/* 26/11 · Registro central de escuchas en tiempo real. Al cerrar sesión se apagan TODAS antes de salir:
   antes quedaban vivas, Firebase las cortaba por falta de permiso y aparecía «Error cargando notificaciones:
   Missing or insufficient permissions» en la pantalla de inicio. Un error mientras se cierra la sesión no se muestra. */
const _escuchas = new Set();
let _cerrandoSesion = false;
function onSnapshot(...args){
  const iNext = args.findIndex(a => typeof a === 'function');
  if (iNext >= 0 && typeof args[iNext + 1] === 'function') {
    const onErr = args[iNext + 1];
    args[iNext + 1] = err => { if (_cerrandoSesion || !currentUser) { console.info('Escucha cerrada al salir:', err?.code); return; } onErr(err); };
  } else if (iNext >= 0) {
    args.splice(iNext + 1, 0, err => { if (_cerrandoSesion || !currentUser) return; console.warn('Escucha en tiempo real:', err?.code, err?.message); });
  }
  const u = _fsOnSnapshot(...args);
  const quitar = () => { _escuchas.delete(quitar); try { u(); } catch (e) {} };
  _escuchas.add(quitar);
  return quitar;
}
window.__escuchasActivas = () => _escuchas.size;
function cerrarEscuchas(){ [..._escuchas].forEach(q => q()); _escuchas.clear(); }
async function salirDeBoe(){ _cerrandoSesion = true; cerrarEscuchas(); try { await signOut(auth); } finally { setTimeout(() => { _cerrandoSesion = false; }, 1500); } }

