  document.getElementById('uaBody').innerHTML = html;
  const ok = document.getElementById('uaOk'); ok.textContent = okTxt; ok.className = 'btn ' + okClase; ok.disabled = false; ok.style.display = okTxt ? '' : 'none';
  document.getElementById('uaModal').classList.add('open');
