let menuGrupos = [];          // [{ id, nombre, modulos:[claves], colapsado }]
const menuGruposColapsado = {};



/* Grupos del menú — documento uiPrefs/menuGruposV2 (compartido por todos los usuarios y equipos).
   · Antes se usaba uiPrefs/menuGrupos: una pestaña abierta con una versión vieja de la app lo reescribía con su copia
     antigua y los módulos recién añadidos «se salían». Las versiones viejas solo conocen ese documento, así que ya no
     pueden pisar el nuevo. Si el nuevo aún no existe, se parte del viejo (sin escribir al cargar).
   · Cada cambio es una transacción (lee, aplica y guarda de forma atómica) y todos los equipos lo ven en vivo. */
const MENU_DOC = 'menuGruposV2', MENU_DOC_VIEJO = 'menuGrupos';
let _menuGruposVivo = false;
async function cargarMenuGrupos(){
  const ok = await leerMenuGruposServidor();
  if (!ok) menuGrupos = [];
  renderMenuGrupos();
  if (!_menuGruposVivo) { _menuGruposVivo = true;
    onSnapshot(doc(db,'uiPrefs',MENU_DOC), snap => {
      if (!snap.exists()) return;
      menuGrupos = JSON.parse(JSON.stringify(snap.data()?.grupos || []));
      dedupMenuGrupos(); _menuGruposCargado = true;
      renderMenuGrupos();
    }, err => console.warn('Menú en vivo no disponible:', err));
  }
}
/* Lee el estado real del servidor. Devuelve false si no se pudo leer. */
async function leerMenuGruposServidor(){
  try {
    let snap = await getDoc(doc(db,'uiPrefs',MENU_DOC));
    if (!snap.exists()) snap = await getDoc(doc(db,'uiPrefs',MENU_DOC_VIEJO));
    menuGrupos = snap.exists() ? JSON.parse(JSON.stringify(snap.data()?.grupos || [])) : [];
    dedupMenuGrupos();
    _menuGruposCargado = true;
    return true;
  } catch(e){ console.warn('Error al cargar grupos de menú:', e); _menuGruposCargado = false; return false; }
}

/* Deja cada módulo en UN solo grupo (el primero donde aparezca). Solo en memoria.
   No borra grupos ni claves de módulos que esta versión no conozca (se conservan tal cual en la base). */
function dedupMenuGrupos(){
  const vistos = new Set();
  let cambio = false;
  menuGrupos.forEach(g => {
    const limpio = [];
    (g.modulos||[]).forEach(m => {
      if (vistos.has(m)) { cambio = true; return; }  // ya está en otro grupo → quitar duplicado
      vistos.add(m);
      limpio.push(m);
    });
    g.modulos = limpio;
  });
  return cambio;
}

let _menuGruposCargado = false;   // true una vez que se leyeron desde la BD
const _menuGrupoLimpio = gs => gs.map(g => ({ id:g.id, nombre:g.nombre, modulos:[...(g.modulos||[])] }));
/* Todo cambio del menú pasa por aquí, en una transacción: lee el estado real, aplica el cambio y guarda.
   Un cambio hecho al mismo tiempo en otro equipo no se pierde (Firestore repite la transacción). Devuelve true si quedó guardado. */
let _menuGruposOcupado = false;
async function mutarMenuGrupos(cambio){
  if (_menuGruposOcupado) return false;
  _menuGruposOcupado = true;
  const NADA = 'sin-cambio';
  try {
    await runTransaction(db, async tx => {
      const ref = doc(db,'uiPrefs',MENU_DOC);
      let s = await tx.get(ref);
      if (!s.exists()) s = await tx.get(doc(db,'uiPrefs',MENU_DOC_VIEJO));   // primera vez: se parte del documento anterior
      menuGrupos = s.exists() ? JSON.parse(JSON.stringify(s.data()?.grupos || [])) : [];
      dedupMenuGrupos();
      if (cambio() === false) throw new Error(NADA);
      tx.set(ref, { grupos: _menuGrupoLimpio(menuGrupos), esquema: 2, updatedAt: serverTimestamp(), por: currentProfile?.nombreCompleto || currentUser?.email || '' });
    });
    _menuGruposCargado = true;
    renderMenuGrupos();
    return true;
  } catch(e){
    if (e?.message !== NADA) {
      console.warn('No se pudo guardar grupos de menú:', e);
      toast('No se guardó el menú: ' + (e?.code === 'permission-denied' ? 'tu usuario no tiene permiso para cambiarlo.' : (e?.message || 'error de conexión.')), 'error');
    }
    await leerMenuGruposServidor();   // volver a mostrar lo que de verdad está guardado
    renderMenuGrupos();
    return false;
  } finally { _menuGruposOcupado = false; }
}

/* Render de los grupos-carpeta en el menú */
function renderMenuGrupos(){
  const cont = document.getElementById('menuGruposContainer');
  const div  = document.getElementById('menuGruposDivider');
  if (!cont) return;
  if (!menuGrupos.length){ cont.innerHTML=''; if(div) div.style.display='none'; sincronizarModulosFijos(); return; }
  if (div) div.style.display='block';

  cont.innerHTML = menuGrupos.map((g, gi)=>{
    const colap = menuGruposColapsado[g.id];
    const items = (g.modulos||[]).map((clave, mi)=>{
      const mod = MODULOS_CATALOGO[clave];
      if (!mod) return '';
      return `<a class="nav-item nav-item-grupo" draggable="true"
        data-grupo="${g.id}" data-modulo="${clave}" data-mi="${mi}"
        ondragstart="menuModDragStart(event)" ondragover="menuModDragOver(event)" ondrop="menuModDrop(event)" ondragend="menuModDragEnd(event)"
        onclick="navigate('${clave}',this)">
        <i class="fa-solid ${mod.icon}"></i><span>${escHtml(mod.label)}</span></a>`;
    }).join('');
    return `<div class="menu-grupo ${colap?'colapsado':''}" data-gid="${g.id}">
      <div class="menu-grupo-head" draggable="true"
        data-gi="${gi}" data-gid="${g.id}"
        ondragstart="menuGrupoDragStart(event)" ondragover="menuGrupoDragOver(event)" ondrop="menuGrupoDrop(event)" ondragend="menuGrupoDragEnd(event)">
        <span onclick="toggleMenuGrupo('${g.id}')" style="display:flex;align-items:center;gap:8px;flex:1;cursor:pointer">
          <i class="fa-solid fa-chevron-down menu-grupo-chevron"></i>
          <i class="fa-solid fa-folder menu-grupo-folder"></i>
          <span class="menu-grupo-nombre">${escHtml(g.nombre)}</span>
        </span>
        <button onclick="event.stopPropagation();openMenuGrupoModal('${g.id}')" title="Editar" class="menu-grupo-btn"><i class="fa-solid fa-pen"></i></button>
        <button onclick="event.stopPropagation();replicarMenuGrupo('${g.id}')" title="Replicar grupo" class="menu-grupo-btn"><i class="fa-solid fa-copy"></i></button>
        <button onclick="event.stopPropagation();eliminarMenuGrupo('${g.id}')" title="Eliminar" class="menu-grupo-btn del"><i class="fa-solid fa-trash"></i></button>
      </div>
      <div class="menu-grupo-items">${items}</div>
    </div>`;
  }).join('');

  sincronizarModulosFijos();
  // Reaplicar permisos: los grupos recién renderizados deben respetar las vistas autorizadas
  if (typeof aplicarPermisosMenu==='function' && !esAdmin && permisosUsuario!==null) aplicarPermisosMenu();
}

/* Oculta del menú fijo los módulos que ya están dentro de algún grupo
   (evita que aparezcan duplicados: una vez en el grupo y otra abajo). */
function sincronizarModulosFijos(){
  // Claves de todos los módulos que están dentro de algún grupo
  const enGrupos = new Set();
  menuGrupos.forEach(g => (g.modulos||[]).forEach(m => enGrupos.add(m)));

  // Recorrer los ítems fijos del menú (los que llaman navigate('clave',this))
  Object.keys(MODULOS_CATALOGO).forEach(clave => {
    const item = document.querySelector(`.sidebar-nav > .nav-item[onclick*="'${clave}'"]`);
    if (item) item.style.display = enGrupos.has(clave) ? 'none' : '';
  });

  // Ocultar etiquetas de sección (Principal/Gestión/Análisis) que quedaron sin ítems visibles
  sincronizarEtiquetasSeccion();
}

/* Oculta una etiqueta de sección si todos sus ítems están ocultos */
function sincronizarEtiquetasSeccion(){
  const nav = document.querySelector('.sidebar-nav');
  if (!nav) return;
  const hijos = [...nav.children];
  const esEtiqueta = (el) => el.classList.contains('nav-group-label')
    || (el.tagName === 'DIV' && el.querySelector('.nav-group-label'));

  hijos.forEach((el, i) => {
    if (!esEtiqueta(el)) return;
    // La sección "Principal" (div con botón +) nunca se oculta: tiene el botón de crear grupo
    if (el.tagName === 'DIV' && el.querySelector('.nav-group-label')) return;
    // ¿Hay algún nav-item visible entre esta etiqueta y la siguiente?
    let hayVisible = false;
    for (let j=i+1; j<hijos.length; j++){
      const sib = hijos[j];
      if (esEtiqueta(sib)) break;
      if (sib.classList.contains('nav-item') && sib.style.display !== 'none'){ hayVisible = true; break; }
    }
    el.style.display = hayVisible ? '' : 'none';
  });
}

window.toggleMenuGrupo = (gid) => {
  menuGruposColapsado[gid] = !menuGruposColapsado[gid];
  const el = document.querySelector(`.menu-grupo[data-gid="${gid}"]`);
  if (el) el.classList.toggle('colapsado', menuGruposColapsado[gid]);
};

/* ── Modal crear/editar grupo ── */
let _editMenuGrupoId = null;
window.openMenuGrupoModal = (gid=null) => {
  _editMenuGrupoId = gid;
  const g = gid ? menuGrupos.find(x=>x.id===gid) : null;
  document.getElementById('menuGrupoTitle').textContent = g ? 'Editar grupo' : 'Nuevo grupo de menú';
  document.getElementById('menuGrupoNombre').value = g?.nombre || '';
  // Render de checkboxes de módulos, en orden si edita
  const seleccionados = g?.modulos || [];
  const orden = [...seleccionados.filter(k=>MODULOS_CATALOGO[k]), ...Object.keys(MODULOS_CATALOGO).filter(k=>!seleccionados.includes(k))];
  document.getElementById('menuGrupoModulos').innerHTML = orden.map(clave=>{
    const mod = MODULOS_CATALOGO[clave];
    const chk = seleccionados.includes(clave) ? 'checked' : '';
    const sinPermiso = typeof puedeVer === 'function' && !puedeVer(clave);
    return `<label class="menu-mod-check">
      <input type="checkbox" value="${clave}" ${chk}/>
      <i class="fa-solid ${mod.icon}"></i> ${escHtml(mod.label)}${sinPermiso ? ' <small class="menu-mod-sinperm" title="Tu usuario no tiene permiso para esta vista: queda en el grupo pero no la verás">(sin permiso para tu usuario)</small>' : ''}
    </label>`;
  }).join('');
  document.getElementById('menuGrupoModal').classList.add('open');
};
window.closeMenuGrupoModal = () => { document.getElementById('menuGrupoModal').classList.remove('open'); _editMenuGrupoId=null; };

window.guardarMenuGrupo = async () => {
  const nombre = document.getElementById('menuGrupoNombre').value.trim();
  if (!nombre) { toast('Ponle un nombre al grupo.','error'); return; }
  const modulos = [...document.querySelectorAll('#menuGrupoModulos input:checked')].map(c=>c.value);
  if (!modulos.length) { toast('Selecciona al menos un módulo.','error'); return; }
  const editId = _editMenuGrupoId;
  const destinoId = editId || ('mg'+Date.now().toString(36));
  const btn = document.querySelector('#menuGrupoModal [onclick="guardarMenuGrupo()"]'); if (btn) btn.disabled = true;
  const ok = await mutarMenuGrupos(() => {
    // ── LÓGICA DE MOVER (no copiar): cada módulo vive en un solo grupo; al asignarlo aquí sale de los demás ──
    const vaciados = new Set();
    menuGrupos.forEach(g => {
      if (g.id === destinoId) return;
      const antes = (g.modulos||[]).length;
      g.modulos = (g.modulos||[]).filter(m => !modulos.includes(m));
      if (antes > 0 && !g.modulos.length) vaciados.add(g.id);
    });
    const g = editId ? menuGrupos.find(x=>x.id===editId) : null;
    if (g) {
      const desconocidos = (g.modulos||[]).filter(m => !MODULOS_CATALOGO[m]);   // módulos que esta versión no conoce: se conservan
      g.nombre = nombre; g.modulos = [...modulos, ...desconocidos];
    } else {
      menuGrupos.push({ id:destinoId, nombre, modulos });   // nuevo (o el grupo fue eliminado en otro equipo: se vuelve a crear)
    }
    // Quitar solo los grupos que quedaron vacíos por este movimiento
    menuGrupos = menuGrupos.filter(x => !vaciados.has(x.id));
  });
  if (btn) btn.disabled = false;
  if (!ok) return;   // el modal queda abierto con lo que se eligió para reintentar
  closeMenuGrupoModal();
  toast('Grupo guardado.','success');
};

window.eliminarMenuGrupo = async (gid) => {
  if (!confirm('¿Eliminar este grupo del menú? Los módulos NO se eliminan, solo la carpeta.')) return;
  if (await mutarMenuGrupos(() => { menuGrupos = menuGrupos.filter(g=>g.id!==gid); })) toast('Grupo eliminado.','success');
};

/* Replicar un grupo del menú (solo estructura visual; los datos NO se tocan).
   Cada módulo vive en un solo grupo, así que la copia nace vacía y se abre para elegir qué módulos pasan a ella
   (antes copiaba los módulos y la copia desaparecía al recargar). */
window.replicarMenuGrupo = async (gid) => {
  const g = menuGrupos.find(x=>x.id===gid);
  if (!g) return;
  const nombre = prompt('Nombre de la nueva sesión (grupo):', g.nombre + ' (copia)');
  if (nombre === null) return;
  const nom = nombre.trim();
  if (!nom) { toast('Nombre vacío.','error'); return; }
  const nuevoId = 'mg'+Date.now().toString(36);
  if (!(await mutarMenuGrupos(() => { menuGrupos.push({ id:nuevoId, nombre:nom, modulos:[] }); }))) return;
  toast(`Grupo "${nom}" creado. Marca los módulos que pertenecen a él.`,'success');
  openMenuGrupoModal(nuevoId);
};

/* ── Drag & drop de MÓDULOS dentro de un grupo ── */
let _dragMod = null;
window.menuModDragStart = (e) => { _dragMod = { grupo:e.target.dataset.grupo, mi:+e.target.dataset.mi }; e.target.classList.add('dragging'); e.stopPropagation(); };
window.menuModDragOver  = (e) => { e.preventDefault(); };
window.menuModDrop = (e) => {
  e.preventDefault(); e.stopPropagation();
  const destino = e.target.closest('.nav-item-grupo');
  if (!destino || !_dragMod) return;
  const g = menuGrupos.find(x=>x.id===_dragMod.grupo);
  if (!g || destino.dataset.grupo !== _dragMod.grupo) return;  // solo dentro del mismo grupo
  const from = _dragMod.mi, to = +destino.dataset.mi;
  if (from===to) return;
  const gid = g.id, clave = g.modulos[from], claveDestino = g.modulos[to];
  mutarMenuGrupos(() => {
    const gg = menuGrupos.find(x=>x.id===gid); if (!gg) return false;
    const i = gg.modulos.indexOf(clave), j = gg.modulos.indexOf(claveDestino);
    if (i < 0 || j < 0) return false;
    gg.modulos.splice(i,1); gg.modulos.splice(j,0,clave);
  });
};
window.menuModDragEnd = (e) => { e.target.classList.remove('dragging'); _dragMod=null; };

/* ── Drag & drop de GRUPOS (reordenar sesiones) ── */
let _dragGrupo = null;
window.menuGrupoDragStart = (e) => { _dragGrupo = +e.currentTarget.dataset.gi; e.currentTarget.classList.add('dragging'); };
window.menuGrupoDragOver  = (e) => { e.preventDefault(); };
window.menuGrupoDrop = (e) => {
  e.preventDefault();
  const destino = e.currentTarget;
  // Reordenar grupos
  const to = +destino.dataset.gi;
  if (_dragGrupo===null || _dragGrupo===to) return;
  const idMover = menuGrupos[_dragGrupo]?.id, idDestino = menuGrupos[to]?.id;
  if (!idMover || !idDestino) return;
  mutarMenuGrupos(() => {
    const i = menuGrupos.findIndex(x=>x.id===idMover), j = menuGrupos.findIndex(x=>x.id===idDestino);
    if (i < 0 || j < 0) return false;
    const [g] = menuGrupos.splice(i,1); menuGrupos.splice(j,0,g);
  });
};
window.menuGrupoDragEnd = (e) => { e.currentTarget.classList.remove('dragging'); _dragGrupo=null; };


/* Reenviar datos al iframe de Reportes cada vez que se entra a la vista
   (el iframe puede haber enviado IFRAME_READY antes de que los datos
    estuvieran disponibles, perdiéndose el primer envío) */
async function reenviarDatosReportes() {
  const frame = document.getElementById('repFrame');
  if (!frame?.contentWindow) return;
  try {
    const [factSnap, docSnap] = await Promise.all([
      getDocs(collection(db,'facturas')),
      getDocs(collection(db,'doctors')),
    ]);
    const facturas = factSnap.docs
      .map(d=>({id:d.id,...d.data()}))
      .sort((a,b)=>(b.createdAt?.seconds||0)-(a.createdAt?.seconds||0));
    const docsList = docSnap.docs.map(d=>({id:d.id,...d.data()}));
    if (docsList.length) doctors = docsList;
    frame.contentWindow.postMessage({
      type: 'FACTURAS_UPDATE',
      facturas,
      doctors: docsList.map(d=>({id:d.id, nombre:d.nombre, especialidad:d.especialidad}))
    }, '*');
    sendDoctorStyles(frame);
  } catch(e) {
    console.warn('No se pudieron reenviar datos a Reportes:', e);
  }
}
window.setBottomActive = el => { document.querySelectorAll('.bottom-nav-item').forEach(i=>i.classList.remove('active')); el.classList.add('active'); };
window.toggleSidebar = () => {
  const sb=document.getElementById('sidebar'), sh=document.getElementById('appShell'), ov=document.getElementById('sidebarOverlay');
  if(window.innerWidth<=768){ const open=sb.classList.toggle('mobile-open'); ov.classList.toggle('open',open); }
  else{ const col=sb.classList.toggle('collapsed'); sh.classList.toggle('full',col); }
};
window.refreshAll = () => { renderDashboard(); filterDoctors(); renderKanban(); applyTareaFilters(); renderEquipo(); updateNavBadges(); toast('Actualizado.','success'); };

/* ── CLOCK ── */
function startClock(){
  const el=document.getElementById('topbarClock');
  const tick=()=>el.textContent=new Date().toLocaleDateString('es-CO',{weekday:'short',day:'2-digit',month:'short'})+' · '+new Date().toLocaleTimeString('es-CO',{hour:'2-digit',minute:'2-digit'});
  tick(); setInterval(tick,10000);
}

/* ── DASHBOARD ── */
/* ═══════════════════════════════════════════════════════════════════════
   DASHBOARD 3D (dashboard3d.js, Three.js cargado bajo demanda).
   Usa los datos que ya están en memoria (doctors, formatos, tareas, teamMembers):
   no hace lecturas adicionales a Firebase.
═══════════════════════════════════════════════════════════════════════ */
let _d3 = null, _d3Cargando = false, _d3Fallo = false;
function dash3dDatos(){
  const hoy = new Date(); const hoyISO = hoy.getFullYear()+'-'+String(hoy.getMonth()+1).padStart(2,'0')+'-'+String(hoy.getDate()).padStart(2,'0');
  const norm = s => String(s||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
  const tildes = s => String(s).normalize('NFD').length - String(s).length;
  // Especialidades unificadas (mayúsculas, tildes y espacios): solo para mostrar
  const grupos = new Map();
  doctors.forEach(d=>{
    const nombre = String(d.especialidad||'').trim() || 'Sin especialidad';
    const k = norm(nombre) || 'sin especialidad';
    const g = grupos.get(k) || { clave:k, total:0, activos:0, inactivos:0, conteo:{} };
    g.total++; if (d.estado==='Activo') g.activos++; else if (d.estado==='Inactivo') g.inactivos++;
    g.conteo[nombre] = (g.conteo[nombre]||0)+1; grupos.set(k, g);
  });
  let especialidades = [...grupos.values()].map(g=>{
    const variantes = Object.keys(g.conteo).sort((a,b)=>(g.conteo[b]-g.conteo[a]) || (tildes(b)-tildes(a)));
    return { clave:g.clave, nombre:variantes[0], variantes, total:g.total, activos:g.activos, inactivos:g.inactivos };
  }).sort((a,b)=>b.total-a.total || a.nombre.localeCompare(b.nombre,'es'));
  const especialidadesTotal = especialidades.filter(e=>e.clave!=='sin especialidad').length;
  if (especialidades.length > 8){
    const resto = especialidades.slice(7);
    especialidades = especialidades.slice(0,7).concat([{ clave:'otras', nombre:'Otras ('+resto.length+')', variantes:resto.map(e=>e.nombre),
      total:resto.reduce((s,e)=>s+e.total,0), activos:resto.reduce((s,e)=>s+e.activos,0), inactivos:resto.reduce((s,e)=>s+e.inactivos,0) }]);
  }
  const pend = formatos.filter(f=>f.status==='Pendiente').length, rev = formatos.filter(f=>f.status==='En revisión').length, listo = formatos.filter(f=>f.status==='Listo').length;
  const abiertos = formatos.filter(f=>f.status!=='Listo');
  const uid = currentUser?.uid;
  const tareasDe = id => tareas.filter(t=>t.asignadoId===id);
  const resumenT = lista => { const ab = lista.filter(t=>t.estado!=='Completada');
    return { pend:ab.length, urgentes:ab.filter(t=>t.prioridad==='Urgente').length, vencidas:ab.filter(t=>t.fecha && t.fecha<hoyISO).length,
      hoy:ab.filter(t=>t.fecha===hoyISO).length, comp:lista.length-ab.length,
      proximas:ab.filter(t=>t.fecha).sort((a,b)=>a.fecha.localeCompare(b.fecha)).slice(0,3).map(t=>(t.titulo||'Tarea')+' · '+t.fecha.slice(8,10)+'/'+t.fecha.slice(5,7)) }; };
  const mias = resumenT(tareasDe(uid));
  // Facturación (UROEXPERTOS original, ya cargado en memoria)
  const verFact = puedeVer('egresos');
  const madres = verFact ? egresos : [];
  const sinPagar = madres.filter(e=>!e.fechaPago);
  return {
    facturacion: { permitido:verFact, madres:madres.length, pagadas:madres.length-sinPagar.length, pendientes:sinPagar.length,
      hijas: madres.reduce((s,e)=>s+(e.hijas||[]).length,0), valorPendiente: sinPagar.reduce((s,e)=>s+(Number(e.valorEspecialista)||0),0) },
    actualizado: Date.now(),
    doctores: { total:doctors.length, activos:doctors.filter(d=>d.estado==='Activo').length, inactivos:doctors.filter(d=>d.estado==='Inactivo').length },
    especialidades, especialidadesTotal,
    procesos: { pend, rev, listo, total:formatos.length, avance: formatos.length ? Math.round(listo*100/formatos.length) : 0,
      vencidos: abiertos.filter(f=>f.fecha && f.fecha<hoyISO).length, urgentes: abiertos.filter(f=>f.prioridad==='Urgente').length },
    tareas: mias,
    equipo: teamMembers.map(m=>{ const id = m.uid||m.id; const r = resumenT(tareasDe(id));
      return { uid:id, nombre:m.nombreCompleto||m.email||'Usuario', ini:initials(m.nombreCompleto||m.email||'?'), rol:m.rol||'', color:m.color||'#1757a8',
        pend:r.pend, venc:r.vencidas, urg:r.urgentes, comp:r.comp }; }),
  };
}
function renderDashboard(){
  const host = document.getElementById('d3Host'); if (!host) return;
  if (!puedeVer('dashboard')) return;   // sin permiso: no descarga Three.js
  const datos = dash3dDatos();
  if (_d3) { _d3.actualizar(datos); return; }
  if (_d3Fallo) { dash3dRespaldo(host, datos); return; }
  if (_d3Cargando) return;
  _d3Cargando = true;
  host.innerHTML = '<div class="d3-cargando"><i class="fa-solid fa-cube fa-spin"></i><p>Construyendo tu negocio en 3D…</p></div>';
  import('./dashboard3d.js?v=20261019e')
    .then(m => m.montar(host, dash3dDatos()))
    .then(ctrl => { _d3 = ctrl; })
    .catch(e => { console.warn('Dashboard 3D no disponible, se muestra la versión simple:', e); _d3Fallo = true; dash3dRespaldo(host, dash3dDatos()); })
    .finally(() => { _d3Cargando = false; });
}
/* Respaldo si el navegador no soporta 3D (WebGL) o no cargó la librería: mismos datos en tarjetas */
function dash3dRespaldo(host, d){
  const f = d.facturacion;
  const tarj = (titulo, ic, filas) => '<div class="d3-r-card"><div class="d3-r-tit"><i class="fa-solid '+ic+'"></i> '+titulo+'</div>'
    + filas.map(x=>'<div class="d3-r-fila'+(x[2]?' alerta':'')+'"><span>'+escHtml(x[0])+'</span><b>'+escHtml(String(x[1]))+'</b></div>').join('')+'</div>';
  host.innerHTML = '<div class="d3-r-aviso"><i class="fa-solid fa-circle-info"></i> Tu navegador no pudo mostrar la vista 3D; estos son los mismos datos.</div><div class="d3-r-grid">'
    + tarj('Clientes','fa-user-doctor',[['Doctores',d.doctores.total],['Activos',d.doctores.activos],['Inactivos',d.doctores.inactivos],['Especialidades',d.especialidadesTotal]])
    + (f.permitido ? tarj('Facturación','fa-file-invoice',[['Facturas a la entidad',f.madres],['Liquidaciones de especialistas',f.hijas],['Pagadas',f.pagadas],['Pendientes de pago',f.pendientes,f.pendientes>0]]) : '')
    + tarj('Equipo','fa-users',[['Usuarios',d.equipo.length]].concat(d.equipo.slice(0,8).map(m=>[m.nombre, m.rol||'Usuario'])))
    + '</div>';
}

/* ── DOCTORS ── */
window.filterDoctors = () => {
  const q=(document.getElementById('searchDoctor')?.value||'').toLowerCase();
  const est=document.getElementById('filterEstado')?.value||'';
  let list=[...doctors];
  if(q) list=list.filter(d=>(d.nombre||'').toLowerCase().includes(q)||(d.especialista||'').toLowerCase().includes(q)||(d.especialidad||'').toLowerCase().includes(q)||(d.entidad||'').toLowerCase().includes(q)
    || cliRazones(d).some(r => { const e = cliRazonEfectiva(d, r); return String(e.razonSocial||'').toLowerCase().includes(q) || (entNitLimpio(q).length >= 4 && entNitLimpio(e.documento).includes(entNitLimpio(q))); }));
  if (est === 'incompletos') list = list.filter(d => !d.unidaA && !d.reclasificada && d.estado !== 'Inactivo' && ['especialista','residente',''].includes(d.tipoCliente||'') && !cliDatosCompletos(d));
  else if (est.startsWith('tipo:')) list = list.filter(d => (d.tipoCliente||'') === est.slice(5));
  else if(est) list=list.filter(d=>d.estado===est);
  const tbody=document.getElementById('doctorsBody'), empty=document.getElementById('emptyDoctors'), table=document.getElementById('doctorsTable');
  if(!list.length){tbody.innerHTML='';empty.style.display='block';table.style.display='none';return;}
  empty.style.display='none';table.style.display='table';

  const filaCliente = (d) => {
    const accCount=d.accesos?.length||0;
    const logoCell = d.logoBase64
      ? `<div class="doc-av has-logo"><img src="${d.logoBase64}" alt="logo"/></div>`
      : `<div class="doc-av" style="background:${avatarColor(d.nombre)}">${initials(d.nombre)}</div>`;
    const rp = cliRazonPred(d), ep = cliRazonEfectiva(d, rp), falt = cliFaltantes(d, rp), nRz = cliRazones(d).length;
    const tipoLbl = (CLI_TIPOS.find(t => t[0] === d.tipoCliente)||[])[1];
    return `<tr data-cli-group="${escHtml(d.grupo||'')}"${d.unidaA ? ' class="cli-unida"' : ''}>
    <td><div class="doc-cell">${logoCell}<div><div class="doc-name">${escHtml(d.especialista || d.nombre)}</div><div style="font-size:11px;color:var(--gray-3)">${escHtml([d.especialista && _nrm(d.especialista) !== _nrm(d.nombre) ? d.nombre : '', tipoLbl || 'Sin clasificar', d.especialidad].filter(Boolean).join(' · '))}</div></div></div></td>
    <td>${escHtml(ep?.razonSocial || '—')}${nRz > 1 ? ` <span class="cli-mas" title="${nRz} razones sociales">+${nRz - 1}</span>` : ''}</td>
    <td class="cli-doc">${ep?.documento ? escHtml(entNitTexto(ep.documento, ep.tipoPersona === 'juridica' ? entDvCalc(ep.documento) : '')) : '—'}</td>
    <td>${ep?.regimen ? (ep.regimen === 'simple' ? 'Simple' : 'Ordinario') : '—'}</td>
    <td>${escHtml(ep?.banco || '—')}</td>
    <td>${d.unidaA ? '<span class="cli-est gris">Unida</span>' : d.reclasificada ? `<span class="cli-est gris">${{ entidad:'Es entidad', empresa:'Es la empresa', no_cliente:'No es cliente' }[d.reclasificada] || 'Reclasificada'}</span>` : falt.length ? `<span class="cli-est mal" title="Falta: ${escHtml(falt.join(', '))}">Incompleto</span>` : '<span class="cli-est ok">Completo</span>'}${cliRazones(d).some(cliCambioPendiente) ? ' <span class="cli-est mal" title="Cambio de cuenta sin aprobar">Cuenta por aprobar</span>' : ''}</td>
    <td><span class="badge badge-${d.estado==='Activo'?'active':'inactive'}">${d.estado||'—'}</span></td>
    <td><div class="tbl-actions"><button class="act-btn" title="Mover a grupo" style="background:var(--blue-pale);color:var(--blue)" onclick="openMoverClienteGrupo('${d.id}')"><i class="fa-solid fa-folder"></i></button><button class="act-btn edit" onclick="openDoctorModal('${d.id}')"><i class="fa-solid fa-pen"></i></button><button class="act-btn del" onclick="deleteDoctor('${d.id}')"><i class="fa-solid fa-trash"></i></button></div></td>
  </tr>`;
  };

  // Si hay búsqueda activa, mostrar lista plana (búsqueda independiente del grupo)
  if (q) {
    tbody.innerHTML = list.map(filaCliente).join('');
    return;
  }

  // ── Agrupar clientes por su campo "grupo" ──
  const mapa = new Map();
  list.forEach(d => {
    const g = (d.grupo||'').trim() || '__singrupo__';
    if (!mapa.has(g)) mapa.set(g, []);
    mapa.get(g).push(d);
  });
  // Orden: grupos alfabéticos primero, "Sin grupo" al final
  const claves = [...mapa.keys()].sort((a,b)=>{
    if (a==='__singrupo__') return 1;
    if (b==='__singrupo__') return -1;
    return a.localeCompare(b,'es');
  });

  tbody.innerHTML = claves.map(clave => {
    const grupoNom = clave==='__singrupo__' ? 'Sin grupo' : clave;
    const items = mapa.get(clave);
    const colapsado = clienteGrupoColapsado[clave] ? 'colapsado' : '';
    const cab = `<tr class="tbl-group-row cli-group-row ${colapsado}" data-cligroup="${escHtml(clave)}" onclick="toggleClienteGrupo('${escHtml(clave)}',this)">
      <td colspan="8" class="tbl-group-cell">
        <i class="fa-solid fa-chevron-down tbl-group-chevron"></i>
        <i class="fa-solid fa-folder-open tbl-group-folder"></i>
        <span class="tbl-group-label">${escHtml(grupoNom)}</span>
        <span class="tbl-group-count">${items.length} cliente${items.length!==1?'s':''}</span>
      </td>
      <td></td>
    </tr>`;
    const filas = items.map(d => filaCliente(d).replace('<tr ', `<tr data-cligroup-row="${escHtml(clave)}" `)).join('');
    return cab + filas;
  }).join('');

  // Aplicar estado colapsado
  claves.forEach(clave => {
    if (clienteGrupoColapsado[clave]) {
      tbody.querySelectorAll(`tr[data-cligroup-row="${cssEscapa(clave)}"]`).forEach(tr=>tr.style.display='none');
    }
  });
};

/* Estado de grupos de clientes (colapsado) + persistencia */
const clienteGrupoColapsado = {};
window.toggleClienteGrupo = (clave, cab) => {
  const colapsar = !clienteGrupoColapsado[clave];
  clienteGrupoColapsado[clave] = colapsar;
  cab.classList.toggle('colapsado', colapsar);
  document.querySelectorAll(`#doctorsBody tr[data-cligroup-row="${cssEscapa(clave)}"]`).forEach(tr=>{
    tr.style.display = colapsar ? 'none' : '';
  });
  // Persistir
  clearTimeout(_cliGrupoTimer);
  _cliGrupoTimer = setTimeout(()=>{
    const cerrados={}; Object.keys(clienteGrupoColapsado).forEach(k=>{if(clienteGrupoColapsado[k])cerrados[k]=true;});
    setDoc(doc(db,'uiPrefs','clienteGrupos'),{colapsados:cerrados,updatedAt:serverTimestamp()}).catch(()=>{});
  },500);
};
let _cliGrupoTimer = null;

/* Mover un cliente a un grupo (crea el grupo si no existe) */
window.openMoverClienteGrupo = (clienteId) => {
  const d = doctors.find(x=>x.id===clienteId);
  if (!d) return;
  const gruposExistentes = [...new Set(doctors.map(x=>(x.grupo||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'es'));
  _moverClienteId = clienteId;
  const sel = document.getElementById('moverGrupoSelect');
  sel.innerHTML = '<option value="">— Sin grupo —</option>'
    + gruposExistentes.map(g=>`<option value="${escHtml(g)}" ${g===(d.grupo||'')?'selected':''}>${escHtml(g)}</option>`).join('');
  document.getElementById('moverGrupoNuevo').value = '';
  document.getElementById('moverClienteNombre').textContent = d.nombre;
  document.getElementById('moverGrupoModal').classList.add('open');
};
let _moverClienteId = null;
window.closeMoverGrupoModal = () => { document.getElementById('moverGrupoModal').classList.remove('open'); _moverClienteId=null; };
window.guardarMoverGrupo = async () => {
  if (!_moverClienteId) return;
  const nuevo = document.getElementById('moverGrupoNuevo').value.trim();
  const sel   = document.getElementById('moverGrupoSelect').value;
  const grupo = nuevo || sel;   // el nombre nuevo tiene prioridad
  try {
    await updateDoc(doc(db,'doctors',_moverClienteId), { grupo });
    toast(grupo ? `Cliente movido a "${grupo}".` : 'Cliente sin grupo.', 'success');
    closeMoverGrupoModal();
  } catch(e){ toast('Error: '+e.message,'error'); }
};
/* ═════════════════════════════════════════════════════════════════
   CLIENTES · FICHA DEL ESPECIALISTA — FACTURACIÓN Y PAGO (doc. 18 nov 2026, sección 4)
   · tipoCliente: especialista | residente | empresa ('' = sin clasificar).
   · razones: una o más razones sociales «Paga a» por especialista (honorarios a su nombre, equipos por su SAS…),
     cada una con tipo de persona, documento (+DV), régimen, banco, tipo y número de cuenta, adjuntos y una predeterminada.
   · Los campos sueltos de siempre (nit, banco, nCuenta, tipoCuenta, regimenTrib) se siguen guardando con los datos de la
     razón predeterminada, para que el resto de la app funcione igual.
   · Fichas antiguas sin razones: se muestra una razón armada con sus datos (sin escribir nada hasta que se guarde).
   · Cambio de cuenta: queda registrado (quién, cuándo, valor anterior), exige certificado bancario nuevo y la siguiente
     orden de pago sale NO APTA hasta que OTRA persona lo apruebe.
═════════════════════════════════════════════════════════════════ */
const CLI_TIPOS = [['especialista','Especialista'],['residente','Residente'],['empresa','Empresa del grupo']];
const CLI_BANCOS = ['Bancolombia','Banco de Bogotá','Davivienda','BBVA','Banco de Occidente','Banco Popular','Banco AV Villas','Banco Caja Social',
  'Scotiabank Colpatria','Banco Agrario','Itaú','Banco GNB Sudameris','Banco Pichincha','Bancoomeva','Banco Falabella','Banco Finandina',
  'Banco Serfinanza','Banco W','Bancamía','Banco Mundo Mujer','Lulo Bank','Nu Colombia','Nequi','Daviplata','Coltefinanciera','Confiar','JFK Cooperativa','Otro'];
const CLI_LARGO_CUENTA = { 'Bancolombia': 11 };   // validación de longitud por banco (aviso, no bloquea)
const CLI_SUFIJOS_JUR = /\b(s\.?\s?a\.?\s?s\.?|sas|s\.?\s?a\.?|ltda\.?|limitada|e\.?\s?u\.?|s\.?\s?c\.?\s?s\.?)\s*$/i;
const cliCuentaLimpia = v => String(v||'').replace(/\D/g,'');   // texto: conserva ceros a la izquierda
/* Número de cuenta normalizado: solo dígitos y, si el banco usa una longitud fija y faltan ceros a la izquierda, se completan
   (Bancolombia «296 - 75613 - 91» → 02967561391) */
function cliCuentaNormal(banco, v){ let n = cliCuentaLimpia(v); const L = CLI_LARGO_CUENTA[banco]; if (L && n && n.length < L && n.length >= L - 2) n = n.padStart(L, '0'); return n; }
const cliUsuario = () => currentProfile?.nombreCompleto || currentUser?.email || '';
/* Solo contabilidad y administración editan banco y cuenta */
function cliPuedeEditarBanco(){ return esAdmin || /contab|contador|admin|gerent/i.test(String(currentProfile?.rol||'')); }
function cliNuevoId(){ return 'rz' + Date.now().toString(36) + Math.random().toString(36).slice(2,6); }
function cliNombrePersona(d){ return String(d?.especialista || d?.nombre || '').trim(); }
/* Razón social armada con los datos antiguos de la ficha (no se guarda hasta que alguien guarde la ficha) */
function cliRazonVirtual(d){
  const jur = CLI_SUFIJOS_JUR.test(String(d?.nombre||'').trim()) && _nrm(d?.nombre) !== _nrm(d?.especialista);
  const nitRaw = String(d?.nit||''), m = nitRaw.match(/^\s*([\d.\s]+)\s*-\s*(\d)\s*$/);
  const regOld = String(d?.regimenTrib||'');
  return { id: 'rz_legado', _virtual: true, tipoPersona: jur ? 'juridica' : 'natural',
    razonSocial: jur ? String(d.nombre).trim() : cliNombrePersona(d),
    documento: entNitLimpio(m ? m[1] : nitRaw), dv: m ? m[2] : (jur && entNitLimpio(nitRaw) ? entDvCalc(entNitLimpio(nitRaw)) : ''),
    regimen: regOld === 'simple' ? 'simple' : (regOld ? 'ordinario' : ''),
    banco: String(d?.banco||'').trim(), tipoCuenta: d?.tipoCuenta || '', nCuenta: cliCuentaLimpia(d?.nCuenta), predeterminada: true };
}
function cliRazones(d){ return Array.isArray(d?.razones) && d.razones.length ? d.razones : (d ? [cliRazonVirtual(d)] : []); }
function cliRazonPred(d){ const rs = cliRazones(d); return rs.find(r => r.predeterminada) || rs[0] || null; }
/* Datos efectivos de una razón (la natural toma nombre y cédula de los datos personales) */
function cliRazonEfectiva(d, r){
  if (!r) return null;
  if (r.tipoPersona === 'natural') return { ...r, razonSocial: cliNombrePersona(d), documento: entNitLimpio(d?.cedula || r.documento), dv: '' };
  return r;
}
function cliFaltantes(d, r){
  const e = cliRazonEfectiva(d, r); if (!e) return ['razón social'];
  const f = [];
  if (!e.razonSocial) f.push('razón social');
  if (!e.documento) f.push(e.tipoPersona === 'juridica' ? 'NIT' : 'cédula');
  if (!e.regimen) f.push('régimen'); if (!e.banco) f.push('banco'); if (!e.tipoCuenta) f.push('tipo de cuenta'); if (!e.nCuenta) f.push('número de cuenta');
  return f;
}
const cliDatosCompletos = d => cliFaltantes(d, cliRazonPred(d)).length === 0;
const cliCambioPendiente = r => !!(r?.cuentaCambio && !r.cuentaCambio.aprobadoISO);
/* Ficha del especialista por su nombre (las liquidaciones enlazan por nombre). Prefiere activas y no unidas. */
function cliDoctorDeEspecialista(nombre){
  const k = _nrm(nombre); if (!k) return null;
  const c = doctors.filter(d => _nrm(d.especialista) === k && !d.unidaA);
  return c.find(d => d.estado !== 'Inactivo') || c[0] || null;
}
function cliRazonDeHija(h){
  const d = cliDoctorDeEspecialista(h?.nombre); if (!d) return { d: null, r: null };
  const rs = cliRazones(d);
  const r = (h?.razonId && rs.find(x => x.id === h.razonId)) || rs.find(x => h?.proveedor && _nrm(cliRazonEfectiva(d, x).razonSocial) === _nrm(h.proveedor)) || cliRazonPred(d);
  return { d, r: cliRazonEfectiva(d, r) };
}
/* Un NIT o cédula no puede estar en dos fichas */
function cliDocumentoEnOtraFicha(docum, idFicha){
  const n = entNitLimpio(docum); if (!n) return null;
  for (const d of doctors) {
    if (d.id === idFicha || d.unidaA) continue;
    if (entNitLimpio(d.cedula) === n) return { d, donde: 'cédula' };
    for (const r of cliRazones(d)) if (entNitLimpio(r.documento) === n) return { d, donde: r.razonSocial || 'razón social' };
  }
  return null;
}

/* ── Editor de razones sociales dentro de la ficha ── */
let cliRazonesLocal = [], cliRazonesOrig = [], _cliAdjPend = {};   // _cliAdjPend[razonId] = { rut:File, cert:File, camara:File }
function cliBancoOpts(sel){
  const lista = sel && !CLI_BANCOS.includes(sel) ? [sel, ...CLI_BANCOS] : CLI_BANCOS;
  return `<option value="">— Banco —</option>` + lista.map(b => `<option ${b === sel ? 'selected' : ''}>${escHtml(b)}</option>`).join('');
}
function cliAdjuntosDe(docId, razonId){
  if (!docId) return [];
  return comprobantes.filter(c => c.egresoId === 'cli_' + docId && c.hid === razonId && c.estado === 'completo')
    .sort((a,b) => String(b.fechaISO).localeCompare(String(a.fechaISO)));
}
function cliRenderRazones(){
  const box = document.getElementById('cliRazones'); if (!box) return;
  const d = { especialista: document.getElementById('dEspecialista').value, nombre: document.getElementById('dNombre').value, cedula: document.getElementById('dCedula').value };
  const docId = editingDoctorId, banco = cliPuedeEditarBanco();
  box.innerHTML = cliRazonesLocal.map((r, i) => {
    const e = cliRazonEfectiva(d, r), nat = r.tipoPersona === 'natural';
    const falt = cliFaltantes(d, r), adj = cliAdjuntosDe(docId, r.id), pend = _cliAdjPend[r.id] || {};
    const adjCelda = (tipo, lbl) => { const ult = adj.find(a => a.tipoDoc === tipo), p = pend[tipo];
      return `<div class="cli-adj"><span class="cli-adj-l">${lbl}</span>${p ? `<span class="cli-adj-f nuevo"><i class="fa-solid fa-paperclip"></i> ${escHtml(p.name)} <small>(se sube al guardar)</small></span>`
        : ult ? `<button type="button" class="cli-adj-f" onclick="compDescargar('${ult.id}')"><i class="fa-solid fa-file-pdf"></i> ${escHtml(ult.nombre)} <small>${escHtml(compFechaHora(ult.fechaISO))}</small></button>` : '<span class="cli-adj-f falta">Sin adjunto</span>'}
        <label class="cli-adj-up"><i class="fa-solid fa-upload"></i><input type="file" accept=".pdf,application/pdf,image/*" onchange="cliAdjElegir('${r.id}','${tipo}',this)" hidden/></label></div>`; };
    const cc = r.cuentaCambio, pendCambio = cliCambioPendiente(r);
    return `<div class="cli-rz${r.predeterminada ? ' pred' : ''}" data-i="${i}">
      <div class="cli-rz-cab">
        <label class="cli-rz-pred"><input type="radio" name="cliPred" ${r.predeterminada ? 'checked' : ''} onchange="cliRazonPredeterminada(${i})"/> Predeterminada</label>
        <span class="cli-rz-estado ${falt.length ? 'mal' : 'ok'}">${falt.length ? `<i class="fa-solid fa-triangle-exclamation"></i> Datos de pago incompletos: ${escHtml(falt.join(', '))}` : '<i class="fa-solid fa-circle-check"></i> Datos de pago completos'}</span>
        ${cliRazonesLocal.length > 1 ? `<button type="button" class="act-btn" title="Quitar esta razón social" aria-label="Quitar razón social" onclick="cliRazonQuitar(${i})"><i class="fa-solid fa-trash"></i></button>` : ''}
      </div>
      <div class="cli-rz-grid">
        <div class="fg"><label>Tipo de persona</label><select onchange="cliRazonCampo(${i},'tipoPersona',this.value)"><option value="natural" ${nat ? 'selected' : ''}>Natural</option><option value="juridica" ${!nat ? 'selected' : ''}>Jurídica (SAS)</option></select></div>
        <div class="fg cli-span2"><label>Razón social («Paga a»)</label><input type="text" value="${escHtml(e.razonSocial||'')}" ${nat ? 'readonly title="Persona natural: es el nombre del especialista"' : ''} placeholder="Ej. UROONCOLOGO SAS" oninput="cliRazonCampo(${i},'razonSocial',this.value,true)"/></div>
        <div class="fg"><label>${nat ? 'Cédula' : 'NIT'}</label>${nat ? `<input type="text" value="${escHtml(e.documento||'')}" readonly title="Sale de la cédula de los datos personales"/>`
          : `<div class="ent-nit-par"><input type="text" inputmode="numeric" value="${escHtml(r.documento||'')}" placeholder="NIT" oninput="cliRazonCampo(${i},'documento',this.value,true)"/><span>-</span><input type="text" value="${escHtml(r.documento ? entDvCalc(r.documento) : '')}" readonly title="Dígito de verificación calculado por BOE" aria-label="Dígito de verificación"/></div>`}</div>
        <div class="fg"><label>Régimen</label><select onchange="cliRazonCampo(${i},'regimen',this.value)"><option value="">— Elige —</option><option value="simple" ${r.regimen === 'simple' ? 'selected' : ''}>Simple</option><option value="ordinario" ${r.regimen === 'ordinario' ? 'selected' : ''}>Ordinario</option></select>
          <small class="ent-hint">Retención: ${r.regimen ? String(regTarifa(r.regimen)).replace('.', ',') + ' %' : '—'} <a href="#" onclick="event.preventDefault();regAbrir()">tarifas</a></small></div>
        <div class="fg"><label>Banco</label><select ${banco ? '' : 'disabled'} onchange="cliRazonCampo(${i},'banco',this.value)">${cliBancoOpts(r.banco)}</select></div>
        <div class="fg"><label>Tipo de cuenta</label><select ${banco ? '' : 'disabled'} onchange="cliRazonCampo(${i},'tipoCuenta',this.value)"><option value="">— Tipo —</option>${['Ahorros','Corriente', ...(r.tipoCuenta && !['Ahorros','Corriente'].includes(r.tipoCuenta) ? [r.tipoCuenta] : [])].map(t => `<option ${t === r.tipoCuenta ? 'selected' : ''}>${escHtml(t)}</option>`).join('')}</select></div>
        <div class="fg"><label>N° de cuenta</label><input type="text" inputmode="numeric" value="${escHtml(r.nCuenta||'')}" ${banco ? '' : 'readonly'} placeholder="Solo números" oninput="cliRazonCampo(${i},'nCuenta',this.value,true)"/>
          ${(() => { const L = CLI_LARGO_CUENTA[r.banco], n = cliCuentaLimpia(r.nCuenta), nn = cliCuentaNormal(r.banco, r.nCuenta); if (!L || !n) return '';
            if (nn.length !== L) return `<small class="ent-hint warn">${escHtml(r.banco)} usa ${L} dígitos (tiene ${n.length}).</small>`;
            return nn !== n ? `<small class="ent-hint">Se guarda como ${escHtml(nn)} (${L} dígitos).</small>` : ''; })()}</div>
        <div class="fg cli-span2"><label>Titular de la cuenta</label><input type="text" value="${escHtml(e.razonSocial||'')}" readonly title="Es el mismo «Paga a»"/></div>
      </div>
      ${banco ? '' : '<p class="cli-nota"><i class="fa-solid fa-lock"></i> Solo contabilidad y administración pueden editar banco y cuenta.</p>'}
      <div class="cli-adjs">${adjCelda('rut','RUT')}${adjCelda('cert','Certificado bancario')}${nat ? '' : adjCelda('camara','Cámara de comercio')}</div>
      ${pendCambio ? `<div class="cli-cambio"><i class="fa-solid fa-shield-halved"></i> Cambio de cuenta del ${escHtml(compFechaHora(cc.fechaISO))} por ${escHtml(cc.por)}: antes ${escHtml([cc.anterior?.banco, cc.anterior?.tipoCuenta, cc.anterior?.nCuenta].filter(Boolean).join(' · ') || 'sin cuenta')}. <b>La siguiente orden de pago sale NO APTA hasta que otra persona lo apruebe.</b>
          ${banco && cc.porUid !== currentUser?.uid ? `<button type="button" class="uro-btn pri sm" onclick="cliAprobarCambio(${i})">Aprobar cambio</button>` : '<small>(debe aprobarlo otra persona de contabilidad o administración)</small>'}</div>`
        : cc?.aprobadoISO ? `<div class="cli-cambio ok"><i class="fa-solid fa-circle-check"></i> Último cambio de cuenta aprobado por ${escHtml(cc.aprobadoPor)} el ${escHtml(compFechaHora(cc.aprobadoISO))}.</div>` : ''}
    </div>`;
  }).join('') + `<button type="button" class="btn btn-ghost btn-xs" onclick="cliRazonAgregar()"><i class="fa-solid fa-plus"></i> Añadir razón social</button>`;
}
window.cliRenderRazones = cliRenderRazones;
window.cliRazonCampo = (i, k, v, sinRepintar) => {
  const r = cliRazonesLocal[i]; if (!r) return;
  if (k === 'documento') v = entNitLimpio(v);
  if (k === 'nCuenta') v = cliCuentaLimpia(v);
  r[k] = v; delete r._virtual;
  if (k === 'tipoPersona' && v === 'juridica' && r.razonSocial === cliNombrePersona({ especialista: document.getElementById('dEspecialista').value })) r.razonSocial = '';
  if (!sinRepintar) cliRenderRazones();
  else { const card = document.querySelector(`#cliRazones .cli-rz[data-i="${i}"]`); if (card && (k === 'documento')) { const dv = card.querySelector('.ent-nit-par input[readonly]'); if (dv) dv.value = v ? entDvCalc(v) : ''; } }
};
window.cliRazonAgregar = () => { cliRazonesLocal.push({ id: cliNuevoId(), tipoPersona: 'juridica', razonSocial: '', documento: '', regimen: '', banco: '', tipoCuenta: '', nCuenta: '', predeterminada: !cliRazonesLocal.length }); cliRenderRazones(); };
window.cliRazonQuitar = (i) => {
  const r = cliRazonesLocal[i]; if (!r) return;
  const usos = egresos.reduce((t, e) => t + (e.hijas||[]).filter(h => h.razonId === r.id).length, 0);
  if (usos) { toast(`Esa razón social está en ${usos} liquidación(es); no se puede quitar.`, 'error'); return; }
  if (!confirm(`¿Quitar la razón social «${r.razonSocial || 'sin nombre'}»?`)) return;
  cliRazonesLocal.splice(i, 1);
  if (!cliRazonesLocal.some(x => x.predeterminada) && cliRazonesLocal[0]) cliRazonesLocal[0].predeterminada = true;
  cliRenderRazones();
};
window.cliRazonPredeterminada = (i) => { cliRazonesLocal.forEach((r, k) => r.predeterminada = k === i); cliRenderRazones(); };
window.cliAdjElegir = (razonId, tipo, input) => {
  const f = input.files?.[0]; if (!f) return;
  const err = compValidar(f); if (err) { toast(err, 'error'); input.value = ''; return; }
  (_cliAdjPend[razonId] = _cliAdjPend[razonId] || {})[tipo] = f;
  cliRenderRazones();
};
window.cliAprobarCambio = async (i) => {
  const r = cliRazonesLocal[i]; if (!r?.cuentaCambio || !editingDoctorId) return;
  if (!segExigir('gerencia', 'aprobar cambios de cuenta bancaria')) return;
  if (r.cuentaCambio.porUid === currentUser?.uid) { toast('El cambio lo debe aprobar otra persona.', 'error'); return; }
  if (!cliPuedeEditarBanco()) { toast('Solo contabilidad o administración aprueban cambios de cuenta.', 'error'); return; }
  if (!confirm(`¿Verificaste el certificado bancario de ${r.razonSocial} y apruebas la cuenta ${r.banco} ${r.tipoCuenta} ${r.nCuenta}?`)) return;
  try {
    await runTransaction(db, async tx => {
      const ref = doc(db,'doctors', editingDoctorId); const sn = await tx.get(ref); if (!sn.exists()) throw new Error('La ficha ya no existe.');
      const rs = JSON.parse(JSON.stringify(sn.data().razones || [])); const rr = rs.find(x => x.id === r.id);
      if (!rr?.cuentaCambio || rr.cuentaCambio.aprobadoISO) throw new Error('El cambio ya no está pendiente.');
      if (rr.cuentaCambio.porUid === currentUser?.uid) throw new Error('El cambio lo debe aprobar otra persona.');
      Object.assign(rr.cuentaCambio, { aprobadoPor: cliUsuario(), aprobadoPorUid: currentUser?.uid || '', aprobadoISO: new Date().toISOString() });
      tx.update(ref, { razones: rs, updatedAt: serverTimestamp() });
      r.cuentaCambio = rr.cuentaCambio;
    });
    toast('Cambio de cuenta aprobado.', 'success'); cliRenderRazones();
  } catch (e) { toast('No se pudo aprobar: ' + e.message, 'error'); }
};
/* Sube un adjunto de la ficha con el mismo mecanismo verificado de los comprobantes */
async function cliSubirAdjunto(docId, razonId, tipoDoc, f){
  const bytes = new Uint8Array(await f.arrayBuffer()), sha = await compSha256(bytes), b64 = compB64DeBytes(bytes), nChunks = Math.ceil(b64.length / COMP_CHUNK), ext = compExt(f.name);
  const ref = await addDoc(collection(db,'comprobantes'), { egresoId: 'cli_' + docId, hid: razonId, nivel: 'cliente', tipoDoc, factura: '',
    nombre: f.name, ext, tipo: f.type || COMP_TIPOS[ext] || 'application/octet-stream', tamano: bytes.length, sha256: sha, nChunks, b64Len: b64.length, estado: 'subiendo',
    subidoPor: currentUser?.email || '', subidoPorUid: currentUser?.uid || '', fechaISO: new Date().toISOString(), createdAt: serverTimestamp() });
  try {
    for (let i = 0; i < nChunks; i++) await setDoc(doc(db,'comprobantesChunks', compIdFragmento(ref.id, i)), { compId: ref.id, i, data: b64.slice(i * COMP_CHUNK, (i + 1) * COMP_CHUNK) });
    await updateDoc(doc(db,'comprobantes', ref.id), { estado: 'completo', verificadoISO: new Date().toISOString() });
    return ref.id;
  } catch (e) { await compBorrarContenido(ref.id, nChunks).catch(()=>{}); await deleteDoc(doc(db,'comprobantes', ref.id)).catch(()=>{}); throw e; }
}
/* Valida las razones y arma lo que se guarda. Devuelve null si hay que corregir algo. */
function cliRazonesParaGuardar(d){
  const rs = cliRazonesLocal.map(r => { const x = { ...r, _orig: r.id }; delete x._virtual; if (x.id === 'rz_legado') x.id = cliNuevoId(); return x; });
  if (!rs.length) return { razones: [] };
  if (rs.filter(r => r.predeterminada).length !== 1) { rs.forEach((r, k) => r.predeterminada = k === Math.max(0, rs.findIndex(x => x.predeterminada))); }
  const vistos = new Map();
  for (const r of rs) {
    const e = cliRazonEfectiva(d, r);
    if (r.tipoPersona === 'juridica' && !String(r.razonSocial||'').trim()) { toast('Escribe la razón social de la persona jurídica.', 'error'); return null; }
    const n = entNitLimpio(e.documento);
    if (n) {
      if (vistos.has(n)) { toast(`El documento ${n} está repetido en dos razones sociales de esta ficha.`, 'error'); return null; }
      vistos.set(n, true);
      const otra = cliDocumentoEnOtraFicha(n, editingDoctorId);
      if (otra) { toast(`El ${r.tipoPersona === 'juridica' ? 'NIT' : 'documento'} ${n} ya está en la ficha «${otra.d.nombre}» (${otra.donde}). Un NIT o cédula no puede estar en dos fichas: únelas o corrige el dato.`, 'error'); return null; }
    }
    if (r.tipoPersona === 'juridica') r.dv = n ? entDvCalc(n) : '';
    if (r.tipoPersona === 'natural') { r.razonSocial = ''; r.documento = ''; r.dv = ''; }   // se toman de los datos personales
  }
  // Cambios de cuenta: registro, certificado nuevo y aprobación por otra persona
  for (const r of rs) {
    const o = cliRazonesOrig.find(x => x.id === r._orig);
    const ant = o ? { banco: o.banco || '', tipoCuenta: o.tipoCuenta || '', nCuenta: cliCuentaLimpia(o.nCuenta) } : null;
    const cambio = ant && ant.nCuenta && (ant.banco !== (r.banco||'') || ant.tipoCuenta !== (r.tipoCuenta||'') || cliCuentaNormal(ant.banco, ant.nCuenta) !== cliCuentaNormal(r.banco, r.nCuenta));
    if (!cambio) continue;
    if (!cliPuedeEditarBanco()) { toast('Solo contabilidad y administración pueden cambiar banco o cuenta.', 'error'); return null; }
    if (!_cliAdjPend[r._orig]?.cert) { toast(`Cambiaste la cuenta de ${cliRazonEfectiva(d, r).razonSocial}: adjunta el certificado bancario nuevo antes de guardar.`, 'error'); return null; }
    const hist = Array.isArray(r.historialCuenta) ? r.historialCuenta.slice(-19) : [];
    hist.push({ anterior: ant, nuevo: { banco: r.banco, tipoCuenta: r.tipoCuenta, nCuenta: cliCuentaLimpia(r.nCuenta) }, por: cliUsuario(), porUid: currentUser?.uid || '', fechaISO: new Date().toISOString() });
    r.historialCuenta = hist;
    r.cuentaCambio = { anterior: ant, nuevo: { banco: r.banco, tipoCuenta: r.tipoCuenta, nCuenta: cliCuentaLimpia(r.nCuenta) }, por: cliUsuario(), porUid: currentUser?.uid || '', fechaISO: new Date().toISOString() };
  }
  const mapaIds = {}; rs.forEach(r => { mapaIds[r._orig] = r.id; delete r._orig; r.nCuenta = cliCuentaNormal(r.banco, r.nCuenta); });
  const p = cliRazonEfectiva(d, rs.find(r => r.predeterminada));
  return { razones: rs, mapaIds, legado: { nit: p.documento ? (p.documento + (p.dv ? '-' + p.dv : '')) : '', banco: p.banco || '', nCuenta: p.nCuenta || '', tipoCuenta: p.tipoCuenta || '', regimenTrib: p.regimen || '' } };
}

