  { const av = document.getElementById('cliUnidaAviso'); if (av) { const pr = d?.unidaA ? doctors.find(x => x.id === d.unidaA) : null; av.innerHTML = d?.unidaA ? `<i class="fa-solid fa-link"></i> Esta ficha se unió a «${escHtml(pr?.nombre || 'otra ficha')}» el ${escHtml(compFechaHora(d.unidaISO))}.` : (d?.reclasificada ? `<i class="fa-solid fa-circle-info"></i> Reclasificada (${escHtml(d.reclasificada)}) por ${escHtml(d.reclasificadaPor||'')}.` : ''); av.style.display = av.innerHTML ? '' : 'none'; } }
