// Reemplaza con tu API key de Anthropic (console.anthropic.com)
const CLAUDE_API_KEY = 'PEGA_AQUI_TU_API_KEY_DE_CLAUDE';
let aiOpen = false;
let aiHistory = [];  // historial de conversación con la IA

/* Mostrar / ocultar panel */
