/* ══ SUSCRIPCIÓN FIRESTORE ══ */
let _grupoEstadoCargado = false;
function subscribeEgresos() {
  // Cargar el estado de carpetas UNA sola vez, temprano, antes de que
  // los snapshots rendericen. Al terminar, re-renderiza para aplicarlo.
  if (!_grupoEstadoCargado) {
    _grupoEstadoCargado = true;
    cargarGrupoColapsado().then(() => {
      renderEgresoTable();
      renderCustomTables();
    });
  }
  subscribeEntidades();
  regSuscribir();
  opSuscribir();
  feSuscribir();
  onSnapshot(collection(db,'egresos'), snap => {
    egresos = snap.docs.map(d=>({id:d.id,...d.data()}));
    iaDatosCambiaron();
    renderEgresoTable();
    if (document.getElementById('egresoModal')?.classList.contains('open')) { try { segPintarCandado(); } catch (e) {} }
    if (_d3) renderDashboard();   // zonas Facturación / Conciliaciones del dashboard 3D
    renderCustomTables();
  });
  onSnapshot(collection(db,'tablasEgreso'), snap => {
    const prev = tablasEgreso; // keep transient state
    tablasEgreso = snap.docs.map(d=>{
      const existing = prev.find(t=>t.id===d.id);
      return {
        id:d.id,...d.data(),
        _selectedIdent:   existing?._selectedIdent   || '',
        _selectedIdents:  existing?._selectedIdents  || [],
        _chkContabilidad: d.data().chkContabilidad   || false,
        _chkFacturacion:  d.data().chkFacturacion    || false,
      };
    });
    renderCustomTables();
    if (document.getElementById('egresoModal')?.classList.contains('open')) { egmResumen(); egmGirosPintar(); }   // un pago a un especialista recalcula el resumen y los giros de la factura a la entidad abierta
  });
}

/* ══ TABLA EGRESO (madre/hija) ══ */
/* "2026-07-15" → "15/07/2026" (fecha legible corta) */
function fmtFechaLegible(iso){
  if (!iso) return '';
  const m = String(iso).match(/^(\d{4})-(\d{2})-(\d{2})/);
  return m ? `${m[3]}/${m[2]}/${m[1]}` : iso;
}


/* ══════════════════════════════════════════════════
   UROEXPERTOS · Centro de facturación (pestañas, filtros, resumen)
   Solo cambia CÓMO se muestran los datos; no escribe en Firestore.
══════════════════════════════════════════════════ */
const _uroLS = { get(k){ try { return localStorage.getItem(k); } catch(e){ return null; } },
                 set(k,v){ try { localStorage.setItem(k,v); } catch(e){} } };
let _uroTabActual = _uroLS.get('uroTab') || 'resumen';
window.uroTab = (t) => {
  _uroTabActual = ['resumen','madres','liq'].includes(t) ? t : 'resumen';
  _uroLS.set('uroTab', _uroTabActual);
  const on = _uroTabActual;
  [['resumen','uroTabResumen','uroPanelResumen'],['madres','uroTabMadres','uroPanelMadres'],['liq','uroTabLiq','uroPanelLiq']].forEach(([k,tab,pan])=>{
    const b = document.getElementById(tab), p = document.getElementById(pan);
    if (b){ b.classList.toggle('on', k===on); b.setAttribute('aria-selected', k===on ? 'true':'false'); b.tabIndex = k===on ? 0 : -1; }
    if (p) p.hidden = (k!==on);
  });
  if (on === 'liq' && typeof renderCustomTables === 'function') renderCustomTables();
};
function uroContadoresTabs(){
  const a = document.getElementById('uroTabMadresN'); if (a) a.textContent = egresos.length || '';
  const b = document.getElementById('uroTabLiqN');    if (b) b.textContent = tablasEgreso.length || '';
}

const _ufNorm = s => String(s||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').trim();
let _ufAnioInicial = false;   // el año por defecto se fija una sola vez (año actual si tiene datos)
function uroFiltrosMadre(){
  const v = id => document.getElementById(id)?.value || '';
  return { anio: v('ufAnio'), mes: v('ufMes'), entidad: v('ufEntidad'), estado: v('ufEstado'), q: _ufNorm(v('ufBuscar')) };
}
/* Entidades sin repetir aunque estén escritas con mayúsculas, minúsculas o sin tildes distintas:
   "PANAMERICANA" y "Panamericana" son una sola. Se muestran en minúscula con mayúscula inicial,
   conservando siglas (S.A., E.S.E, RP) y las tildes de la variante que las tenga. */
function uroNombreBonito(s){
  const menores = new Set(['de','del','la','las','los','el','y','e','en','a','por','para']);
  return String(s||'').trim().replace(/\s+/g,' ').split(' ').map((w,i) => {
    if (/\./.test(w) || (w.length <= 3 && !/[aeiouáéíóú]/i.test(w))) return w.toUpperCase();   // siglas
    const l = w.toLocaleLowerCase('es');
    return (i>0 && menores.has(l)) ? l : l.charAt(0).toLocaleUpperCase('es') + l.slice(1);
  }).join(' ');
}
function uroEntidadesCanon(){
  const m = new Map();   // clave normalizada → variante elegida
  egresos.forEach(e => {
    const raw = String(e.nombre||'').trim(); if (!raw) return;
    const k = impNorm(raw); const prev = m.get(k);
    const tildes = v => (v.normalize('NFD').match(/[\u0300-\u036f]/g)||[]).length;
    if (!prev || tildes(raw) > tildes(prev)) m.set(k, raw);
  });
  return [...m.entries()].map(([k, v]) => [k, uroNombreBonito(v)]).sort((a,b)=>a[1].localeCompare(b[1],'es',{sensitivity:'base'}));
}
/* ═════════════════════════════════════════════════════════════════
   CATÁLOGO ÚNICO DE ENTIDADES (colección 'entidades')
   · ID único e inmutable ('ent_' + nombre normalizado al crearla). Cambiar la razón social no cambia el ID.
   · Campos: razonSocial, nit (texto, conserva ceros), dv, activo, clave (para detectar duplicados),
     creadoEn, actualizadoEn, creadoPor, origen, historial [{campo, antes, despues, por, fecha}].
   · Las facturas a la entidad guardan entidadId + copia del NIT (entidadNit/entidadDv) y conservan 'nombre'
     para que todos los módulos actuales sigan funcionando.
   · Facturas antiguas sin entidadId: se reconocen SOLO por nombre idéntico (sin distinguir mayúsculas,
     tildes ni espacios). Nunca se fusionan por nombres parecidos: esas quedan en la lista de revisión.
═════════════════════════════════════════════════════════════════ */
let entidades = [];
let _entCargado = false, _entSembrando = false;
const ENT_ABREV = { fund:'fundacion', fdn:'fundacion', clin:'clinica', clinic:'clinica', hosp:'hospital', cia:'compania', univ:'universidad', soc:'sociedad', med:'medica', medicos:'medicas' };
const ENT_VACIAS = new Set(['de','del','la','las','los','el','y','e','en']);
const ENT_SUFIJOS = new Set(['sas','sa','ltda','limitada','sociedad','anonima','scs','sca','eu','bic']);
const ENT_GENERICAS = new Set(['clinica','fundacion','hospital','ips','ese','centro','medico','medica','medicas','sede','salud','compania']);
/* Clave para detectar duplicados: sin mayúsculas, tildes, puntuación, espacios, artículos ni sufijos societarios,
   con abreviaturas comunes expandidas ("Fund. Clín. del Norte S.A.S." = "Fundación Clínica de Norte"). */
function entTokens(nombre){
  const t = impNorm(nombre).split(' ').filter(Boolean), out = [];
  for (let i = 0; i < t.length; i++) {          // letras sueltas seguidas = sigla (e s e → ese, s a s → sas)
    if (t[i].length === 1) { let s = t[i]; while (t[i+1] && t[i+1].length === 1) s += t[++i]; out.push(s); }
    else out.push(t[i]);
  }
  return out.map(w => ENT_ABREV[w] || w).filter(w => !ENT_VACIAS.has(w) && !ENT_SUFIJOS.has(w));
}
const entClave = nombre => entTokens(nombre).join(' ');
const entIdDesde = nombre => 'ent_' + (impNorm(nombre).replace(/ /g,'_').slice(0,60) || Date.now().toString(36));
const entNitLimpio = v => String(v||'').replace(/\D/g,'');
/* Dígito de verificación DIAN (módulo 11) */
function entDvCalc(nit){
  const d = entNitLimpio(nit); if (!d) return '';
  const pesos = [3,7,13,17,19,23,29,37,41,43,47,53,59,67,71];
  let s = 0; [...d].reverse().forEach((c,i) => { s += Number(c) * (pesos[i]||0); });
  const r = s % 11; return String(r > 1 ? 11 - r : r);
}
const entNitTexto = (nit, dv) => nit ? String(nit).replace(/\B(?=(\d{3})+(?!\d))/g,'.') + (dv !== '' && dv != null ? '-' + dv : '') : '';
const entPorId = id => entidades.find(x => x.id === id) || null;
const entActivas = () => entidades.filter(x => x.activo !== false).sort((a,b)=>String(a.razonSocial).localeCompare(String(b.razonSocial),'es',{sensitivity:'base'}));
/* Entidad de una factura a la entidad: la referencia guardada o, en facturas antiguas, el nombre idéntico */
/* Entidad de un nombre escrito: idéntico (sin mayúsculas/tildes/espacios) o con la misma clave
   (artículos, sufijos S.A.S./S.A., abreviaturas). Solo si hay UNA coincidencia. */
function entPorNombre(nombre){
  const k = impNorm(nombre); if (!k) return null;
  let hits = entidades.filter(x => impNorm(x.razonSocial) === k);
  if (!hits.length) { const c = entClave(nombre); hits = c ? entidades.filter(x => entClave(x.razonSocial) === c) : []; }
  return hits.length === 1 ? hits[0] : null;
}
/* Entidad de una factura a la entidad: la referencia guardada o la de su nombre */
function entDe(e){
  if (!e) return null;
  if (e.entidadId) { const x = entPorId(e.entidadId); if (x) return x; }
  return entPorNombre(e.nombre);
}
/* Entidad de una tabla de liquidación: la guardada o la de su nombre */
function entDeTabla(t){
  if (!t) return null;
  if (t.entidadId) { const x = entPorId(t.entidadId); if (x) return x; }
  return entPorNombre(t.nombre);
}
function entBuscarDuplicados(nombre, nit, excluirId){
  const k = entClave(nombre), n = entNitLimpio(nit), sig = new Set(entTokens(nombre).filter(w => !ENT_GENERICAS.has(w)));
  const out = [];
  entidades.forEach(x => {
    if (x.id === excluirId) return;
    if (n && entNitLimpio(x.nit) === n) { out.push({ ent:x, tipo:'igual', motivo:'mismo NIT' }); return; }
    if (k && entClave(x.razonSocial) === k) { out.push({ ent:x, tipo:'igual', motivo:'mismo nombre' }); return; }
    const sx = new Set(entTokens(x.razonSocial).filter(w => !ENT_GENERICAS.has(w)));
    if (!sig.size || !sx.size) return;
    const comun = [...sig].filter(w => sx.has(w)).length;
    if (comun && (comun === sig.size || comun === sx.size)) out.push({ ent:x, tipo:'parecida', motivo:'nombre parecido' });
  });
  return out;
}
const entUsuario = () => currentProfile?.nombreCompleto || currentUser?.email || '';

/* Entidades de Uroexpertos: siempre están en el catálogo (se crean solas en la base si faltan). */
const ENT_BASE = ['Administración','Clínica Llano Grande','Clínica Medellín','Clínica Panamericana','Clínica Vida',
  'E.S.E Hospital San Vicente de Paul del Municipio de Caldas','Fundación Clínica de Norte','IPS Ambulatorias de Colombia S.A.S.',
  'RP Medicas S.A.','Uroexpertos'];
let _entGuardadas = [], _entErrorAvisado = false;
function entMezclar(){
  const ids = new Set(_entGuardadas.map(x => x.id));
  const claves = new Set(_entGuardadas.map(x => entClave(x.razonSocial)));
  const faltan = ENT_BASE.filter(n => !ids.has(entIdDesde(n)) && !claves.has(entClave(n)))   // ya guardada con otra escritura: no se repite
    .map(n => ({ id: entIdDesde(n), razonSocial: n, nit:'', dv:'', activo:true, clave: entClave(n), _pendiente: true }));
  entidades = [..._entGuardadas, ...faltan];
  return faltan;
}
function subscribeEntidades(){
  entMezclar(); _entCargado = true;   // las entidades base se ven desde el primer momento
  onSnapshot(collection(db,'entidades'), snap => {
    _entGuardadas = snap.docs.map(d => ({ id:d.id, ...d.data() }));
    const faltan = entMezclar();
    if (faltan.length) entCrearBase(faltan);
    uroPoblarFiltrosMadre();
    renderEgresoTable();
    if (document.getElementById('egresoModal')?.classList.contains('open')) entRefrescarSeleccion();
    if (document.getElementById('uroMadresModal')?.classList.contains('open')) uroMselRender();
    if (document.getElementById('entCatModal')?.classList.contains('open')) entCatRender();
  }, err => { console.warn('No se pudo leer el catálogo de entidades:', err); entAvisarError(err); });
}
function entAvisarError(err){
  if (_entErrorAvisado) return; _entErrorAvisado = true;
  toast('El catálogo de entidades no se pudo leer o guardar en la base (' + (err?.code || err?.message || 'error') + '). Revisa las reglas de Firestore.', 'error');
}
/* Crea en la base las entidades base que falten (IDs fijos + transacción: dos equipos a la vez no duplican) */
async function entCrearBase(faltan){
  if (_entSembrando) return; _entSembrando = true;
  try {
    await runTransaction(db, async tx => {
      const refs = faltan.map(x => doc(db,'entidades', x.id));
      const leidos = await Promise.all(refs.map(r => tx.get(r)));
      refs.forEach((r, i) => { if (leidos[i].exists()) return;
        tx.set(r, { razonSocial: faltan[i].razonSocial, nit:'', dv:'', activo:true, clave: faltan[i].clave, origen:'catálogo base',
          creadoEn: serverTimestamp(), actualizadoEn: serverTimestamp(), creadoPor: entUsuario(), historial: [] }); });
    });
  } catch (e) { console.warn('No se pudieron crear las entidades base:', e); entAvisarError(e); }
  finally { _entSembrando = false; }
}
/* Crea una entidad (transacción: si el ID ya existe no se sobrescribe) */
async function entCrear({ razonSocial, nit, dv }){
  const nombre = String(razonSocial||'').trim().replace(/\s+/g,' ');
  if (!nombre) throw new Error('Escribe el nombre o razón social.');
  const n = entNitLimpio(nit);
  if (n && (n.length < 5 || n.length > 15)) throw new Error('El NIT debe tener entre 5 y 15 dígitos.');
  const d = String(dv||'').replace(/\D/g,'').slice(0,1);
  const dup = entBuscarDuplicados(nombre, n).find(x => x.tipo === 'igual');
  if (dup) throw Object.assign(new Error(`Ya existe «${dup.ent.razonSocial}» (${dup.motivo}).`), { dup: dup.ent });
  const ref = doc(db,'entidades', entIdDesde(nombre));
  await runTransaction(db, async tx => {
    const s = await tx.get(ref);
    if (s.exists()) throw Object.assign(new Error('Ya existe una entidad con ese nombre.'), { dup: { id: ref.id, ...s.data() } });
    tx.set(ref, { razonSocial: nombre, nit: n, dv: d, activo: true, clave: entClave(nombre), origen:'manual',
      creadoEn: serverTimestamp(), actualizadoEn: serverTimestamp(), creadoPor: entUsuario(), historial: [] });
  });
  const nueva = { id: ref.id, razonSocial: nombre, nit: n, dv: d, activo: true, clave: entClave(nombre) };
  if (!entPorId(ref.id)) entidades.push(nueva);   // disponible ya, antes de que llegue el snapshot
  return nueva;
}
/* Actualiza campos de una entidad dejando historial (valor anterior, nuevo, usuario y fecha) */
async function entActualizar(id, cambios){
  const ref = doc(db,'entidades', id);
  const base = entPorId(id);
  await runTransaction(db, async tx => {
    const s = await tx.get(ref);
    if (!s.exists()) {
      if (!base?._pendiente) throw new Error('La entidad ya no existe.');
      const nuevo = { razonSocial: base.razonSocial, nit:'', dv:'', activo:true, ...cambios };
      tx.set(ref, { ...nuevo, clave: entClave(nuevo.razonSocial), origen:'catálogo base', creadoEn: serverTimestamp(), actualizadoEn: serverTimestamp(), creadoPor: entUsuario(),
        historial: Object.entries(cambios).map(([k, v]) => ({ campo:k, antes:'', despues:v, por: entUsuario(), fecha: new Date().toISOString() })) });
      return;
    }
    const act = s.data(), hist = Array.isArray(act.historial) ? act.historial.slice(-49) : [];
    const upd = {};
    Object.entries(cambios).forEach(([k, v]) => { if ((act[k] ?? '') !== v) { upd[k] = v; hist.push({ campo:k, antes: act[k] ?? '', despues: v, por: entUsuario(), fecha: new Date().toISOString() }); } });
    if (!Object.keys(upd).length) return;
    if ('razonSocial' in upd) upd.clave = entClave(upd.razonSocial);
    tx.update(ref, { ...upd, historial: hist, actualizadoEn: serverTimestamp() });
  });
}

/* ── Selector de entidad en la factura a la entidad (búsqueda por nombre o NIT, teclado, crear sin salir) ── */
let _entIdx = -1, _entNombreHistorico = '';
function entComboOpciones(){
  const q = impNorm(document.getElementById('eNombre')?.value), qn = entNitLimpio(document.getElementById('eNombre')?.value);
  const selId = document.getElementById('eEntidadId')?.value;
  const sel = selId ? entPorId(selId) : null;
  const filtrar = !(sel && impNorm(sel.razonSocial) === q);   // con una entidad ya elegida se ven todas
  return entActivas().filter(x => !filtrar || !q || impNorm(x.razonSocial).includes(q) || (qn.length >= 3 && entNitLimpio(x.nit).includes(qn)));
}
function entComboRender(){
  const box = document.getElementById('entLista'); if (!box) return;
  const ops = entComboOpciones(), selId = document.getElementById('eEntidadId')?.value;
  const txt = (document.getElementById('eNombre')?.value || '').trim();
  box.innerHTML = (ops.length ? ops.map((x, i) => `<div class="ent-op${x.id===selId?' sel':''}${i===_entIdx?' act':''}" role="option" id="entOp${i}" aria-selected="${x.id===selId}" data-id="${x.id}" onmousedown="event.preventDefault();entSeleccionar('${x.id}')">
      <span class="ent-op-n">${escHtml(x.razonSocial)}</span><span class="ent-op-nit">${x.nit ? 'NIT ' + escHtml(entNitTexto(x.nit, x.dv)) : '<em>sin NIT</em>'}</span>
      <button type="button" class="ent-op-ed" title="Editar nombre y NIT" aria-label="Editar ${escHtml(x.razonSocial)}" onmousedown="event.preventDefault();event.stopPropagation();entEditarDesdeLista('${x.id}')"><i class="fa-solid fa-pen"></i></button></div>`).join('')
    : `<div class="ent-vacio">${_entCargado ? 'Ninguna entidad coincide.' : 'Cargando catálogo…'}</div>`)
    + `<div class="ent-op ent-crear${_entIdx===ops.length?' act':''}" role="option" id="entOp${ops.length}" onmousedown="event.preventDefault();entAbrirCrear()"><i class="fa-solid fa-plus"></i> Crear nueva entidad${txt && !ops.some(x=>impNorm(x.razonSocial)===impNorm(txt)) ? ` «${escHtml(txt)}»` : ''}</div>`;
  document.getElementById('eNombre')?.setAttribute('aria-activedescendant', _entIdx >= 0 ? 'entOp' + _entIdx : '');
}
function entComboAbrir(){ const b = document.getElementById('entLista'); if (!b) return; entComboRender();
  const c = document.querySelector('#egresoModal .ent-combo'); if (c) b.style.top = (c.offsetTop + c.offsetHeight + 4) + 'px';   // justo debajo de la casilla
  b.hidden = false; document.getElementById('eNombre')?.setAttribute('aria-expanded','true'); }
function entComboCerrar(){ const b = document.getElementById('entLista'); if (b) b.hidden = true; _entIdx = -1; document.getElementById('eNombre')?.setAttribute('aria-expanded','false'); }
function entComboInit(){
  const inp = document.getElementById('eNombre'); if (!inp || inp._entListo) return; inp._entListo = true;
  inp.addEventListener('focus', entComboAbrir);
  inp.addEventListener('click', entComboAbrir);
  inp.addEventListener('input', () => {
    const sel = entPorId(document.getElementById('eEntidadId').value);
    if (sel && impNorm(sel.razonSocial) !== impNorm(inp.value)) entPonerEntidad(null, { conservarTexto:true });
    _entIdx = -1; entComboAbrir();
  });
  inp.addEventListener('keydown', ev => {
    const b = document.getElementById('entLista'); const n = entComboOpciones().length + 1;
    if (ev.key === 'ArrowDown') { ev.preventDefault(); if (b.hidden) entComboAbrir(); _entIdx = (_entIdx + 1) % n; entComboRender(); document.getElementById('entOp'+_entIdx)?.scrollIntoView({ block:'nearest' }); }
    else if (ev.key === 'ArrowUp') { ev.preventDefault(); _entIdx = _entIdx <= 0 ? n - 1 : _entIdx - 1; entComboRender(); document.getElementById('entOp'+_entIdx)?.scrollIntoView({ block:'nearest' }); }
    else if (ev.key === 'Enter' && !b.hidden) { ev.preventDefault(); const ops = entComboOpciones();
      if (_entIdx >= 0 && _entIdx < ops.length) entSeleccionar(ops[_entIdx].id);
      else if (_entIdx === ops.length) entAbrirCrear();
      else if (ops.length === 1) entSeleccionar(ops[0].id); }
    else if (ev.key === 'Escape') entComboCerrar();
  });
  inp.addEventListener('blur', () => setTimeout(() => {
    entComboCerrar();
    // Si lo escrito es exactamente una entidad (aunque cambien mayúsculas, tildes o abreviaturas), se elige sola
    if (!document.getElementById('eEntidadId').value && inp.value.trim()) {
      const hits = entActivas().filter(x => entClave(x.razonSocial) === entClave(inp.value));
      if (hits.length === 1) entSeleccionar(hits[0].id);
    }
    entPintarHint();
  }, 120));
  document.querySelector('#egresoModal .ent-caret')?.addEventListener('mousedown', ev => { ev.preventDefault(); const b = document.getElementById('entLista'); if (b.hidden) { inp.focus(); entComboAbrir(); } else entComboCerrar(); });
  ['eEntidadNit','eEntidadDv'].forEach(id => document.getElementById(id)?.addEventListener('input', ev => {
    const el = ev.target; el.value = id === 'eEntidadDv' ? el.value.replace(/\D/g,'').slice(0,1) : el.value.replace(/[^\d.\-\s]/g,'');
    if (id === 'eEntidadNit') { const m = el.value.match(/^([\d.\s]+)-(\d)$/); if (m) { el.value = m[1]; document.getElementById('eEntidadDv').value = m[2]; } }
    entPintarHint();
  }));
}
window.entSeleccionar = (id) => { entPonerEntidad(entPorId(id)); entComboCerrar(); document.getElementById('eFactura')?.focus(); };
/* Pone la entidad en el formulario y su NIT (o permite escribirlo si aún no tiene) */
function entPonerEntidad(ent, o = {}){
  const inp = document.getElementById('eNombre'), hid = document.getElementById('eEntidadId');
  const nit = document.getElementById('eEntidadNit'), dv = document.getElementById('eEntidadDv');
  hid.value = ent ? ent.id : '';
  if (ent && !o.conservarTexto) inp.value = ent.razonSocial;
  const tieneNit = !!(ent && ent.nit);
  const snap = o.snapshot;   // NIT guardado en la factura (se conserva al consultar facturas anteriores)
  nit.value = snap?.nit ? snap.nit : (tieneNit ? ent.nit : '');
  dv.value  = snap?.nit ? (snap.dv || '') : (tieneNit ? (ent.dv || '') : '');
  const editable = !!ent && !tieneNit && !snap?.nit;
  [nit, dv].forEach(el => { el.readOnly = !editable; el.classList.toggle('ent-auto', !editable); });
  nit.placeholder = ent ? (editable ? 'Escribe el NIT' : '') : 'Se completa al elegir la entidad';
  entPintarHint();
}
function entPintarHint(){
  const h = document.getElementById('entHint'), hn = document.getElementById('entNitHint'); if (!h || !hn) return;
  const id = document.getElementById('eEntidadId').value, ent = id ? entPorId(id) : null, txt = document.getElementById('eNombre').value.trim();
  h.className = 'ent-hint'; hn.className = 'ent-hint';
  if (!ent && txt) {
    if (_entNombreHistorico && impNorm(txt) === impNorm(_entNombreHistorico)) { h.textContent = 'Este nombre no está en el catálogo. Elige la entidad de la lista.'; h.classList.add('warn'); }
    else { h.textContent = 'Elige una entidad de la lista o créala con «+ Crear nueva entidad».'; h.classList.add('warn'); }
  } else h.textContent = '';
  const nit = document.getElementById('eEntidadNit');
  if (ent && !nit.readOnly) {
    const n = entNitLimpio(nit.value), dv = document.getElementById('eEntidadDv').value;
    if (!n) hn.textContent = 'Esta entidad aún no tiene NIT: escríbelo y quedará guardado en el catálogo.';
    else if (dv && dv !== entDvCalc(n)) { hn.textContent = `El dígito de verificación calculado es ${entDvCalc(n)}. Revísalo.`; hn.classList.add('warn'); }
    else hn.textContent = dv ? '' : `Dígito de verificación sugerido: ${entDvCalc(n)}.`;
  } else hn.textContent = '';
}
/* Al abrir la factura a la entidad */
function entCargarEnFormulario(e){
  entComboInit();
  _entNombreHistorico = e ? String(e.nombre||'') : '';
  const ent = entDe(e);
  document.getElementById('eNombre').value = e?.nombre || '';
  entPonerEntidad(ent, { conservarTexto: !ent, snapshot: e?.entidadNit ? { nit: e.entidadNit, dv: e.entidadDv } : null });
  if (!ent) { document.getElementById('eNombre').value = e?.nombre || ''; entPintarHint(); }
}
/* El catálogo cambió con la factura abierta (p. ej. otra persona completó el NIT) */
function entRefrescarSeleccion(){
  const id = document.getElementById('eEntidadId')?.value; if (!id) return;
  const ent = entPorId(id), nit = document.getElementById('eEntidadNit');
  if (ent && nit.readOnly === false && ent.nit && !entNitLimpio(nit.value)) entPonerEntidad(ent);
  if (!document.getElementById('entLista')?.hidden) entComboRender();
}
/* Valida y devuelve lo que la factura a la entidad guarda de su entidad (o null si hay que corregir algo) */
async function entDatosParaGuardar(){
  const id = document.getElementById('eEntidadId').value, txt = document.getElementById('eNombre').value.trim();
  if (!id) {
    if (!txt) return { nombre: '' };
    if (editEgresoId && impNorm(txt) === impNorm(_entNombreHistorico)) return { nombre: txt };   // factura antigua sin tocar la entidad
    toast('Elige la entidad de la lista o créala con «+ Crear nueva entidad». Así no se crean entidades repetidas.', 'error');
    document.getElementById('eNombre').focus(); return null;
  }
  const ent = entPorId(id); if (!ent) { toast('La entidad elegida ya no existe en el catálogo.', 'error'); return null; }
  const nit = entNitLimpio(document.getElementById('eEntidadNit').value), dv = document.getElementById('eEntidadDv').value.replace(/\D/g,'').slice(0,1);
  if (!document.getElementById('eEntidadNit').readOnly && nit) {   // NIT nuevo para una entidad que no tenía
    if (nit.length < 5 || nit.length > 15) { toast('El NIT debe tener entre 5 y 15 dígitos.', 'error'); return null; }
    const otra = entidades.find(x => x.id !== id && entNitLimpio(x.nit) === nit);
    if (otra) { toast(`Ese NIT ya pertenece a «${otra.razonSocial}». Revisa la entidad elegida.`, 'error'); return null; }
    try { await entActualizar(id, { nit, dv }); ent.nit = nit; ent.dv = dv; }
    catch (err) { toast('No se pudo guardar el NIT en el catálogo: ' + err.message, 'error'); return null; }
  }
  return { nombre: ent.razonSocial, entidadId: id, entidadNit: nit || ent.nit || '', entidadDv: nit ? dv : (ent.dv || '') };
}

/* ── Modal: crear entidad (desde el selector o desde el catálogo) ── */
let _entCrearDestino = null;   // 'egreso' | 'catalogo' | 'tabla'
window.entAbrirCrear = (destino = 'egreso', nombreInicial) => {
  _entCrearDestino = destino;
  entComboCerrar();
  const txt = nombreInicial ?? (destino === 'egreso' ? (document.getElementById('eNombre')?.value || '').trim() : '');
  document.getElementById('entNuevaNombre').value = (destino === 'egreso' && entPorId(document.getElementById('eEntidadId')?.value)) ? '' : txt;
  document.getElementById('entNuevaNit').value = ''; document.getElementById('entNuevaDv').value = '';
  entCrearValidar();
  document.getElementById('entModal').classList.add('open');
  setTimeout(() => document.getElementById('entNuevaNombre').focus(), 40);
};
window.entCerrarCrear = () => { document.getElementById('entModal').classList.remove('open'); if (_entCrearDestino === 'egreso') document.getElementById('eNombre')?.focus(); };
window.entCrearValidar = () => {
  const nom = document.getElementById('entNuevaNombre').value, nitEl = document.getElementById('entNuevaNit'), dvEl = document.getElementById('entNuevaDv');
  const m = nitEl.value.match(/^([\d.\s]+)-(\d)$/); if (m) { nitEl.value = m[1]; dvEl.value = m[2]; }
  dvEl.value = dvEl.value.replace(/\D/g,'').slice(0,1);
  const nit = entNitLimpio(nitEl.value);
  const dups = nom.trim() || nit ? entBuscarDuplicados(nom, nit) : [];
  const iguales = dups.filter(d => d.tipo === 'igual'), parecidas = dups.filter(d => d.tipo === 'parecida');
  const box = document.getElementById('entDup');
  const fila = d => `<div class="ent-dup-f"><span><b>${escHtml(d.ent.razonSocial)}</b>${d.ent.nit ? ' · NIT ' + escHtml(entNitTexto(d.ent.nit, d.ent.dv)) : ''} <small>(${d.motivo}${d.ent.activo===false?' · inactiva':''})</small></span>${_entCrearDestino === 'egreso' && d.ent.activo !== false ? `<button type="button" class="uro-btn outline sm" onclick="entUsarExistente('${d.ent.id}')">Seleccionar</button>` : ''}</div>`;
  box.innerHTML = iguales.length ? `<div class="ent-dup err"><i class="fa-solid fa-circle-exclamation"></i> Esta entidad ya existe. No se puede crear otra igual.${iguales.map(fila).join('')}</div>`
    : parecidas.length ? `<div class="ent-dup warn"><i class="fa-solid fa-triangle-exclamation"></i> Hay entidades con nombre parecido. Revisa que no sea la misma.${parecidas.map(fila).join('')}</div>` : '';
  const hn = document.getElementById('entNuevaNitHint');
  hn.textContent = nit && !dvEl.value ? `Dígito de verificación sugerido: ${entDvCalc(nit)}` : (nit && dvEl.value !== entDvCalc(nit) ? `El dígito calculado es ${entDvCalc(nit)}. Revísalo.` : '');
  hn.className = 'ent-hint' + (nit && dvEl.value && dvEl.value !== entDvCalc(nit) ? ' warn' : '');
  document.getElementById('entGuardarBtn').disabled = !nom.trim() || iguales.length > 0 || (nit && (nit.length < 5 || nit.length > 15));
};
window.entUsarExistente = (id) => { document.getElementById('entModal').classList.remove('open'); entSeleccionar(id); toast('Entidad seleccionada.', 'success'); };
window.entGuardarNueva = async () => {
  const btn = document.getElementById('entGuardarBtn');
  const datos = { razonSocial: document.getElementById('entNuevaNombre').value, nit: document.getElementById('entNuevaNit').value, dv: document.getElementById('entNuevaDv').value };
  const parecidas = entBuscarDuplicados(datos.razonSocial, datos.nit).filter(d => d.tipo === 'parecida');
  if (parecidas.length && !confirm(`Existe una entidad parecida: «${parecidas[0].ent.razonSocial}».\n\n¿Es una entidad diferente y quieres crearla de todas formas?`)) return;
  btn.disabled = true; const txt = btn.innerHTML; btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Guardando…';
  try {
    const nueva = await entCrear(datos);
    document.getElementById('entModal').classList.remove('open');
    toast(`Entidad «${nueva.razonSocial}» creada.`, 'success');
    if (_entCrearDestino === 'egreso') entSeleccionar(nueva.id);
    else if (_entCrearDestino === 'tabla') { const s = document.getElementById('tablaEntidad'); if (s) { tablaEntidadOpts(nueva.id); } }
    else entCatRender();
  } catch (e) { toast(e.message, 'error'); entCrearValidar(); }
  finally { btn.innerHTML = txt; entCrearValidar(); }
};

/* ── Catálogo de entidades: lista, NIT, activar/inactivar y revisión de facturas antiguas ── */
window.entAbrirCatalogo = () => { document.getElementById('entCatBuscar').value = ''; _entCatEdit = null; entCatRender(); document.getElementById('entCatModal').classList.add('open'); };
window.entCerrarCatalogo = () => document.getElementById('entCatModal').classList.remove('open');
let _entCatEdit = null;
window.entCatRender = () => {
  const box = document.getElementById('entCatBody'); if (!box) return;
  const q = impNorm(document.getElementById('entCatBuscar').value), qn = entNitLimpio(document.getElementById('entCatBuscar').value);
  const usos = new Map(); egresos.forEach(e => { const x = entDe(e); if (x) usos.set(x.id, (usos.get(x.id)||0) + 1); });
  const lista = entidades.slice().sort((a,b)=>String(a.razonSocial).localeCompare(String(b.razonSocial),'es',{sensitivity:'base'}))
    .filter(x => !q || impNorm(x.razonSocial).includes(q) || (qn.length >= 3 && entNitLimpio(x.nit).includes(qn)));
  const filas = lista.map((x, n) => _entCatEdit === x.id ? `<tr class="ent-edit">
      <td class="ent-n">${n+1}</td>
      <td><input type="text" id="entEdNombre" value="${escHtml(x.razonSocial)}" aria-label="Razón social" onkeydown="if(event.key==='Enter')entCatGuardar('${x.id}');if(event.key==='Escape')entCatEditar(null)"/></td>
      <td><div class="ent-nit-par"><input type="text" id="entEdNit" value="${escHtml(x.nit||'')}" inputmode="numeric" placeholder="NIT" aria-label="NIT" oninput="entCatDvSugerido()" onkeydown="if(event.key==='Enter')entCatGuardar('${x.id}')"/><span>-</span><input type="text" id="entEdDv" value="${escHtml(x.dv||'')}" maxlength="1" inputmode="numeric" placeholder="DV" aria-label="Dígito de verificación" oninput="entCatDvSugerido()" onkeydown="if(event.key==='Enter')entCatGuardar('${x.id}')"/></div><small class="ent-hint" id="entEdHint"></small></td>
      <td colspan="2" class="ent-cat-acc"><button type="button" class="uro-btn ghost sm" onclick="entCatEditar(null)">Cancelar</button><button type="button" class="uro-btn pri sm" onclick="entCatGuardar('${x.id}')"><i class="fa-solid fa-check"></i> Guardar</button></td></tr>`
    : `<tr class="${x.activo===false?'ent-inactiva':''}">
      <td class="ent-n">${n+1}</td>
      <td><b>${escHtml(x.razonSocial)}</b>${x.activo===false?' <span class="uro-pill gris">Inactiva</span>':''}</td>
      <td>${x.nit ? escHtml(entNitTexto(x.nit, x.dv)) : '<span class="ent-falta">Sin NIT</span>'}</td>
      <td class="td-num">${usos.get(x.id)||0}</td>
      <td class="ent-cat-acc"><button type="button" class="uro-btn outline sm" onclick="entCatEditar('${x.id}')"><i class="fa-solid fa-pen"></i> Editar</button>
        <button type="button" class="act-btn" title="${x.activo===false?'Activar':'Inactivar'}" aria-label="${x.activo===false?'Activar':'Inactivar'} ${escHtml(x.razonSocial)}" onclick="entCatActivo('${x.id}',${x.activo===false})"><i class="fa-solid ${x.activo===false?'fa-toggle-off':'fa-toggle-on'}"></i></button></td></tr>`).join('');
  box.innerHTML = `<table class="ent-cat-t"><thead><tr><th class="ent-n">N.º</th><th>Entidad</th><th>NIT</th><th class="td-num">Facturas</th><th><span class="uro-sr">Acciones</span></th></tr></thead><tbody>${filas || '<tr><td colspan="5" class="uro-vacio-tabla">No hay entidades que coincidan.</td></tr>'}</tbody></table>`;
  if (_entCatEdit) entCatDvSugerido();
};
window.entCatDvSugerido = () => {
  const h = document.getElementById('entEdHint'); if (!h) return;
  const dvEl = document.getElementById('entEdDv'); dvEl.value = dvEl.value.replace(/\D/g,'').slice(0,1);
  const n = entNitLimpio(document.getElementById('entEdNit').value), dv = dvEl.value;
  h.className = 'ent-hint' + (n && dv && dv !== entDvCalc(n) ? ' warn' : '');
  h.textContent = !n ? '' : !dv ? `DV sugerido: ${entDvCalc(n)}` : (dv !== entDvCalc(n) ? `El DV calculado es ${entDvCalc(n)}` : '');
};
window.entCatEditar = (id) => { _entCatEdit = id; entCatRender(); setTimeout(()=>document.getElementById('entEdNombre')?.focus(), 30); };
window.entCatGuardar = async (id) => {
  const nombre = document.getElementById('entEdNombre').value.trim().replace(/\s+/g,' '), nit = entNitLimpio(document.getElementById('entEdNit').value), dv = document.getElementById('entEdDv').value.replace(/\D/g,'').slice(0,1);
  if (!nombre) { toast('La razón social no puede quedar vacía.','error'); return; }
  if (nit && (nit.length < 5 || nit.length > 15)) { toast('El NIT debe tener entre 5 y 15 dígitos.','error'); return; }
  const dup = entBuscarDuplicados(nombre, nit, id).find(d => d.tipo === 'igual');
  if (dup) { toast(`Ya existe «${dup.ent.razonSocial}» (${dup.motivo}).`,'error'); return; }
  const antes = entPorId(id)?.razonSocial || '';
  try { await entActualizar(id, { razonSocial: nombre, nit, dv }); const n = await entPropagarNombre(id, antes, nombre); _entCatEdit = null; toast(`Entidad actualizada${n ? `: ${n} factura(s) a la entidad con el nombre nuevo` : ''}.`,'success'); entCatRender(); }
  catch (e) { toast('No se pudo guardar: ' + e.message,'error'); }
};
/* 9.6 · el nombre corregido de una entidad se aplica a todas sus facturas (solo el campo nombre; nada más cambia) */
async function entPropagarNombre(id, antes, nuevo){
  if (!nuevo || antes === nuevo) return 0;
  const lista = egresos.filter(e => e.entidadId === id || (!e.entidadId && antes && impNorm(e.nombre) === impNorm(antes))).filter(e => e.nombre !== nuevo);
  let n = 0;
  for (let i = 0; i < lista.length; i += 200) {
    const lote = writeBatch(db), hist = writeBatch(db), ahora = new Date().toISOString(), por = currentProfile?.nombreCompleto || currentUser?.email || '';
    lista.slice(i, i + 200).forEach(e => { lote.update(doc(db,'egresos', e.id), { nombre: nuevo });
      hist.set(doc(collection(db,'historialEgresos')), { egresoId: e.id, accion: 'Cambio', campo: 'Entidad', antes: e.nombre || '', despues: nuevo, motivo: 'Nombre corregido en el catálogo de entidades', por, porUid: currentUser?.uid || '', porEmail: currentUser?.email || '', fechaISO: ahora, createdAt: serverTimestamp() }); });
    await lote.commit(); n += Math.min(200, lista.length - i); await hist.commit().catch(() => {});
  }
  const inp = document.getElementById('eNombre'); if (inp && document.getElementById('eEntidadId')?.value === id) inp.value = nuevo;
  return n;
}
window.entEditarDesdeLista = (id) => {
  const x = entPorId(id); if (!x) return;
  entComboCerrar();
  uaModal(`Editar entidad`, `<div class="ua-form"><label class="ua-full">Nombre o razón social<input id="entLNombre" value="${escHtml(x.razonSocial)}" maxlength="120"/></label>
    <label>NIT<input id="entLNit" value="${escHtml(x.nit || '')}" inputmode="numeric" maxlength="15"/></label><label>DV<input id="entLDv" value="${escHtml(x.dv || '')}" inputmode="numeric" maxlength="1"/></label></div>
    <p class="ua-nota"><i class="fa-solid fa-circle-info"></i> El nombre corregido se aplica a todas sus facturas a la entidad (${egresos.filter(e => e.entidadId === id || (!e.entidadId && impNorm(e.nombre) === impNorm(x.razonSocial))).length}). Queda en el historial de cada una.</p><p class="ua-err" id="uaErr"></p>`, 'Guardar entidad');
  const dvSug = () => { const n = entNitLimpio(document.getElementById('entLNit').value), dv = document.getElementById('entLDv'); if (n && !dv.value) dv.placeholder = entDvCalc(n); };
  document.getElementById('entLNit').addEventListener('input', dvSug); dvSug();
  document.getElementById('uaOk').onclick = async () => {
    const nombre = document.getElementById('entLNombre').value.trim().replace(/\s+/g,' '), nit = entNitLimpio(document.getElementById('entLNit').value);
    const dv = (document.getElementById('entLDv').value.replace(/\D/g,'') || (nit ? entDvCalc(nit) : '')).slice(0,1), err = document.getElementById('uaErr');
    if (!nombre) { err.textContent = 'Escribe el nombre.'; return; }
    if (nit && (nit.length < 5 || nit.length > 15)) { err.textContent = 'El NIT debe tener entre 5 y 15 dígitos.'; return; }
    const dup = entBuscarDuplicados(nombre, nit, id).find(d => d.tipo === 'igual'); if (dup) { err.textContent = `Ya existe «${dup.ent.razonSocial}» (${dup.motivo}).`; return; }
    const antes = x.razonSocial;
    try { await entActualizar(id, { razonSocial: nombre, nit, dv }); const n = await entPropagarNombre(id, antes, nombre);
      if (document.getElementById('eEntidadId')?.value === id) { document.getElementById('eNombre').value = nombre; try { entRefrescarSeleccion(); } catch (e) {} }
      toast(`Entidad actualizada${n ? `: ${n} factura(s) con el nombre nuevo` : ''}.`, 'success'); uaCerrar(); }
    catch (e) { err.textContent = 'No se pudo guardar: ' + e.message; }
  };
};
window.entCatActivo = async (id, activar) => {
  const x = entPorId(id); if (!x) return;
  if (!activar && !confirm(`¿Inactivar «${x.razonSocial}»? Deja de aparecer en el selector; sus facturas y liquidaciones no cambian.`)) return;
  try { await entActualizar(id, { activo: !!activar }); toast(activar ? 'Entidad activada.' : 'Entidad inactivada.','success'); }
  catch (e) { toast('No se pudo cambiar: ' + e.message,'error'); }
};
/* Escribe entidadId en facturas a la entidad (solo esa referencia; nada más cambia). Lotes atómicos de hasta 400. */
/* ── Entidad de una tabla de liquidación (formulario de tabla) ── */
function tablaEntidadOpts(selId){
  const s = document.getElementById('tablaEntidad'); if (!s) return;
  s.innerHTML = `<option value="">— Elige la entidad —</option>` + entActivas().map(x => `<option value="${x.id}">${escHtml(x.razonSocial)}</option>`).join('');
  s.value = selId && entPorId(selId) ? selId : '';
}

function uroMadresFiltradas(){
  const f = uroFiltrosMadre();
  return egresos.filter(e => {
    const hm = String(e.honorarioMes||'');
    if (f.anio && hm.slice(0,4) !== f.anio) return false;
    if (f.mes && hm.slice(5,7) !== f.mes) return false;
    if (f.entidad) {   // catálogo único: por entidad (referencia o nombre idéntico); nombres antiguos sin entidad, por su nombre
      const x = entDe(e);
      if (f.entidad.startsWith('ent:') ? (!x || 'ent:' + x.id !== f.entidad) : (x || 'nom:' + impNorm(e.nombre) !== f.entidad)) return false;
    }
    if (f.estado) { const est = egmEstadoEgreso(e).estado;
      if (f.estado === 'cobro' && est !== 'En cobro') return false;
      if (f.estado === 'giro' && est !== 'Cobrada · pendiente giro') return false;
      if (f.estado === 'cerrada' && est !== 'Cerrada') return false; }
    if (f.q) {
      const blob = _ufNorm([e.factura, e.concepto, e.nombre,
        ...(e.hijas||[]).flatMap(h=>[h.factura, h.nombre, h.concepto])].join(' '));
      if (!blob.includes(f.q)) return false;
    }
    return true;
  });
}
/* Rellena los selects de filtros conservando lo elegido */
function uroPoblarFiltrosMadre(){
  const setOpts = (id, opts, todos) => {
    const el = document.getElementById(id); if (!el) return;
    const prev = el.value;
    el.innerHTML = `<option value="">${todos}</option>` + opts.map(([v,l])=>`<option value="${escHtml(v)}">${escHtml(l)}</option>`).join('');
    if (opts.some(([v])=>v===prev)) el.value = prev;
  };
  const anios = [...new Set(egresos.map(e=>String(e.honorarioMes||'').slice(0,4)).filter(a=>/^\d{4}$/.test(a)))].sort().reverse();
  setOpts('ufAnio', anios.map(a=>[a,a]), 'Todos los años');
  if (!_ufAnioInicial && anios.length){
    _ufAnioInicial = true;
    const actual = String(new Date().getFullYear());
    const el = document.getElementById('ufAnio');
    if (el && anios.includes(actual)) el.value = actual;
  }
  setOpts('ufMes', MESES_NOMBRE.map((m,i)=>[String(i+1).padStart(2,'0'), m]), 'Todos los meses');
  { const conFact = new Set(egresos.map(e => entDe(e)?.id).filter(Boolean));
    const sueltos = new Map(); egresos.forEach(e => { if (!entDe(e) && String(e.nombre||'').trim()) sueltos.set('nom:' + impNorm(e.nombre), String(e.nombre).trim() + ' (sin entidad)'); });
    setOpts('ufEntidad', [...entidades.filter(x => conFact.has(x.id) || x.activo !== false).sort((a,b)=>String(a.razonSocial).localeCompare(String(b.razonSocial),'es',{sensitivity:'base'})).map(x => ['ent:' + x.id, x.razonSocial + (x.activo === false ? ' (inactiva)' : '')]), ...sueltos.entries()], 'Todas las entidades'); }
}
window.uroFiltroMadre = () => { _uroMPag = 1; renderEgresoTable(); };
window.uroLimpiarFiltrosMadre = () => {
  ['ufAnio','ufMes','ufEntidad','ufEstado','ufBuscar'].forEach(id=>{ const el=document.getElementById(id); if (el) el.value=''; });
  renderEgresoTable();
};
function uroKpisMadres(lista){
  const box = document.getElementById('uroKpisMadres'); if (!box) return;
  const nH  = lista.reduce((s,e)=>s+(e.hijas||[]).length,0);
  const vEnt = lista.reduce((s,e)=>s+(Number(e.valorEntidad)||0),0);
  const vEsp = lista.reduce((s,e)=>s+(Number(e.valorEspecialista)||0),0);
  const pend = lista.filter(e=>!e.fechaPago).length;
  const k = (lbl, val, cls='') => `<div class="uro-kpi ${cls}"><div class="uro-kpi-l">${lbl}</div><div class="uro-kpi-v">${val}</div></div>`;
  box.innerHTML =
    k('Facturas a la entidad', lista.length) +
    k('Liquidaciones de especialistas', nH) +
    k('Valor entidad', fmtCOP(vEnt)) +
    k('Valor especialistas', fmtCOP(vEsp), 'acento') +
    k('Pendientes de pago', pend ? `${pend} <small>de ${lista.length}</small>` : (lista.length ? 'Ninguna' : '—'));
  const sub = document.getElementById('uroMadresSub');
  if (sub) sub.textContent = lista.length === egresos.length
    ? `${egresos.length} factura${egresos.length!==1?'s':''} a la entidad · todas`
    : `Mostrando ${lista.length} de ${egresos.length} facturas a la entidad según los filtros`;
}

function renderEgresoTable() {
  uroContadoresTabs();
  if (!document.querySelector('.uro-tab.on')) uroTab(_uroTabActual);
  renderUroResumen();
  const tbody = document.getElementById('egresoBody');
  const empty = document.getElementById('egresoEmpty');
  if (!tbody) return;
  uroPoblarFiltrosMadre();
  const lista = uroMadresFiltradas();
  const sub = document.getElementById('uroMadresSub');
  if (sub) sub.textContent = lista.length === egresos.length
    ? `${egresos.length} factura${egresos.length!==1?'s':''} emitida${egresos.length!==1?'s':''} a las entidades`
    : `${lista.length} de ${egresos.length} facturas según los filtros`;
  const pag = document.getElementById('uroMadresPag');
  if (!egresos.length) { tbody.innerHTML=''; empty.style.display='flex'; if (pag) pag.innerHTML=''; return; }
  empty.style.display='none';
  if (!lista.length) {
    tbody.innerHTML = `<tr class="uro-sin-res"><td colspan="10">
      <strong>Ninguna factura a la entidad coincide con los filtros.</strong>
      <span>Las demás siguen guardadas.</span>
      <button class="uro-btn sec sm" type="button" onclick="uroLimpiarFiltrosMadre()">Ver todas</button></td></tr>`;
    if (pag) pag.innerHTML = '';
    return;
  }
  // Más recientes primero: fecha de facturación, luego mes de honorario, luego número (orden numérico)
  const clave = e => String(e.fechaFacturacion || (e.honorarioMes ? e.honorarioMes+'-00' : ''));
  lista.sort((a,b) => clave(b).localeCompare(clave(a))
    || String(b.factura||'').localeCompare(String(a.factura||''),'es',{numeric:true}));
  const total = lista.length;
  const paginas = Math.max(1, Math.ceil(total / _uroMTam));
  if (_uroMPag > paginas) _uroMPag = paginas;
  const desde = (_uroMPag-1) * _uroMTam;
  const pagina = lista.slice(desde, desde + _uroMTam);

  const madreHtml = (e) => {
    const hijas = e.hijas||[];
    const totalHijas = hijas.reduce((s,h)=>s+(Number(h.valorEspecialista)||0),0);
    const totalEntidadHijas = hijas.reduce((s,h)=>s+(Number(h.valorEntidad)||0),0);
    const totalAdminHijas   = hijas.reduce((s,h)=>s+(Number(h.administracion)||0),0);
    const entidadMadre = Number(e.valorEntidad)||0;
    const difEntidad = entidadMadre - totalEntidadHijas;
    const hayDif = hijas.length && Math.abs(difEntidad) > 0.5;
    const fecha = e.fechaFacturacion ? fmtFechaLegible(e.fechaFacturacion) : (e.honorarioMes ? etiquetaMes(e.honorarioMes).replace(/^(\w{3})\w*/, '$1') : '—');
    let h = `<tr class="egr-madre" onclick="toggleHijas('${e.id}')">
      <td class="egr-expand-cell"><i class="fa-solid fa-chevron-right egr-expand-icon" id="icon-${e.id}" aria-hidden="true"></i></td>
      <td class="uro-nowrap">${escHtml(fecha)}</td>
      <td class="uro-fac">${escHtml(e.factura||'—')}</td>
      <td class="uro-con"><span class="uro-clamp" title="${escHtml(e.concepto||'')}">${escHtml(e.concepto||'—')}</span></td>
      <td class="uro-entc"><span class="uro-clamp" title="${escHtml(e.nombre||'')}">${escHtml(e.nombre||'—')}</span></td>
      <td class="td-num">${fmtCOP(e.valorEntidad)}${Number(e.administracion) ? `<span class="uro-cell-sub">Adm. ${fmtCOP(e.administracion)}</span>` : ''}</td>
      <td class="td-num egr-val-esp ${Number(e.valorEspecialista)?'':'uro-cero'}">${fmtCOP(e.valorEspecialista)}</td>
      <td class="td-num"><span class="uro-nh ${hijas.length?'':'cero'}">${hijas.length}</span></td>
      <td>${(() => { const r = egmEstadoEgreso(e); const cls = { verde:'ok', ambar:'warn', rojo:'pend', gris:'gris' }[r.estadoCls] || 'gris';
          const det = r.estado === 'En cobro' ? `Saldo por cobrar ${fmtCOP(r.saldoCobrar)}` : r.estado === 'Cobrada · pendiente giro' ? `Por girar a especialistas ${fmtCOP(r.valorPagar)}` : r.estado;
          return `<span class="uro-pill ${cls}" title="${escHtml(det + (e.fechaPago ? ' · Fecha de pago registrada: ' + fmtFechaLegible(e.fechaPago) : ''))}">${escHtml(r.estado)}</span>`; })()}</td>
      <td><div class="tbl-actions">
          ${compBotonTabla(e.id, '', null)}
          <button class="uro-ico" type="button" title="Editar" aria-label="Editar ${escHtml(e.factura||'')}" onclick="event.stopPropagation();openEgresoModal('${e.id}')"><i class="fa-solid fa-pen"></i></button>
          <button class="uro-ico del" type="button" title="Eliminar" aria-label="Eliminar ${escHtml(e.factura||'')}" onclick="event.stopPropagation();deleteEgreso('${e.id}')"><i class="fa-solid fa-trash"></i></button>
      </div></td>
    </tr>`;
    // Liquidaciones de especialistas: panel anidado dentro de la factura a la entidad (se abre al hacer clic en la fila)
    const hijasHtml = hijas.length ? hijas.map((hj, hi) => `<tr>
        <td><span class="uro-hfac">${escHtml(hj.factura||'—')}</span></td>
        <td class="uro-hesp">${escHtml(hj.nombre||'—')}</td>
        <td class="uro-muted">${escHtml(hj.concepto||'—')}</td>
        <td class="uro-muted uro-nowrap">${hj.honorarioMes ? escHtml(etiquetaMes(hj.honorarioMes)) : '—'}</td>
        <td class="td-num">${fmtCOP(hj.valorEntidad)}</td>
        <td class="td-num uro-muted">${fmtCOP(hj.administracion)}</td>
        <td class="td-num uro-hval">${fmtCOP(hj.valorEspecialista)}</td>
        <td class="td-num">${compBotonTabla(e.id, hj.hid||'', hi)}</td>
      </tr>`).join('') : '';
    h += `<tr class="egr-hija-row uro-hpanel-row" data-parent="${e.id}" style="display:none"><td colspan="10">
      <div class="uro-hpanel">
        <div class="uro-hpanel-h">
          <span class="uro-hpanel-t"><i class="fa-solid fa-layer-group" aria-hidden="true"></i> Liquidaciones de especialistas de ${escHtml(e.factura||'esta factura a la entidad')}</span>
          ${hijas.length ? (hayDif
            ? `<span class="uro-pill warn"><i class="fa-solid fa-triangle-exclamation"></i>&nbsp;${difEntidad > 0 ? 'Faltan' : 'Sobran'} ${fmtCOP(Math.abs(difEntidad))} frente a la factura</span>`
            : `<span class="uro-pill ok"><i class="fa-solid fa-circle-check"></i>&nbsp;Conciliado con la factura a la entidad</span>`) : ''}
        </div>
        ${hijas.length ? `<table class="uro-htable">
          <thead><tr><th>Factura</th><th>Especialista</th><th>Concepto</th><th>Mes</th><th class="th-num">Valor entidad</th><th class="th-num">Administración</th><th class="th-num">Valor especialista</th><th class="th-num">Soporte</th></tr></thead>
          <tbody>${hijasHtml}</tbody>
          <tfoot><tr><td colspan="4">Total ${hijas.length} liquidación${hijas.length!==1?'s':''}</td>
            <td class="td-num">${fmtCOP(totalEntidadHijas)}</td><td class="td-num">${fmtCOP(totalAdminHijas)}</td><td class="td-num uro-hval">${fmtCOP(totalHijas)}</td><td></td></tr></tfoot>
        </table>` : `<p class="uro-hvacio">Esta factura a la entidad aún no tiene liquidaciones de especialistas. Agrégalas desde Editar.</p>`}
      </div></td></tr>`;
    return h;
  };
  tbody.innerHTML = pagina.map(madreHtml).join('');

  // Paginación
  if (pag) {
    const nums = [];
    for (let i=1;i<=paginas;i++) if (i===1 || i===paginas || Math.abs(i-_uroMPag)<=1) nums.push(i); else if (nums[nums.length-1] !== '…') nums.push('…');
    pag.innerHTML = `<span>Mostrando ${desde+1} a ${Math.min(desde+_uroMTam,total)} de ${total} factura${total!==1?'s':''}</span>
      <div class="uro-pag-n">
        <button type="button" class="uro-pg" aria-label="Página anterior" ${_uroMPag<=1?'disabled':''} onclick="uroMPagina(${_uroMPag-1})"><i class="fa-solid fa-chevron-left"></i></button>
        ${nums.map(n => n==='…' ? '<span class="uro-pg-e">…</span>' : `<button type="button" class="uro-pg ${n===_uroMPag?'on':''}" ${n===_uroMPag?'aria-current="page"':''} onclick="uroMPagina(${n})">${n}</button>`).join('')}
        <button type="button" class="uro-pg" aria-label="Página siguiente" ${_uroMPag>=paginas?'disabled':''} onclick="uroMPagina(${_uroMPag+1})"><i class="fa-solid fa-chevron-right"></i></button>
      </div>
      <label class="uro-pg-tam">Por página <select onchange="uroMTamano(this.value)">${[10,25,50,100].map(n=>`<option ${n===_uroMTam?'selected':''}>${n}</option>`).join('')}</select></label>`;
  }
}
let _uroMPag = 1, _uroMTam = 10;
window.uroMPagina = (n) => { _uroMPag = Math.max(1, n); renderEgresoTable(); document.getElementById('uroPanelMadres')?.scrollIntoView({ block:'start', behavior:'smooth' }); };
window.uroMTamano = (n) => { _uroMTam = Number(n)||10; _uroMPag = 1; renderEgresoTable(); };

/* ══ RESUMEN: indicadores del periodo y tarjetas por entidad ══
   Todo sale de datos guardados: facturas a la entidad (valor entidad / especialista)
   y filas de las tablas (valor a pagar y pagos registrados). No se estima nada. */
let _uroPeriodo = null;   // 'YYYY-MM' | '' (todos) | null (aún no elegido)
window.uroCambiarPeriodo = (v) => { _uroPeriodo = v; renderUroResumen(); };
function uroPeriodos(){ return [...new Set(egresos.map(e=>String(e.honorarioMes||'').slice(0,7)).filter(m=>/^\d{4}-\d{2}$/.test(m)))].sort().reverse(); }
function uroFilaEnPeriodo(f, periodo){
  if (!periodo) return true;
  const madre = egresos.find(e=>e.id===f.identId);
  const mes = madre ? String(madre.honorarioMes||'') : String(f.mes||'');
  return mes.slice(0,7) === periodo;
}
function renderUroResumen(){
  const box = document.getElementById('uroResumen'); if (!box) return;
  const periodos = uroPeriodos();
  if (_uroPeriodo === null) _uroPeriodo = periodos[0] || '';
  if (_uroPeriodo && !periodos.includes(_uroPeriodo)) _uroPeriodo = periodos[0] || '';
  const P = _uroPeriodo;
  const madres = egresos.filter(e => !P || String(e.honorarioMes||'').slice(0,7) === P);
  const nHijas = madres.reduce((s,e)=>s+(e.hijas||[]).length,0);
  const facturado = madres.reduce((s,e)=>s+(Number(e.valorEntidad)||0),0);
  const valEsp = madres.reduce((s,e)=>s+(Number(e.valorEspecialista)||0),0);
  const filas = tablasEgreso.flatMap(t => (t.filas||[]).filter(f => uroFilaEnPeriodo(f,P)));
  const porPagar = filas.reduce((s,f)=>s+(Number(f.valorPagar)||0),0);
  const conSaldo = filas.filter(f=>(Number(f.valorPagar)||0) > 0).length;
  const pagos = filas.flatMap(f=>f.pagos||[]);
  const pagado = pagos.reduce((s,p)=>s+(Number(p.monto)||0),0);
  const sinPago = madres.filter(e=>!e.fechaPago).length;
  const card = (cls, ico, lbl, val, sub) => `<div class="uro-kc ${cls}">
      <span class="uro-kc-i" aria-hidden="true"><i class="fa-solid ${ico}"></i></span>
      <div class="uro-kc-b"><div class="uro-kc-l">${lbl}</div><div class="uro-kc-v">${val}</div><div class="uro-kc-s">${sub}</div></div>
    </div>`;
  const ents = [...tablasEgreso].sort((a,b)=>String(a.nombre||'').localeCompare(String(b.nombre||''),'es')).map(t => {
    const fs = (t.filas||[]).filter(f => uroFilaEnPeriodo(f,P));
    const idsM = [...new Set(fs.map(f=>f.identId).filter(id => egresos.some(e=>e.id===id)))];
    const fact = idsM.reduce((s,id)=>s+(Number(egresos.find(e=>e.id===id)?.valorEntidad)||0),0);
    const pp = fs.reduce((s,f)=>s+(Number(f.valorPagar)||0),0);
    const pend = fs.filter(f=>uroLiqCalc(f).estado==='pend' || uroLiqCalc(f).estado==='parcial').length;
    return `<button type="button" class="uro-ec" onclick="uroAbrirEntidad('${t.id}')">
      <span class="uro-ec-h">
        ${(t.logoDer||t.logoIzq) ? `<img src="${t.logoDer||t.logoIzq}" alt=""/>` : `<span class="uro-ec-ini" aria-hidden="true">${escHtml((t.nombre||'?').replace(/^tabla\s+/i,'').slice(0,2).toUpperCase())}</span>`}
        <span class="uro-ec-n">${escHtml(t.nombre||'Sin nombre')}</span>
      </span>
      <span class="uro-ec-r"><span>Facturado</span><b>${idsM.length ? fmtCOP(fact) : '—'}</b></span>
      <span class="uro-ec-r"><span>Por pagar</span><b class="acc">${fs.length ? fmtCOP(pp) : '—'}</b></span>
      <span class="uro-ec-f"><span>${idsM.length} factura${idsM.length!==1?'s':''} a la entidad / ${fs.length} fila${fs.length!==1?'s':''}${pend ? ` · ${pend} sin pagar` : ''}</span><span class="uro-ec-go" aria-hidden="true"><i class="fa-solid fa-arrow-right"></i></span></span>
    </button>`;
  }).join('');
  box.innerHTML = `
    <div class="uro-res-top">
      <h2 class="uro-sec-t">Resumen del periodo</h2>
      <label class="uro-periodo"><i class="fa-regular fa-calendar" aria-hidden="true"></i>
        <span class="uro-sr">Periodo</span>
        <select onchange="uroCambiarPeriodo(this.value)">
          <option value="" ${!P?'selected':''}>Todos los periodos</option>
          ${periodos.map(m=>`<option value="${m}" ${m===P?'selected':''}>${escHtml(etiquetaMes(m))}</option>`).join('')}
        </select></label>
    </div>
    <div class="uro-kcs">
      ${card('c-verde','fa-file-invoice','Facturado a entidades', fmtCOP(facturado), `${madres.length} factura${madres.length!==1?'s':''} a la entidad${sinPago?` · ${sinPago} sin fecha de pago`:''}`)}
      ${card('c-azul','fa-user-doctor','Valor especialistas', fmtCOP(valEsp), `${nHijas} factura${nHijas!==1?'s':''} liquidación${nHijas!==1?'s':''}`)}
      ${card('c-naranja','fa-hourglass-half','Por pagar a especialistas', fmtCOP(porPagar), `${conSaldo} fila${conSaldo!==1?'s':''} con saldo en las tablas`)}
      ${card('c-morado','fa-hand-holding-dollar','Pagos registrados', fmtCOP(pagado), `${pagos.length} pago${pagos.length!==1?'s':''} anotado${pagos.length!==1?'s':''}`)}
    </div>
    <div class="uro-res-top">
      <h2 class="uro-sec-t">Entidades</h2>
      <button class="uro-btn ghost sm" type="button" onclick="openTablaModal()"><i class="fa-solid fa-plus"></i> Nueva tabla</button>
    </div>
    ${ents ? `<div class="uro-ecs">${ents}</div>` : `<div class="uro-vacio-grande"><h2>Aún no hay tablas de liquidación</h2><p>Crea una tabla por entidad para liquidar a sus especialistas.</p><button class="uro-btn pri" type="button" onclick="openTablaModal()"><i class="fa-solid fa-plus"></i> Nueva tabla</button></div>`}
    <p class="uro-nota" style="padding:12px 2px 0">«Por pagar» suma el valor a pagar guardado en cada fila (neto menos pagos registrados). El periodo se toma del mes de honorarios de la factura a la entidad.</p>`;
}
window.uroAbrirEntidad = (id) => { _uroTablaActiva = id; uroTab('liq'); renderCustomTables(); window.scrollTo({ top:0, behavior:'smooth' }); };

function agruparPorMesMadre(items){
  const map = new Map();
  items.forEach(e => {
    const clave = (e.honorarioMes||'').trim() || 'sin-mes';
    if (!map.has(clave)) map.set(clave, []);
    map.get(clave).push(e);
  });
  const claves = [...map.keys()].sort((a,b)=>{
    if (a === 'sin-mes') return 1;
    if (b === 'sin-mes') return -1;
    return b.localeCompare(a);
  });
  return claves.map(clave => ({ clave, etiqueta: etiquetaMes(clave), items: map.get(clave) }));
}

/* Expandir / contraer un grupo de mes de facturas a la entidad */
window.toggleGrupoMadre = (clave, filaCab) => {
  const key = `madre|${clave}`;
  const colapsar = !grupoColapsado[key];
  grupoColapsado[key] = colapsar;
  persistirGrupoColapsado();
  filaCab.classList.toggle('colapsado', colapsar);
  const tbody = document.getElementById('egresoBody');
  if (!tbody) return;
  tbody.querySelectorAll(`tr[data-mgroup-row="${cssEscapa(clave)}"]`).forEach(tr=>{
    if (colapsar) {
      tr.style.display = 'none';
    } else {
      // Al expandir el grupo: mostrar madres; hijas quedan ocultas hasta abrir cada factura a la entidad
      if (tr.classList.contains('egr-madre')) tr.style.display = '';
      else tr.style.display = 'none';
      // reset del ícono de expansión de cada factura a la entidad
      if (tr.classList.contains('egr-madre')) {
        const ic = tr.querySelector('.egr-expand-icon');
        ic?.classList.remove('open');
      }
    }
  });
}

window.toggleHijas = (id) => {
  const icon = document.getElementById('icon-'+id);
  const rows = document.querySelectorAll(`[data-parent="${id}"]`);
  const open = [...rows].some(r => r.style.display !== 'none');
  rows.forEach(r => r.style.display = open ? 'none' : 'table-row');
  icon?.classList.toggle('open', !open);
  icon?.closest('tr')?.classList.toggle('abierta', !open);
};

/* ══ MODAL EGRESO ══ */
window.openEgresoModal = (id=null) => {
  editEgresoId = id;
  const e = id ? egresos.find(x=>x.id===id) : null;
  document.getElementById('egresoModalTitle').textContent = id?'Editar Egreso':'Nuevo Egreso';
  document.getElementById('egresoId').value = id||'';
  { const hb = document.getElementById('hijasBody'); if (hb) hb.innerHTML = ''; }   // que el resumen no lea hijas del registro abierto antes
  document.getElementById('eFechaFacturacion').value = e?.fechaFacturacion||'';
  document.getElementById('eHonorarioMes').value = e?.honorarioMes||'';
  document.getElementById('eConcepto').value = e?.concepto||'';
  entCargarEnFormulario(e);   // entidad del catálogo + NIT
  document.getElementById('eFactura').value = e?.factura||'';
  document.getElementById('eValorEntidad').value = e?.valorEntidad||'';
  document.getElementById('eNotaCredito').value = e?.notaCredito||'';   // se muestra como «Glosa» (mismo campo y misma resta)
  document.getElementById('eNotaCreditoNum').value = e?.notaCreditoNumero||'';
  document.getElementById('eAdministracion').value = e?.administracion||'';
  document.getElementById('eValorEspecialista').value = e?.valorEspecialista||'';
  document.getElementById('eFechaPago').value = e?.fechaPago||'';
  document.getElementById('eNotas').value = e?.notas||'';
  // Editar: respetar ICA/Rete guardados (pueden ser manuales). Nuevo: auto-calcular.
  egmPrepararAutos(e);
  if (e) {
    document.getElementById('eIca').value = (e.ica ?? '') === '' ? '' : e.ica;
    document.getElementById('eReteHonorarios').value = (e.reteHonorarios ?? '') === '' ? '' : e.reteHonorarios;
    calcEgresoNeto('abrir');   // ICA guardado se respeta; la retención se respeta si es digitada (certificado) y si no se recalcula sobre la base
  } else {
    calcEgresoNeto();       // egreso nuevo: ICA y Rete automáticos
  }
  localHijas = e?.hijas ? JSON.parse(JSON.stringify(e.hijas)) : [];
  localAbonos = (Array.isArray(e?.abonos) ? JSON.parse(JSON.stringify(e.abonos)) : []).map(egmAbonoNormalizar);
  _abonosQuitados = [];
  egmRenderAbonos();
  const bq = document.getElementById('egmHijasBuscar'); if (bq) bq.value = '';
  compSubscribe();
  renderHijasTable();
  compRenderSeccionModal();
  document.getElementById('egresoModal').classList.add('open');
  // 9.9 · candado: las facturas ya revisadas se cierran al abrirlas
  try { if (id && segRevisada(id) && !e?.candado?.cerrado) segCerrar(id, 'Revisada por Facturación y por Contabilidad'); segPintarCandado(); } catch (eSeg) { console.warn(eSeg); }
};

/* Valor consignado Entidad (en pantalla «Neto entidad · total a consignar») = Valor entidad − Glosa − ICA − Retención.
   Retención = REDONDEAR(Valor entidad × 11 %) − REDONDEAR(Glosa × 11 %): automática hasta que se digita a mano (certificado de la entidad).
   ICA = REDONDEAR(Valor entidad × 10 / 1000): automático hasta que se digita a mano.
   origen: true = se está digitando ICA/Retención · 'abrir' = al abrir un registro · (vacío) = cambió Valor entidad o Glosa */
window.calcEgresoNeto = (origen) => {
  const entidad = Number(document.getElementById('eValorEntidad')?.value)||0;
  const nota    = Number(document.getElementById('eNotaCredito')?.value)||0;
  const elIca = document.getElementById('eIca');
  const elRet = document.getElementById('eReteHonorarios');
  if (origen !== true) {
    if (elIca && origen !== 'abrir' && elIca.dataset.manual !== '1') elIca.value = Math.round(entidad * 10 / 1000);
    if (elRet && elRet.dataset.manual !== '1') elRet.value = egmReteAuto(entidad, nota);   // 11 % del facturado − 11 % de la glosa
  }
  const ica     = Number(elIca?.value)||0;
  const reteHon = Number(elRet?.value)||0;
  const neto = entidad - nota - ica - reteHon;
  const el = document.getElementById('eValorEntidadNeto');
  if(el) el.value = neto;
  egmResumen();
};

let _uroVolverAMadres = null;   // tabla cuyo selector de factura a la entidads se reabre al cerrar la factura creada desde allí
window.closeEgresoModal = () => {
  document.getElementById('egresoModal').classList.remove('open');
  editEgresoId = null; localHijas = [];
  document.getElementById('entLista') && (document.getElementById('entLista').hidden = true);
  if (_uroVolverAMadres) { const t = _uroVolverAMadres; _uroVolverAMadres = null; setTimeout(() => uroAbrirMadres(t), 50); }
};

/* Pasa a localHijas lo que está escrito en pantalla antes de volver a pintar la tabla
   (antes, añadir o quitar una liquidación borraba los cambios sin guardar de las demás filas). */
function egmSyncHijasDesdeDOM(){
  document.querySelectorAll('#hijasBody tr').forEach(row => {
    const h = localHijas[Number(row.dataset.i)]; if (!h) return;
    const g = sel => row.querySelector(sel);
    Object.assign(h, {
      fechaFacturacion: g('.hija-fecha')?.value||'', honorarioMes: g('.hija-mes')?.value||'',
      concepto: g('.hija-concepto')?.value.trim()||'', nombre: g('.hija-nombre')?.value||'',
      tipoPersona: g('.hija-tipopersona')?.value||'', proveedor: g('.hija-proveedor')?.value.trim()||'',
      factura: g('.hija-factura')?.value.trim()||'',
      valorEntidad: Number(g('.hija-entidad')?.value)||0, administracion: Number(g('.hija-admin')?.value)||0,
      valorEspecialista: Number(g('.hija-valor')?.value)||0,
      adminModo: g('.hija-admin-modo')?.value||'directo', adminPct: Number(g('.hija-admin-pct')?.value)||0,
      razonId: row.dataset.razonId || '',
      ...egmAdminDatosFila(row),
    });
  });
}
window.addHijaRow = () => {
  egmSyncHijasDesdeDOM();
  localHijas.push({factura:'', concepto:'', valor:0});
  renderHijasTable();
  // la liquidación nueva queda abierta para diligenciarla completa
  const filas = document.querySelectorAll('#hijasBody tr'); const ult = filas[filas.length-1];
  if (ult) { ult.classList.add('abierta'); ult.querySelector('.egm-hdet')?.setAttribute('aria-expanded','true'); ult.scrollIntoView({ block:'nearest', behavior:'smooth' }); ult.querySelector('.hija-factura')?.focus(); }
};
window.egmToggleHija = (btn) => {
  const tr = btn.closest('tr'); if (!tr) return;
  const abierta = tr.classList.toggle('abierta');
  btn.setAttribute('aria-expanded', abierta ? 'true' : 'false');
};

window.removeHijaRow = (i) => {
  egmSyncHijasDesdeDOM();
  localHijas.splice(i,1);
  renderHijasTable();
};

