  (d.completitud||[]).filter(f => f.aviso).forEach(f => alertas.push({ bloque:2, info:true, texto: f.txt, detalle: f.det }));
  (d.aFavor||[]).forEach(a => alertas.push({ bloque:2, info:true, texto:`${a.nombre} tiene ${fmtCOP(a.monto)} pagados de más en ${a.factura} (a favor de Uroexpertos)`, detalle:'Descuéntalo a mano en el giro de esta factura.' }));
  if (pagosRealizados > 0 && pctPagado - pctCobrado > 0.0005) alertas.push({ bloque:2, texto:'Pagos a especialistas por encima de lo cobrado', detalle:`Pagado ${Math.round(pctPagado*100)}% · cobrado ${Math.round(pctCobrado*100)}%` });
