  l(`(−) Consignado por la entidad (${nAbonos} ${nAbonos === 1 ? 'abono' : 'abonos'})`, abonos, 'Suma de los abonos registrados');
  l('(=) Saldo por cobrar', saldoCobrar, 'Total a consignar − Consignado', { t:true, saldo:true });
