  l('(−) Total descuentos', totalDescuentos, 'Suma de descuentos en la liquidación de cada liquidación');
  l('(=) Neto liquidado', netoLiquidado, 'Honorarios brutos − Total descuentos', { t:true });
  l('(−) Pagos realizados', pagosRealizados, 'Suma de los pagos registrados en la liquidación');
  if (pagadoDeMas >= 1) l('(+) Pagado de más a especialistas', pagadoDeMas, 'A favor de Uroexpertos: se descuenta en la siguiente factura');
  l('(=) Valor a pagar', valorPagar, 'Suma de lo que se debe a cada especialista', { t:true, saldo:true });
  b('3. Glosa y resultado');
