  l('Queda en Uroexpertos (caja)', queda, 'Total a consignar − Neto liquidado' + (otrosDesc ? ' − Otros descuentos' : ''), { t:true });
  l('Anticipo de renta (retención de la entidad)', anticipoRenta, 'Se recupera en la declaración de renta');
  l('(=) Resultado Uroexpertos', resultado, 'Queda en Uroexpertos + Anticipo de renta', { t:true });
