  const ta = A.split(' ').filter(t => t.length > 2), tb = B.split(' ').filter(t => t.length > 2);
  const comunes = ta.filter(t => tb.some(u => u === t || (t.length > 4 && u.length > 4 && (u.startsWith(t) || t.startsWith(u))))).length;
