  const u = egmUnirHijasLiquidacion(d.id, hijas.map(h => ({ ...h })));
  const sinFila = u.hijas.filter(h => !h.conLiquidacion && (N(h.valorEspecialista) || N(h.valorEntidad)));
  if (sinFila.length) fallas.push({ k:'vinculo', txt:`${sinFila.length} liquidación(es) sin fila vinculada`, det: sinFila.map(h => `${h.factura || 's/n'} · ${h.nombre || ''}`).join(' · ') });
