  if (!_cn.serv && !_cn.horas) { cont.innerHTML = h + '<p class="cn-ayuda">Carga los dos archivos de la Clínica del Norte (o solo uno, si ese mes no hay horas o servicios). Todo se procesa en este navegador: no se guarda nada.</p>'; return; }
  const lista = cnEspecialistas();
  const anioAct = new Date().getFullYear(), anios = []; for (let y = anioAct - 3; y <= anioAct + 1; y++) anios.push(y);
  if (_cn.anio && !anios.includes(_cn.anio)) anios.push(_cn.anio);
