    + ctls.map(c => `<li class="${c.c}"><i class="fa-solid fa-${c.c === 'ok' ? 'circle-check' : c.c === 'mal' ? 'circle-xmark' : 'triangle-exclamation'}"></i><div><b>${escHtml(c.t)}</b>${c.d ? `<small>${escHtml(c.d)}</small>` : ''}</div></li>`).join('') + '</ul></details>';
