  ws.getRow(1).height = 22; ws.getRow(2).height = 22; ws.getRow(3).height = 8;
  ws.mergeCells('C1:F1'); const t = ws.getCell('C1'); t.value = 'LIQUIDACIÓN DE HORAS Y SERVICIOS'; t.font = fuente({ size:14, bold:true, color:{ argb:MOR } }); t.alignment = { horizontal:'right', vertical:'middle' };
  ws.mergeCells('C2:F2'); const s = ws.getCell('C2'); s.value = CN_CLINICA.toUpperCase() + ' · ' + CN_MESES[_cn.mes - 1] + ' de ' + _cn.anio; s.font = fuente({ color:{ argb:'FF646470' } }); s.alignment = { horizontal:'right' };
