const JV_CAMPOS = ['cedula', 'nombre', 'fecha', 'entidad', 'tipo'];
const JV_ETQ = { cedula: 'Cédula', nombre: 'Nombre del paciente', fecha: 'Fecha del folio', entidad: 'Entidad de ingreso', tipo: 'Tipo de atención', codigo: 'Código', descripcion: 'Descripción del procedimiento' };
