try { speechSynthesis.onvoiceschanged = () => { if (JV2.ajustes) jv2PintarAjustes(); }; } catch (e) {}
/* Texto para leer: sin markdown, montos en pesos, sin cédulas largas */
function jv2TextoVoz(t){
  return String(t || '').replace(/<[^>]+>/g, ' ').replace(/\*\*|__|`|#+\s/g, '').replace(/^\s*(?:[-•*]|\d+[.)])\s+/gm, '')
    .replace(/\$\s?(-?\d{1,3}(?:\.\d{3})*(?:,\d+)?)/g, '$1 pesos').replace(/\b\d{7,}\b/g, ' (dato en pantalla) ').replace(/[_|]/g, ' ').replace(/\s+/g, ' ').trim();
}
function jv2Frases(t){ const out = []; String(t).split(/(?<=[.!?…:;])\s+/).forEach(f => { while (f.length > 190) { const c = f.lastIndexOf(',', 190) > 60 ? f.lastIndexOf(',', 190) + 1 : 190; out.push(f.slice(0, c)); f = f.slice(c).trim(); } if (f.trim()) out.push(f.trim()); }); return out; }
