  if (!it) { JV2V.hablando = false; JV2V.plan = null; JV2V.finMs = Date.now(); if (JV2.estado === 'hablando') JV2.estado = JV2.micOn ? 'escuchando' : 'reposo'; jv2PintarEstado(); jv2RecReanudar(); return; }
  const u = new SpeechSynthesisUtterance(it.f), v = jv2VozElegida();
  if (v) { u.voice = v; u.lang = v.lang; } else u.lang = 'es-CO';
