  jv2Log('user', iaEsc(texto) + (origen === 'voz' ? ' <i class="fa-solid fa-microphone" aria-label="por voz"></i>' : ''));
  JV2.ultimoOrigen = origen;
  if (jv2Local(texto)) return;
  // corrección: si llega otra instrucción mientras analiza la anterior, se cancela la anterior
  if (JV2.ocupado && JV2.abort) { JV2.abort.abort(); JV2.corrigiendo = true; await new Promise(r => setTimeout(r, 30)); }
