    const habia = JV2V.hablando || JV2.ocupado; jv2Callar(); if (JV2.abort) { JV2.abort.abort(); }
    JV2.estado = JV2.micOn ? 'escuchando' : 'reposo'; jv2PintarEstado();
    if (habia) { jv2Frase('De acuerdo.'); jv2Log('bot', '<p>De acuerdo, lo dejo ahí.</p>'); return true; }
