    const abiertos = [...JV2.abiertos].map(k => JV.registros.find(r => r.id === k) || JV.registros.find(r => r.hash === k && r.tipo === JV_CIR)).filter(Boolean);
    const r = quien ? JV.registros.find(x => x.tipo === JV_CIR && jvN(x.nombre + ' ' + x.cedula).includes(quien)) : (abiertos.reverse().find(x => x.tipo === JV_CIR) || JV.registros.filter(x => x.tipo === JV_CIR).slice(-1)[0]);
    if (!r) return di(quien ? `No encuentro una cirugía de ${quien}.` : 'Abre en el panel el paciente que quieres consultar, o dime su nombre.');
