    const tipo = /interconsulta/.test(n) ? 'INTERCONSULTA' : /cirugia/.test(n) ? JV_CIR : /consulta/.test(n) ? 'CONSULTA' : '', estado = /pendiente|revisar/.test(n) ? 'rev' : /validad/.test(n) ? 'ok' : /error/.test(n) ? 'err' : '';
    JV2.filtro = { tipo, estado, q: '', mes: jv2MesDeTexto(n) }; jv2TogglePanelDocs(true); jv2Tab('resultados');
    const k = jv2Resultados().length;
    return di(`${k ? 'Te muestro' : 'No hay'} ${k || ''} ${tipo === 'INTERCONSULTA' ? 'interconsulta' : tipo === 'CONSULTA' ? 'consulta' : tipo === JV_CIR ? 'cirugía' : 'registro'}${k === 1 ? '' : 's'}${estado === 'rev' ? ' por revisar' : estado === 'ok' ? ' validado' + (k === 1 ? '' : 's') : estado === 'err' ? ' con error' : ''}${JV2.filtro.mes ? ' de ' + jv2MesTxt(JV2.filtro.mes) : ''} en el panel.`.replace(/\s+/g, ' '));
