window.toggleTablaCheck = (tablaId, field, val) => {
  const idx = tablasEgreso.findIndex(t=>t.id===tablaId);
  if(idx===-1) return;
  // 9.9 · cada revisión la marca su rol; quitarla de una factura cerrada exige abrir el candado
  if (!segExigir(field === 'contabilidad' ? 'contabilidad' : 'facturacion', `marcar «Revisado por ${field === 'contabilidad' ? 'Contabilidad' : 'Facturación'}»`) || (!val && !segPuedeQuitarRevision(tablaId))) { renderCustomTables(); return; }
  if(field==='contabilidad') tablasEgreso[idx]._chkContabilidad = val;
  if(field==='facturacion')  tablasEgreso[idx]._chkFacturacion  = val;
  // persist to Firestore
  const upd = {};
  upd[field==='contabilidad'?'chkContabilidad':'chkFacturacion'] = val;
  upd[field==='contabilidad'?'chkContabilidadPor':'chkFacturacionPor'] = currentProfile?.nombreCompleto || currentUser?.email || '';
  upd[field==='contabilidad'?'chkContabilidadISO':'chkFacturacionISO'] = new Date().toISOString();
  updateDoc(doc(db,'tablasEgreso',tablaId), upd).then(() => {
    const madres = [...new Set((tablasEgreso[idx]?.filas || []).map(f => f.identId).filter(Boolean))];
    madres.forEach(id => segHistorial(id, [{ accion: val ? 'Marcó revisión' : 'Quitó revisión', campo: `Revisado por ${field === 'contabilidad' ? 'Contabilidad' : 'Facturación'} · ${tablasEgreso[idx]?.nombre || ''}`, despues: val ? 'Sí' : 'No' }]));
    if (val) segTrasRevision(tablaId);
    else madres.forEach(id => { const e = egresos.find(x => x.id === id); if (e?.candado?.cerrado) updateDoc(doc(db,'egresos',id), { 'candado.cerrado': false }).catch(()=>{}); });
  }).catch(e => toast('No se pudo guardar la revisión: ' + e.message, 'error'));
};

/* ── Identificador: cambiar filtro de factura a la entidad ── */
window.onIdentChange = (tablaId, selectEl) =>
  uroAplicarIdents(tablaId, [...selectEl.selectedOptions].map(o=>o.value).filter(Boolean));
/* Aplica la selección de facturas a la entidad de una tabla y trae sus liquidaciones nuevas (sin duplicar) */
/* ¿Esta liquidación ya está en las filas de la tabla? Se revisa de varias formas para no duplicar NUNCA:
   1) mismo id estable de hija (hid);
   2) misma relación madre+posición, siempre que el número de factura no contradiga;
   3) mismo número de factura y mismo especialista (cubre filas viejas, manuales o de otra factura a la entidad). */
const _nrm = v => String(v||'').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,' ');
function uroHijaYaEnFilas(filas, egreso, h, i){
  const key = `${egreso.id}::${i}`;
  const fac = _nrm(h.factura), nom = _nrm(h.nombre);
  return filas.some(f => {
    if (h.hid && f.hid && f.hid === h.hid) return true;
    if (f.hijaKey === key) {
      const ff = _nrm(f.factura);
      if (!(fac && ff && ff !== fac)) return true;
    }
    if (fac && _nrm(f.factura) === fac && (!nom || !f.nombre || _nrm(f.nombre) === nom)) return true;
    return false;
  });
}
const _uroAplicando = {}, _uroPendiente = {};   // candado por tabla: evita importar dos veces con doble clic
/* Solo facturas a la entidad de la misma entidad de la tabla. Devuelve los IDs permitidos. */
function uroMadresDeEntidad(tabla, ids){
  const ent = entDeTabla(tabla);
  if (!ent) return { ok: [], fuera: ids, sinEntidad: true };
  const ok = [], fuera = [];
  ids.forEach(id => { const e = egresos.find(x=>x.id===id); (e && entDe(e)?.id === ent.id ? ok : fuera).push(id); });
  return { ok, fuera, ent };
}
/* Puerta única para asociar facturas a la entidad a una tabla: ninguna vía (selector, select múltiple,
   marcar/desmarcar o una llamada externa) puede asociar madres de otra entidad. */
async function uroAplicarIdents(tablaId, selectedIds) {
  const idx = tablasEgreso.findIndex(t=>t.id===tablaId);
  if (idx===-1) return;
  if (!selectedIds.length) return _uroAplicarIdents(tablaId, selectedIds);
  const chk = uroMadresDeEntidad(tablasEgreso[idx], selectedIds);
  if (chk.sinEntidad) { toast('Esta liquidación aún no tiene entidad. Elígela antes de traer facturas a la entidad.','error'); uroAbrirMadres(tablaId); return; }
  const aviso = chk.fuera.length ? `${chk.fuera.length} factura(s) a la entidad de otra entidad no se asociaron a ${chk.ent.razonSocial}.` : '';
  const actual = uroSelIds(tablasEgreso[idx]);
  if (aviso && chk.ok.length === actual.length && chk.ok.every(id => actual.includes(id))) { toast(aviso,'error'); return; }   // nada más cambió
  await _uroAplicarIdents(tablaId, chk.ok);
  if (aviso) toast(aviso,'error');
}
async function _uroAplicarIdents(tablaId, selectedIds) {
  const idx = tablasEgreso.findIndex(t=>t.id===tablaId);
  if (idx===-1) return;
  tablasEgreso[idx]._selectedIdents = selectedIds;
  tablasEgreso[idx]._selectedIdent  = selectedIds[0]||'';
  renderCustomTables();

  if (!selectedIds.length) return;
  // Si ya se está importando para esta tabla, se repite al terminar con la selección más reciente
  if (_uroAplicando[tablaId]) { _uroPendiente[tablaId] = true; return; }
  _uroAplicando[tablaId] = true;
  try {
    const tabla = tablasEgreso[idx];
    const filas = (tabla.filas||[]).map(f => ({ ...f }));   // 27/11 · E-643: a las filas que ya estaban se les escribe el vínculo
    const nuevas = [], pendientes = [];
    let totalHijasAsociadas = 0, omitidas = 0, vinculadas = 0;
    selectedIds.forEach(egresoId => {
      const egreso = egresos.find(e=>e.id===egresoId);
      if (!egreso) return;
      const hijas = egreso.hijas||[];
      totalHijasAsociadas += hijas.length;
      hijas.forEach((h, i) => {
        if (uroHijaYaEnFilas(nuevas, egreso, h, i)) { omitidas++; return; }
        const m = uroBuscarFila(filas, egreso, h, i);
        if (m && m.tipo === 'ya') { omitidas++; return; }
        if (m && m.tipo === 'exacta') { const f = filas[m.pos]; Object.assign(f, uroVinculo(egresoId, h, i)); if (!f.rowId) f.rowId = genRowId(); vinculadas++; return; }
        if (m && m.tipo === 'probable') { pendientes.push({ egresoId, h, i, fila: filas[m.pos], motivo: m.motivo }); return; }   // no se crea otra fila: se pregunta
        const valorFactura = Number(h.valorEspecialista)||0;
        nuevas.push({
          rowId:        genRowId(),
          hijaKey:      `${egresoId}::${i}`,
          hid:          h.hid || '',
          identId:      egresoId,
          identIds:     [egresoId],
          factura:      h.factura||'',
          mes:          h.honorarioMes||egreso.honorarioMes||'',
          nombre:       h.nombre||egreso.nombre||'',
          tipoPersona:  h.tipoPersona||'',
          valorFactura,
          abono:0, glosa: Math.round(Number(h.glosaImportada)||0), reteFuente:0, afc:0, residentes:0, tiquetes:0, hotel:0, transporte:0,   // 9.12: la glosa de la plantilla pasa a la liquidación
          valorPagar:   valorFactura - Math.round(Number(h.glosaImportada)||0),
          pagos:        [],
          razonId: h.razonId || '',
          ...(() => { const t = regTarifa(regDeEspecialista(h.nombre, h.razonId)); if (!(t > 0)) return {};   // retención según el régimen (se aplica una sola vez, aquí)
            const rf = Math.round(valorFactura * t / 100); return { reteFuente: rf, reteFuenteModo:'pct', reteFuentePct: t, valorPagar: valorFactura - Math.round(Number(h.glosaImportada)||0) - rf }; })(),
        });
      });
    });
    const preguntar = () => { if (!pendientes.length) return;
      const p0 = pendientes[0];
      setTimeout(() => uroVincularAbrir(p0.egresoId, `${pendientes.length} liquidación(es) se parecen a filas que ya estaban (${pendientes.slice(0, 4).map(p => `${p.h.factura || 's/n'} ↔ ${p.fila.factura || 's/n'}: ${p.motivo}`).join(' · ')}${pendientes.length > 4 ? '…' : ''}). No se crearon filas nuevas para ellas: confirma si son la misma.`), 450); };
    if (!nuevas.length && !vinculadas) {
      toast(pendientes.length ? `No se crearon filas: ${pendientes.length} liquidación(es) se parecen a filas existentes. Confírmalas.` : `Sin liquidaciones nuevas por traer: las ${totalHijasAsociadas} ya están en la tabla.`, 'info');
      preguntar();
      return;
    }
    await updateDoc(doc(db,'tablasEgreso',tablaId), { filas: [...filas, ...nuevas], updatedAt: serverTimestamp() });
    toast([nuevas.length && `${nuevas.length} fila${nuevas.length>1?'s':''} nueva${nuevas.length>1?'s':''}`, vinculadas && `${vinculadas} que ya estaba${vinculadas>1?'n':''} quedaron vinculadas`, omitidas && `${omitidas} ya vinculada${omitidas>1?'s':''}`, pendientes.length && `${pendientes.length} por confirmar`].filter(Boolean).join(' · ') + '.', 'success');
    preguntar();
  } catch(e) {
    toast('Error al traer las liquidaciones: '+e.message, 'error');
  } finally {
    _uroAplicando[tablaId] = false;
    if (_uroPendiente[tablaId]) {
      _uroPendiente[tablaId] = false;
      // Esperar a que el cambio guardado llegue a la tabla en memoria antes de volver a comparar
      setTimeout(() => { const t = tablasEgreso.find(x=>x.id===tablaId); if (t) uroAplicarIdents(tablaId, uroSelIds(t)); }, 400);
    }
  }
}

