/* ══ BUSCADOR DE TABLAS ══
   Filtrado en vivo sobre el DOM: instantáneo, sin re-render,
   así el campo no pierde el foco mientras se escribe. */
const busquedaTablas = {};   // { tablaId: texto }

/* Normaliza para comparar: minúsculas, sin tildes, espacios colapsados */
function normBusq(s){
  return String(s||'').toLowerCase().normalize('NFD')
    .replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,' ').trim();
}

window.filtrarTablaBusqueda = (tablaId, texto) => {
  busquedaTablas[tablaId] = texto || '';
  const q    = normBusq(texto);
  const card = document.getElementById('tcard-'+tablaId);
  if (!card) return;

  const filas = card.querySelectorAll('.egr-custom-table tbody tr[data-search]');
  let visibles = 0, total = 0;

  // ¿Cuántos grupos hay y cuántos están abiertos? Si TODOS abiertos → buscar en todo.
  const grupos = [...card.querySelectorAll('.tbl-group-row')];
  const totalGrupos = grupos.length;
  const gruposAbiertos = grupos.filter(gr => {
    const clave = gr.getAttribute('data-group');
    return !grupoColapsado[`${tablaId}|${clave}`];
  }).length;
  // Si hay grupos y no todos están abiertos, la búsqueda se limita a los abiertos
  const limitarAAbiertos = totalGrupos > 0 && gruposAbiertos < totalGrupos;

  filas.forEach(tr => {
    const clave = tr.getAttribute('data-group-row');
    const grupoCerrado = clave && grupoColapsado[`${tablaId}|${clave}`];
    // Con búsqueda: si limitamos a abiertos, las filas de grupos cerrados NO participan
    const participa = !(limitarAAbiertos && grupoCerrado);
    const match = participa && (!q || (tr.getAttribute('data-search')||'').includes(q));
    // Sin búsqueda: respetar el colapso normal
    const mostrar = q ? match : !grupoCerrado;
    tr.style.display = mostrar ? '' : 'none';
    if (q && match){ visibles++; total += Number(tr.getAttribute('data-pagar'))||0; }
    if (!q){ total += (!grupoCerrado ? (Number(tr.getAttribute('data-pagar'))||0) : 0); }
  });

  // Encabezados de grupo
  card.querySelectorAll('.tbl-group-row').forEach(gr => {
    const clave = gr.getAttribute('data-group');
    const cerrado = grupoColapsado[`${tablaId}|${clave}`];
    if (q){
      if (limitarAAbiertos && cerrado){
        // Grupo cerrado no participa en la búsqueda: mostrar encabezado atenuado
        gr.style.display = '';
        gr.classList.add('grupo-fuera-busqueda');
      } else {
        gr.classList.remove('grupo-fuera-busqueda');
        const hayVisibles = [...card.querySelectorAll(`tr[data-group-row="${cssEscapa(clave)}"]`)]
          .some(tr => tr.style.display !== 'none');
        gr.style.display = hayVisibles ? '' : 'none';
      }
    } else {
      gr.style.display = '';
      gr.classList.remove('grupo-fuera-busqueda');
    }
  });

  // Subtotales por grupo: se ocultan mientras hay búsqueda (no reflejarían lo filtrado)
  card.querySelectorAll('.tbl-subtotal').forEach(tr => {
    const clave = tr.getAttribute('data-group-row');
    tr.style.display = (q || grupoColapsado[`${tablaId}|${clave}`]) ? 'none' : '';
  });

  // Mensaje "sin resultados"
  const noRes = card.querySelector('.tbl-no-results');
  if (noRes) noRes.style.display = (q && visibles === 0 && filas.length) ? '' : 'none';

  // Total recalculado sobre lo visible
  const totEl = card.querySelector('.tbl-total-val');
  if (totEl) totEl.textContent = fmtCOP(total);

  // Contador "N de M"
  const cnt = card.querySelector('.ech-search-count');
  if (cnt) cnt.textContent = q ? `${visibles} de ${filas.length}` : '';

  // Botón limpiar visible solo con texto
  const x = card.querySelector('.ech-search-x');
  if (x) x.style.display = q ? '' : 'none';
};

window.limpiarBusquedaTabla = (tablaId) => {
  const inp = document.getElementById('busq-'+tablaId);
  if (inp) inp.value = '';
  filtrarTablaBusqueda(tablaId, '');
  if (inp) inp.focus();
};

/* ══ AGRUPAMIENTO POR MES ══ */
const grupoColapsado = {};   // { "tablaId|clave": true }  → colapsado

/* Persistencia del estado de carpetas (grupos por mes) en Firestore.
   Se guarda con debounce para no escribir en cada clic. */
let _grupoPersistTimer = null;
function persistirGrupoColapsado(){
  clearTimeout(_grupoPersistTimer);
  _grupoPersistTimer = setTimeout(() => {
    const soloCerrados = {};
    Object.keys(grupoColapsado).forEach(k => { if (grupoColapsado[k]) soloCerrados[k] = true; });
    setDoc(doc(db,'uiPrefs','egresosGrupos'), { colapsados: soloCerrados, updatedAt: serverTimestamp() })
      .catch(e => console.warn('No se pudo guardar estado de carpetas:', e));
  }, 500);
}

/* Carga el estado guardado al iniciar la sesión de UROEXPERTOS */
async function cargarGrupoColapsado(){
  try {
    const snap = await getDoc(doc(db,'uiPrefs','egresosGrupos'));
    if (snap.exists()){
      const data = snap.data()?.colapsados || {};
      Object.keys(grupoColapsado).forEach(k => delete grupoColapsado[k]);
      Object.keys(data).forEach(k => { grupoColapsado[k] = true; });
    }
  } catch(e){ console.warn('No se pudo cargar estado de carpetas:', e); }
}
const MESES_NOMBRE = ['Enero','Febrero','Marzo','Abril','Mayo','Junio',
  'Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];

/* Agrupa filas por mes (campo f.mes tipo "2026-03"). Orden descendente (más reciente primero). */
function agruparPorMes(filas){
  const map = new Map();
  filas.forEach(f => {
    const mes = (f.mes||'').trim();
    const clave = mes || 'sin-mes';
    if (!map.has(clave)) map.set(clave, []);
    map.get(clave).push(f);
  });
  const claves = [...map.keys()].sort((a,b)=>{
    if (a === 'sin-mes') return 1;
    if (b === 'sin-mes') return -1;
    return b.localeCompare(a);   // más reciente primero
  });
  return claves.map(clave => ({
    clave,
    etiqueta: etiquetaMes(clave),
    filas: map.get(clave),
  }));
}

/* "2026-03" → "Marzo 2026"; "sin-mes" → "Sin mes asignado" */
function etiquetaMes(clave){
  if (clave === 'sin-mes') return 'Sin mes asignado';
  const m = clave.match(/^(\d{4})-(\d{1,2})/);
  if (m){
    const idx = parseInt(m[2],10) - 1;
    if (idx >= 0 && idx < 12) return `${MESES_NOMBRE[idx]} ${m[1]}`;
  }
  return clave;
}

/* Expandir / contraer un grupo de mes */
window.toggleGrupoMes = (tablaId, clave, filaCab) => {
  const key = `${tablaId}|${clave}`;
  const colapsar = !grupoColapsado[key];
  grupoColapsado[key] = colapsar;
  persistirGrupoColapsado();

  const card = document.getElementById('tcard-'+tablaId) || filaCab.closest('.egr-custom-card, .egr-madre-wrap');
  if (!card) return;
  filaCab.classList.toggle('colapsado', colapsar);
  card.querySelectorAll(`tr[data-group-row="${cssEscapa(clave)}"]`).forEach(tr=>{
    tr.style.display = colapsar ? 'none' : '';
  });
};

/* Escapa comillas para selectores de atributo */
function cssEscapa(s){ return String(s||'').replace(/"/g,'\\"'); }

/* ══════════════════════════════════════════════════
   LIQUIDACIONES POR ENTIDAD — vista modernizada
   · Solo una tabla (entidad) a la vez, con selector de tablas arriba.
   · Panel de facturas a la entidad: año, mes, búsqueda, orden y selección múltiple.
   · Filas agrupadas por factura a la entidad (o por mes) con subtotales.
   · Columnas configurables (preferencia local de cada usuario).
   Los datos y las fórmulas NO cambian: neto = (abono>0 ? abono : valor factura) − descuentos;
   "Valor a pagar" es el mismo campo guardado de siempre (saldo pendiente).
══════════════════════════════════════════════════ */
/* Fecha de HOY en la hora del equipo (Colombia). toISOString() usa hora UTC y después
   de las 7 p. m. devolvía la fecha de mañana. */
function uroHoyLocal(){ const d = new Date(); return new Date(d.getTime() - d.getTimezoneOffset()*60000).toISOString().slice(0,10); }
const UROCOLS = [
  { k:'mes',         l:'Periodo',            def:false },
  { k:'tipoPersona', l:'Tipo',               def:true  },
  { k:'valorFactura',l:'Valor factura',      def:true,  num:true },
  { k:'abono',       l:'Abono',              def:true,  num:true },
  { k:'glosa',       l:'Glosa',              def:true,  num:true },
  { k:'reteFuente',  l:'Rete fuente',        def:false, num:true },
  { k:'afc',         l:'AFC',                def:false, num:true },
  { k:'residentes',  l:'Residentes',         def:false, num:true },
  { k:'tiquetes',    l:'Tiquetes',           def:false, num:true },
  { k:'hotel',       l:'Hotel',              def:false, num:true },
  { k:'transporte',  l:'Transporte',         def:false, num:true },
  { k:'_desc',       l:'Descuentos',         def:true,  num:true },
  { k:'_neto',       l:'Neto liquidado',     def:false, num:true },
  { k:'_pagado',     l:'Pagado',             def:false, num:true },
  { k:'valorPagar',  l:'Valor a pagar',      def:true,  num:true },
  { k:'_estado',     l:'Estado',             def:true  },
];
function uroLiqCalc(f){
  const n = v => Number(v)||0;
  const desc = n(f.glosa)+n(f.reteFuente)+n(f.afc)+n(f.residentes)+n(f.tiquetes)+n(f.hotel)+n(f.transporte);
  const base = n(f.abono) > 0 ? n(f.abono) : n(f.valorFactura);
  const neto = base - desc;
  const pagado = (f.pagos||[]).reduce((s,p)=>s+n(p.monto),0);
  let estado = 'pend', estadoTxt = 'Pendiente';
  if (neto <= 0)               { estado = 'cero';    estadoTxt = 'Sin valor'; }
  else if (pagado - neto >= 1) { estado = 'pagado';  estadoTxt = 'Pagado de más'; }
  else if (pagado >= neto)     { estado = 'pagado';  estadoTxt = 'Pagado'; }
  else if (pagado > 0)         { estado = 'parcial'; estadoTxt = 'Pago parcial'; }
  return { desc, neto, pagado, estado, estadoTxt };
}
const _uroColsKey = () => 'uroLiqCols2_' + (currentUser?.uid || 'anon');
function uroColsVisibles(){
  let pref = null;
  try { pref = JSON.parse(_uroLS.get(_uroColsKey()) || 'null'); } catch(e){ pref = null; }
  return UROCOLS.filter(c => pref && (c.k in pref) ? pref[c.k] : c.def);
}
window.uroToggleCol = (k, on) => {
  let pref = {};
  try { pref = JSON.parse(_uroLS.get(_uroColsKey()) || '{}') || {}; } catch(e){ pref = {}; }
  pref[k] = !!on;
  _uroLS.set(_uroColsKey(), JSON.stringify(pref));
  _uroColsAbierto = true;
  renderCustomTables();
};
window.uroColsDefecto = () => { _uroLS.set(_uroColsKey(), '{}'); _uroColsAbierto = true; renderCustomTables(); };
let _uroColsAbierto = false;
window.uroColsPopover = (ev) => {
  if (ev) ev.stopPropagation();
  _uroColsAbierto = !_uroColsAbierto;
  document.querySelectorAll('.uro-cols-pop').forEach(p => p.hidden = !_uroColsAbierto);
  document.querySelectorAll('.uro-cols-btn').forEach(b => b.setAttribute('aria-expanded', _uroColsAbierto ? 'true':'false'));
};
document.addEventListener('click', (ev) => {
  if (!_uroColsAbierto) return;
  if (ev.target.closest && (ev.target.closest('.uro-cols-pop') || ev.target.closest('.uro-cols-btn'))) return;
  _uroColsAbierto = false;
  document.querySelectorAll('.uro-cols-pop').forEach(p => p.hidden = true);
  document.querySelectorAll('.uro-cols-btn').forEach(b => b.setAttribute('aria-expanded','false'));
});

let _uroTablaActiva = '';   // '' = ver la lista de entidades
window.uroTablaActiva = (id) => { _uroTablaActiva = id; _uroColsAbierto = false; renderCustomTables(); };
window.uroVolverEntidades = () => { _uroTablaActiva = ''; renderCustomTables(); };
let _uroVista = _uroLS.get('uroVistaLiq') === 'madre' ? 'madre' : 'lista';
window.uroVistaLiq = (v) => { _uroVista = v === 'madre' ? 'madre' : 'lista'; _uroLS.set('uroVistaLiq', _uroVista); renderCustomTables(); };

function uroSelIds(t){ return t._selectedIdents?.length ? t._selectedIdents : (t._selectedIdent ? [t._selectedIdent] : []); }
/* Cuántas hijas de una factura a la entidad ya están en una tabla (por relación interna o, en filas viejas, por factura) */
function uroHijasEnTabla(tabla, egreso){
  const filas = (tabla.filas||[]).filter(f => uroFilaEsDe(f, [egreso.id]));   // 27/11 · misma regla que la vista y los giros: solo filas vinculadas
  return (egreso.hijas||[]).filter((h,i) => uroBuscarFila(filas, egreso, h, i)?.tipo === 'ya').length;
}
window.uroToggleMadre = (tablaId, egresoId, marcar) => {
  const t = tablasEgreso.find(x=>x.id===tablaId); if (!t) return;
  const ids = uroSelIds(t).filter(id => id !== egresoId);
  if (marcar) ids.push(egresoId);
  uroAplicarIdents(tablaId, ids);
};
window.uroLimpiarSeleccion = (tablaId) => uroAplicarIdents(tablaId, []);

/* ── Modal: seleccionar facturas a la entidad ── */
let _uroMselTabla = null, _uroMselSet = new Set(), _uroMselQuitadas = 0;
window.uroAbrirMadres = (tablaId) => {
  const t = tablasEgreso.find(x=>x.id===tablaId); if (!t) return;
  _uroMselTabla = tablaId;
  { const chk = uroMadresDeEntidad(t, uroSelIds(t)); _uroMselSet = new Set(chk.ok); _uroMselQuitadas = chk.sinEntidad ? 0 : chk.fuera.length; }
  const anios = [...new Set(egresos.map(e=>String(e.honorarioMes||'').slice(0,4)).filter(a=>/^\d{4}$/.test(a)))].sort().reverse();
  const actual = String(new Date().getFullYear());
  const selA = document.getElementById('umAnio');
  selA.innerHTML = `<option value="">Todos</option>` + anios.map(a=>`<option value="${a}">${a}</option>`).join('');
  selA.value = anios.includes(actual) ? actual : '';
  document.getElementById('umMes').innerHTML = `<option value="">Todos</option>` + MESES_NOMBRE.map((m,i)=>`<option value="${String(i+1).padStart(2,'0')}">${m}</option>`).join('');
  document.getElementById('umBuscar').value = '';
  document.getElementById('umMostrar').value = '';
  document.getElementById('uroMselSub').textContent = t.nombre || '';
  uroMselRender();
  document.getElementById('uroMadresModal').classList.add('open');
  setTimeout(()=>document.getElementById('umBuscar')?.focus(), 50);
};
window.uroCerrarMadres = () => { document.getElementById('uroMadresModal').classList.remove('open'); _uroMselTabla = null; };
window.uroMselToggle = (id, on) => { if (on) _uroMselSet.add(id); else _uroMselSet.delete(id); uroMselCuenta();
  document.querySelector(`#umBody tr[data-id="${id}"]`)?.classList.toggle('sel', on); };
function uroMselCuenta(){
  const n = _uroMselSet.size;
  document.getElementById('umCuenta').textContent = n ? `${n} factura${n!==1?'s':''} a la entidad seleccionada${n!==1?'s':''}` : 'Sin selección: se verán todas las filas de la tabla';
}
window.uroMselRender = () => {
  const t = tablasEgreso.find(x=>x.id===_uroMselTabla); if (!t) return;
  const ent = entDeTabla(t);
  const cab = document.getElementById('umEntidad');
  if (cab) cab.innerHTML = ent
    ? `<i class="fa-solid fa-building-columns"></i> Entidad: <b>${escHtml(ent.razonSocial)}</b>${ent.nit ? ` <span class="uro-muted">· NIT ${escHtml(entNitTexto(ent.nit, ent.dv))}</span>` : ''}<span class="uro-muted"> — solo se muestran sus facturas a la entidad</span>${_uroMselQuitadas ? `<span class="um-aviso"> · se quitaron ${_uroMselQuitadas} de otra entidad de la selección</span>` : ''}`
    : `<div class="um-sinent"><i class="fa-solid fa-circle-exclamation"></i> Esta liquidación aún no tiene entidad. Elige a cuál pertenece para ver sus facturas a la entidad:
        <select id="umEntSel" aria-label="Entidad de la liquidación"><option value="">— Elige —</option>${entActivas().map(x=>`<option value="${x.id}">${escHtml(x.razonSocial)}</option>`).join('')}</select>
        <button type="button" class="uro-btn pri sm" onclick="uroMselFijarEntidad()">Guardar</button></div>`;
  const v = id => document.getElementById(id)?.value || '';
  const anio = v('umAnio'), mes = v('umMes'), q = _ufNorm(v('umBuscar')), mostrar = v('umMostrar'), orden = v('umOrden') || 'nuevo';
  const deEnt = ent ? egresos.filter(e => entDe(e)?.id === ent.id) : [];
  let lista = deEnt.filter(e => {
    const hm = String(e.honorarioMes||'');
    if (anio && hm.slice(0,4) !== anio) return false;
    if (mes && hm.slice(5,7) !== mes) return false;
    if (q && !_ufNorm([e.factura, e.concepto].join(' ')).includes(q)) return false;
    const n = (e.hijas||[]).length, ya = uroHijasEnTabla(t, e);
    if (mostrar === 'usadas' && !ya) return false;
    if (mostrar === 'nuevas' && !(n > ya)) return false;
    return true;
  });
  const k = e => String(e.fechaFacturacion || (e.honorarioMes ? e.honorarioMes+'-00' : ''));
  const cmp = (a,b) => k(a).localeCompare(k(b)) || String(a.factura||'').localeCompare(String(b.factura||''),'es',{numeric:true});
  lista.sort((a,b) => orden === 'viejo' ? cmp(a,b) : cmp(b,a));
  const body = document.getElementById('umBody');
  const vacio = !ent ? 'Elige la entidad de esta liquidación.'
    : !deEnt.length ? `No hay facturas a la entidad registradas para esta entidad. <button type="button" class="uro-btn pri sm" onclick="uroMselCrearMadre()"><i class="fa-solid fa-plus"></i> Crear factura a la entidad</button>`
    : 'Ninguna factura a la entidad de esta entidad coincide. Cambia el año, el mes o la búsqueda.';
  body.innerHTML = lista.length ? lista.map(e => {
    const n = (e.hijas||[]).length, ya = uroHijasEnTabla(t, e), on = _uroMselSet.has(e.id);
    const est = !n ? '<span class="uro-pill gris">Sin liquidaciones</span>'
      : ya >= n ? '<span class="uro-pill ok">Traída</span>'
      : ya ? `<span class="uro-pill warn">${ya} de ${n} traídas</span>` : '<span class="uro-pill gris">Sin traer</span>';
    const re = egmEstadoEgreso(e), pago = `<span class="uro-pill ${{ verde:'ok', ambar:'warn', rojo:'pend' }[re.estadoCls] || 'gris'}">${escHtml(re.estado)}</span>`;
    const fecha = e.fechaFacturacion ? fmtFechaLegible(e.fechaFacturacion) : '—';
    return `<tr data-id="${e.id}" class="${on?'sel':''}" onclick="if(event.target.tagName!=='INPUT'){const c=this.querySelector('input');c.checked=!c.checked;uroMselToggle('${e.id}',c.checked);}">
      <td><input type="checkbox" ${on?'checked':''} aria-label="Seleccionar ${escHtml(e.factura||'')}" onchange="uroMselToggle('${e.id}',this.checked)"/></td>
      <td class="uro-fac">${escHtml(e.factura||'—')}</td>
      <td class="uro-nowrap uro-muted">${escHtml(fecha)}</td>
      <td class="um-concepto" title="${escHtml(e.concepto||'')}">${escHtml(e.concepto||'—')}</td>
      <td class="uro-nowrap">${e.honorarioMes ? escHtml(etiquetaMes(e.honorarioMes)) : '—'}</td>
      <td class="td-num uro-nowrap uro-total">${fmtCOP(e.valorEntidad)}</td>
      <td class="um-estado">${pago} ${est}</td>
      <td class="td-num">${n}</td>
    </tr>`;
  }).join('') : `<tr><td colspan="8" class="uro-vacio-tabla">${vacio}</td></tr>`;
  uroMselCuenta();
};
window.uroMselFijarEntidad = async () => {
  const id = document.getElementById('umEntSel')?.value; if (!id) { toast('Elige la entidad.','error'); return; }
  const t = tablasEgreso.find(x=>x.id===_uroMselTabla); if (!t) return;
  try { await updateDoc(doc(db,'tablasEgreso',t.id), { entidadId: id, updatedAt: serverTimestamp() }); t.entidadId = id;
    const chk = uroMadresDeEntidad(t, [..._uroMselSet]); _uroMselSet = new Set(chk.ok); _uroMselQuitadas = chk.fuera.length;
    toast('Entidad de la liquidación guardada.','success'); uroMselRender(); }
  catch (e) { toast('No se pudo guardar: ' + e.message,'error'); }
};
/* Crear una factura a la entidad de esta entidad sin salir del flujo: al guardarla aparece en la lista */
window.uroMselCrearMadre = () => {
  const t = tablasEgreso.find(x=>x.id===_uroMselTabla); const ent = entDeTabla(t);
  const sel = new Set(_uroMselSet);
  uroCerrarMadres(); _uroVolverAMadres = t?.id || null;
  if (t) t._selectedIdents = [...sel];   // la selección en curso se conserva al volver
  openEgresoModal();
  if (ent) entPonerEntidad(ent);
};
window.uroAplicarMadres = async () => {
  const id = _uroMselTabla; const ids = [..._uroMselSet];
  uroCerrarMadres();
  if (id) await uroAplicarIdents(id, ids);
};

/* ══ Cambiar estado desde la tabla (menú pequeño junto a la píldora) ══ */
function uroMenu(ev, html){
  ev?.stopPropagation?.();
  let m = document.getElementById('uroMenu');
  if (!m) { m = document.createElement('div'); m.id = 'uroMenu'; m.className = 'uro-menu'; m.setAttribute('role','menu'); document.body.appendChild(m);
    document.addEventListener('click', e => { if (!e.target.closest('#uroMenu')) uroMenuCerrar(); });
    document.addEventListener('keydown', e => { if (e.key === 'Escape') uroMenuCerrar(); });
    window.addEventListener('scroll', uroMenuCerrar, true); }
  m.innerHTML = html; m.hidden = false;
  const r = ev.currentTarget.getBoundingClientRect();
  const w = 270; const left = Math.min(Math.max(8, r.left), window.innerWidth - w - 8);
  const top = (r.bottom + 6 + m.offsetHeight > window.innerHeight) ? Math.max(8, r.top - m.offsetHeight - 6) : r.bottom + 6;
  m.style.left = left + 'px'; m.style.top = top + 'px'; m.style.width = w + 'px';
  m.querySelector('button, input')?.focus();
}
window.uroMenuCerrar = () => { const m = document.getElementById('uroMenu'); if (m) m.hidden = true; };
const _uroHoy = () => uroHoyLocal();

/* Factura a la entidad: Pendiente ↔ Pagada (solo cambia la fecha de pago de la factura a la entidad) */
window.uroMenuMadre = (ev, id) => {
  const e = egresos.find(x=>x.id===id); if (!e) return;
  uroMenu(ev, e.fechaPago
    ? `<div class="uro-menu-t">${escHtml(e.factura||'Factura')} · pagada el ${fmtFechaLegible(e.fechaPago)}</div>
       <button type="button" role="menuitem" onclick="uroMadreEstado('${id}','')"><i class="fa-regular fa-clock"></i> Volver a pendiente</button>`
    : `<div class="uro-menu-t">${escHtml(e.factura||'Factura')} · pendiente de pago</div>
       <label class="uro-menu-f">Fecha de pago<input type="date" id="uroMenuFecha" value="${_uroHoy()}"/></label>
       <button type="button" role="menuitem" class="pri" onclick="uroMadreEstado('${id}',document.getElementById('uroMenuFecha').value)"><i class="fa-solid fa-circle-check"></i> Marcar como pagada</button>`);
};
window.uroMadreEstado = async (id, fecha) => {
  const e = egresos.find(x=>x.id===id); if (!e) return;
  if (!fecha && !confirm(`¿Volver ${e.factura||'esta factura'} a pendiente? Se borra su fecha de pago (${fmtFechaLegible(e.fechaPago)}).`)) return;
  uroMenuCerrar();
  try { await updateDoc(doc(db,'egresos',id), { fechaPago: fecha || '' }); toast(fecha ? `${e.factura||'Factura'} marcada como pagada.` : `${e.factura||'Factura'} volvió a pendiente.`, 'success'); }
  catch(err){ toast('No se pudo cambiar el estado: '+err.message,'error'); }
};

/* Fila de liquidación: registrar el pago total del saldo o deshacer el último pago.
   Nunca se marca "Pagado" sin un pago registrado: el estado sale de los pagos. */
function uroFilaPorId(t, rowId, idx){ const fs = t?.filas||[]; return rowId ? fs.findIndex(f=>f.rowId===rowId) : (fs[idx] ? idx : -1); }
window.uroMenuFila = (ev, tablaId, rowId, idx) => {
  const t = tablasEgreso.find(x=>x.id===tablaId); const pos = uroFilaPorId(t, rowId, idx); if (pos < 0) return;
  const f = t.filas[pos]; const c = uroLiqCalc(f); const saldo = Math.max(0, c.neto - c.pagado);
  const ult = (f.pagos||[]).length ? f.pagos[f.pagos.length-1] : null;
  uroMenu(ev, `<div class="uro-menu-t">${escHtml(f.factura||'Fila')} · ${c.estadoTxt}</div>
    ${saldo > 0 ? `<label class="uro-menu-f">Fecha del pago<input type="date" id="uroMenuFecha" value="${_uroHoy()}"/></label>
      <label class="uro-menu-f">Tipo de abono<select id="uroMenuRef">${tipoAbonoOpciones(tipoAbonoSiguiente(f.pagos))}</select></label>
      <button type="button" role="menuitem" class="pri" onclick="uroPagoTotal('${tablaId}','${rowId}',${idx})"><i class="fa-solid fa-circle-check"></i> Registrar pago total · ${fmtCOP(saldo)}</button>
      <button type="button" role="menuitem" onclick="uroMenuCerrar();openTablaRowModal('${tablaId}',${pos});uroEditTab('pagos')"><i class="fa-solid fa-hand-holding-dollar"></i> Registrar un abono…</button>` : ''}
    ${c.pagado > 0 ? `<button type="button" role="menuitem" onclick="uroDevolucionAbrir('${tablaId}','${rowId}',${idx})"><i class="fa-solid fa-rotate-left"></i> Registrar devolución o anulación…</button>` : ''}`);
};
async function uroGuardarPagosFila(tablaId, rowId, idx, cambiar){
  const t = tablasEgreso.find(x=>x.id===tablaId); const pos = uroFilaPorId(t, rowId, idx);
  if (pos < 0) { toast('La fila cambió. Vuelve a intentarlo.','error'); return false; }
  const filas = [...t.filas]; const f = { ...filas[pos], pagos: [...(filas[pos].pagos||[])] };
  cambiar(f);
  const c = uroLiqCalc(f);
  f.valorPagar = Math.max(0, c.neto - c.pagado);   // misma regla que el formulario de edición
  filas[pos] = f;
  await updateDoc(doc(db,'tablasEgreso',tablaId), { filas, updatedAt: serverTimestamp() });
  return true;
}
window.uroPagoTotal = async (tablaId, rowId, idx) => {
  const fecha = document.getElementById('uroMenuFecha')?.value || _uroHoy();
  const ref = (document.getElementById('uroMenuRef')?.value || '').trim();
  uroMenuCerrar();
  try {
    let monto = 0;
    const ok = await uroGuardarPagosFila(tablaId, rowId, idx, f => {
      const c = uroLiqCalc(f); monto = Math.max(0, c.neto - c.pagado);
      f.pagos.push({ monto, fecha, ref, por: currentProfile?.nombreCompleto || currentUser?.email || '' });
    });
    if (ok) toast(`Pago total registrado: ${fmtCOP(monto)}.`, 'success');
  } catch(e){ toast('No se pudo registrar el pago: '+e.message,'error'); }
};
/* 27/11 · E-643 (error 3): una devolución es un movimiento propio, en negativo. No borra el pago original ni toca la liquidación,
   los descuentos, los demás giros ni la orden de pago: solo sube el saldo de este especialista. El candado no la impide. */
window.uroDevolucionAbrir = (tablaId, rowId, idx) => {
  uroMenuCerrar();
  const t = tablasEgreso.find(x=>x.id===tablaId); const pos = uroFilaPorId(t, rowId, idx); if (pos < 0) return;
  const f = t.filas[pos], c = uroLiqCalc(f), ult = [...(f.pagos||[])].reverse().find(p => Number(p.monto) > 0);
  document.getElementById('uaTitulo').textContent = `Devolución · ${f.factura || ''} · ${f.nombre || ''}`;
  document.getElementById('uaBody').innerHTML = `<p>Queda como un movimiento en negativo: <b>el pago original no se borra</b>. Solo sube el saldo de ${escHtml(f.nombre || 'este especialista')}; la liquidación, los descuentos, los demás giros y la orden de pago siguen como están.</p>
    <label class="ua-full">Tipo<select id="devTipo"><option value="devolucion">El especialista devolvió el dinero</option><option value="anulacion">El pago se registró por error</option></select></label>
    <label>Valor<input id="devValor" type="number" min="1" step="1" value="${Math.round(Number(ult?.monto) || 0)}"/></label>
    <label>Fecha<input id="devFecha" type="date" value="${_uroHoy()}"/></label>
    <label class="ua-full">Motivo (obligatorio)<input id="devMotivo" type="text" maxlength="200" placeholder="Ej.: consignado a la cuenta equivocada; se devolvió el 26/11"/></label>
    <label class="ua-full">N° de comprobante (opcional)<input id="devComp" type="text" maxlength="80"/></label>
    <small class="ua-full">Pagado hasta hoy: ${fmtCOP(c.pagado)}.</small><p class="ua-err" id="uaErr"></p>`;
  const ok = document.getElementById('uaOk'); ok.textContent = 'Registrar'; ok.className = 'btn btn-primary'; ok.disabled = false; ok.style.display = '';
  ok.onclick = async () => {
    const v = Math.round(Number(document.getElementById('devValor').value) || 0), motivo = document.getElementById('devMotivo').value.trim(), tipo = document.getElementById('devTipo').value;
    const fecha = document.getElementById('devFecha').value || _uroHoy(), comp = document.getElementById('devComp').value.trim(), err = document.getElementById('uaErr');
    if (!(v > 0)) { err.textContent = 'Escribe el valor.'; return; }
    if (v > c.pagado + 1) { err.textContent = `No puede superar lo pagado (${fmtCOP(c.pagado)}).`; return; }
    if (!motivo) { err.textContent = 'Escribe el motivo.'; return; }
    ok.disabled = true;
    const por = currentProfile?.nombreCompleto || currentUser?.email || '';
    try {
      const listo = await uroGuardarPagosFila(tablaId, rowId, idx, ff => { ff.pagos.push({ monto: -v, fecha, ref: (tipo === 'anulacion' ? 'Anulación: ' : 'Devolución: ') + motivo, tipoMov: tipo, motivo, comprobante: comp, por, porUid: currentUser?.uid || '', creadoISO: new Date().toISOString() }); });
      if (!listo) { ok.disabled = false; return; }
      if (f.identId) segHistorial(f.identId, [{ accion: tipo === 'anulacion' ? 'Anuló un pago' : 'Registró devolución', campo: `${f.factura || 's/n'} · ${f.nombre || ''}`, antes: fmtCOP(c.pagado), despues: fmtCOP(c.pagado - v), motivo: motivo + (comp ? ' · comprobante ' + comp : '') }]).catch(() => {});
      uaCerrar(); toast(`${tipo === 'anulacion' ? 'Anulación' : 'Devolución'} registrada: ${fmtCOP(v)}. El saldo de ${f.nombre || 'el especialista'} sube en ese valor.`, 'success');
    } catch (x) { err.textContent = 'No se pudo registrar: ' + x.message; ok.disabled = false; }
  };
  document.getElementById('uaModal').classList.add('open'); setTimeout(() => document.getElementById('devMotivo')?.focus(), 30);
};
/* Compatibilidad: «Deshacer último pago» ahora registra una anulación (no borra el pago) */
window.uroDeshacerPago = async (tablaId, rowId, idx) => { uroDevolucionAbrir(tablaId, rowId, idx); };
window.uroDeshacerPagoAntiguo = async (tablaId, rowId, idx) => {
  const t = tablasEgreso.find(x=>x.id===tablaId); const pos = uroFilaPorId(t, rowId, idx); if (pos < 0) return;
  const ult = (t.filas[pos].pagos||[]).slice(-1)[0]; if (!ult) return;
  if (!confirm(`¿Deshacer el pago de ${fmtCOP(ult.monto)} del ${fmtFechaLegible(ult.fecha)}?`)) return;
  uroMenuCerrar();
  try { if (await uroGuardarPagosFila(tablaId, rowId, idx, f => { f.pagos.pop(); })) toast('Último pago deshecho.','success'); }
  catch(e){ toast('No se pudo deshacer: '+e.message,'error'); }
};
window.uroAvisoBloqueo = (tablaId, identId) => {
  const e = egresos.find(x=>x.id===identId);
  toast(`Primero trae la factura a la entidad ${e?.factura||''} para editar sus liquidaciones.`, 'error');
  uroAbrirMadres(tablaId);
};

function renderCustomTables() {
  uroContadoresTabs();
  renderUroResumen();
  const box = document.getElementById('egresoCustomTables');
  if (!box) return;
  if (!tablasEgreso.length) {
    box.innerHTML = `<div class="uro-vacio-grande">
      <h2>Aún no hay tablas de liquidación</h2>
      <p>Crea una tabla por cada entidad (por ejemplo, Clínica Panamericana). Luego eliges sus facturas a la entidad y las liquidaciones llegan solas.</p>
      <button class="uro-btn pri" type="button" onclick="openTablaModal()"><i class="fa-solid fa-plus"></i> Nueva tabla</button>
    </div>`;
    return;
  }
  const t = tablasEgreso.find(x=>x.id===_uroTablaActiva);
  // ── Sin entidad elegida: tarjetas de entidades ──
  if (!t) {
    const tablasOrden = [...tablasEgreso].sort((a,b)=>String(a.nombre||'').localeCompare(String(b.nombre||''),'es'));
    box.innerHTML = `<div class="uro-res-top"><h2 class="uro-sec-t">Elige una entidad</h2>
        <button class="uro-btn sec sm" type="button" onclick="openTablaModal()"><i class="fa-solid fa-plus"></i> Nueva tabla</button></div>
      <div class="uro-ecs">${tablasOrden.map(x => {
        const fs = x.filas||[];
        const pp = fs.reduce((s,f)=>s+(Number(f.valorPagar)||0),0);
        const nM = new Set(fs.map(f=>f.identId).filter(Boolean)).size;
        return `<button type="button" class="uro-ec" onclick="uroTablaActiva('${x.id}')">
          <span class="uro-ec-h">${(x.logoDer||x.logoIzq) ? `<img src="${x.logoDer||x.logoIzq}" alt=""/>` : `<span class="uro-ec-ini" aria-hidden="true">${escHtml((x.nombre||'?').replace(/^tabla\s+/i,'').slice(0,2).toUpperCase())}</span>`}
            <span class="uro-ec-n">${escHtml(x.nombre||'Sin nombre')}</span></span>
          <span class="uro-ec-r"><span>Filas</span><b>${fs.length}</b></span>
          <span class="uro-ec-r"><span>Valor a pagar</span><b class="acc">${fmtCOP(pp)}</b></span>
          <span class="uro-ec-f"><span>${nM} factura${nM!==1?'s':''} a la entidad vinculada${nM!==1?'s':''}</span><span class="uro-ec-go" aria-hidden="true"><i class="fa-solid fa-arrow-right"></i></span></span>
        </button>`; }).join('')}</div>`;
    return;
  }

  const allFilas = t.filas||[];
  const selIds = uroSelIds(t);
  const filas = selIds.length ? allFilas.filter(f=> uroFilaEsDe(f, selIds)) : allFilas;
  const cols = uroColsVisibles();
  const nCols = 2 + cols.length + 1;
  const madresSel = selIds.map(id => egresos.find(e=>e.id===id)).filter(Boolean);

  // Una fila de una factura a la entidad que NO está traída (seleccionada) queda bloqueada:
  // primero se trae la factura a la entidad y luego se editan sus liquidaciones. Las filas sin madre existente siguen editables.
  const estaBloqueada = (f) => !!(f.identId && egresos.some(e=>e.id===f.identId) && !selIds.includes(f.identId));
  let bloq = false;
  const celda = (f, c, calc) => {
    switch (c.k) {
      case 'mes':         return `<td class="uro-nowrap">${f.mes ? escHtml(etiquetaMes(f.mes)) : '—'}</td>`;
      case 'tipoPersona': return `<td class="uro-muted">${escHtml(f.tipoPersona||'—')}</td>`;
      case '_desc':       return `<td class="td-money">${fmtCOP(calc.desc)}</td>`;
      case '_neto':       return `<td class="td-money uro-neto ${calc.neto<0?'neg':''}">${fmtCOP(calc.neto)}</td>`;
      case '_pagado':     return `<td class="td-money">${fmtCOP(calc.pagado)}</td>`;
      case 'valorPagar':  { const cc = uroLiqCalc(f), sv = Math.round(cc.neto - cc.pagado);
        return sv <= -1 ? `<td class="td-money uro-pagar neg" title="Pagado de más: a favor de Uroexpertos">${fmtCOP(sv)}</td>` : `<td class="td-money uro-pagar ${Number(f.valorPagar)<0?'neg':''}">${fmtCOP(f.valorPagar)}</td>`; }
      case '_estado': {
        const cls = calc.estado==='pagado'?'ok':calc.estado==='parcial'?'warn':calc.estado==='cero'?'gris':'pend';
        return bloq || calc.estado==='cero'
          ? `<td><span class="uro-pill ${cls}">${calc.estadoTxt}</span></td>`
          : `<td><button type="button" class="uro-pill ${cls} uro-pill-btn" title="Cambiar estado de pago" onclick="uroMenuFila(event,'${t.id}','${escHtml(f.rowId||'')}',${allFilas.indexOf(f)})">${calc.estadoTxt} <i class="fa-solid fa-chevron-down" aria-hidden="true"></i></button></td>`;
      }
      default:            return `<td class="td-money">${fmtCOP(f[c.k])}</td>`;
    }
  };
  const valorCol = (f, c, calc) => c.k==='_desc' ? calc.desc : c.k==='_neto' ? calc.neto : c.k==='_pagado' ? calc.pagado : (Number(f[c.k])||0);
  const sumaFila = (lista) => cols.map(c => c.num ? lista.reduce((s,f)=>s+valorCol(f,c,uroLiqCalc(f)),0) : null);

  const filaHtml = (f, clave) => {
    const realIdx = allFilas.indexOf(f);
    const calc = uroLiqCalc(f);
    bloq = estaBloqueada(f);
    const madreF = bloq ? (egresos.find(e=>e.id===f.identId)?.factura || '') : '';
    const blob = normBusq([f.factura, f.nombre, f.tipoPersona, f.mes].join(' '));
    const envios = f.envios||[];
    const ultimo = envios.length ? envios[envios.length-1] : null;
    const enviado = !!(ultimo || f.correoEnviado);
    const tituloCorreo = ultimo ? `Último correo: ${ultimo.tipoTxt||''} · ${new Date(ultimo.fecha).toLocaleDateString('es-CO')}. Enviar otro`
                       : f.correoEnviado ? 'Correo enviado. Enviar otro' : 'Enviar por correo';
    return `<tr data-search="${escHtml(blob)}" data-pagar="${Number(f.valorPagar)||0}" ${clave?`data-group-row="${escHtml(clave)}"`:''} class="${bloq?'uro-bloq':''}">
      <td class="uro-fac">${escHtml(f.factura||'—')}</td>
      <td class="uro-esp">${escHtml(f.nombre||'—')}</td>
      ${cols.map(c => celda(f,c,calc)).join('')}
      <td>
        ${bloq ? `<div class="tbl-actions"><button class="uro-ico uro-lock" type="button" title="Trae primero la factura a la entidad ${escHtml(madreF)} para editar esta liquidación" aria-label="Bloqueada: trae primero la factura a la entidad ${escHtml(madreF)}" onclick="uroAvisoBloqueo('${t.id}','${escHtml(f.identId)}')"><i class="fa-solid fa-lock"></i></button></div>` : `<div class="tbl-actions">
          <button class="uro-ico tinted" type="button" title="Editar" aria-label="Editar ${escHtml(f.factura||'')}" onclick="openTablaRowModal('${t.id}',${realIdx})"><i class="fa-solid fa-pen"></i></button>
          <button class="uro-ico tinted ${enviado?'enviado':''}" type="button" title="${escHtml(tituloCorreo)}" aria-label="${escHtml(tituloCorreo)}" onclick="openEnviarModal('${t.id}',${realIdx})"><i class="fa-solid ${enviado?'fa-envelope-circle-check':'fa-paper-plane'}"></i></button>
          <button class="uro-ico del" type="button" title="Eliminar fila" aria-label="Eliminar ${escHtml(f.factura||'')}" onclick="deleteTablaRow('${t.id}',${realIdx},'${escHtml(f.rowId||'')}')"><i class="fa-solid fa-trash"></i></button>
        </div>`}
      </td>
    </tr>`;
  };

  let cuerpo = '';
  const ordenMadre = (f) => { const e = egresos.find(x=>x.id===f.identId); return e ? String(e.honorarioMes||'')+'|'+String(e.factura||'') : ''; };
  if (_uroVista === 'madre') {
    const map = new Map();
    filas.forEach(f => {
      const eg = egresos.find(e => e.id === f.identId);
      const clave = eg ? 'm:'+eg.id : 'm:sin';
      if (!map.has(clave)) map.set(clave, { eg, filas:[] });
      map.get(clave).filas.push(f);
    });
    const grupos = [...map.entries()].map(([clave, g]) => ({
      clave, eg:g.eg, filas:g.filas,
      titulo: g.eg ? (g.eg.factura || 'Factura a la entidad sin número') : 'Filas sin factura a la entidad vinculada',
      meta: g.eg ? [g.eg.honorarioMes ? etiquetaMes(g.eg.honorarioMes) : '', g.eg.concepto||''].filter(Boolean).join(' · ') : 'Filas manuales o de una factura a la entidad eliminada',
      orden: g.eg ? String(g.eg.honorarioMes||'')+'|'+String(g.eg.factura||'') : '',
    })).sort((a,b) => a.orden === '' ? 1 : b.orden === '' ? -1 : b.orden.localeCompare(a.orden,'es',{numeric:true}));
    cuerpo = grupos.map(g => {
      const colapsado = grupoColapsado[`${t.id}|${g.clave}`] ? 'colapsado' : '';
      const sub = sumaFila(g.filas);
      return `<tr class="tbl-group-row uro-grp ${colapsado}" data-group="${escHtml(g.clave)}" onclick="toggleGrupoMes('${t.id}','${escHtml(g.clave)}',this)">
          <td colspan="${nCols}" class="tbl-group-cell"><span class="uro-grp-in">
            <i class="fa-solid fa-chevron-down tbl-group-chevron" aria-hidden="true"></i>
            <span class="tbl-group-label">${escHtml(g.titulo)}</span>
            <span class="uro-grp-meta">${escHtml(g.meta)}</span>
            <span class="tbl-group-count">${g.filas.length} fila${g.filas.length!==1?'s':''}</span>
          </span></td></tr>`
        + g.filas.map(f => filaHtml(f, g.clave)).join('')
        + (g.filas.length > 1 ? `<tr class="tbl-subtotal" data-group-row="${escHtml(g.clave)}"><td colspan="2">Subtotal ${escHtml(g.titulo)}</td>${sub.map((v,i)=>v===null?'<td></td>':`<td class="td-money">${fmtCOP(v)}</td>`).join('')}<td></td></tr>` : '');
    }).join('');
  } else {
    // Lista plana: ordenada por factura a la entidad (más reciente primero) y luego por número de factura
    cuerpo = [...filas].sort((a,b) => ordenMadre(b).localeCompare(ordenMadre(a),'es',{numeric:true})
        || String(a.factura||'').localeCompare(String(b.factura||''),'es',{numeric:true}))
      .map(f => filaHtml(f, '')).join('');
  }

  const totales = sumaFila(filas);
  const pie = filas.length ? `<tfoot><tr>
      <td colspan="2" class="uro-tot-l">Totales · ${filas.length} fila${filas.length!==1?'s':''}</td>
      ${totales.map((v,i) => v === null ? '<td></td>'
        : `<td class="td-money ${cols[i].k==='valorPagar'?'tbl-total-val uro-pagar':''} ${cols[i].k==='_neto'?'uro-neto':''}">${fmtCOP(v)}</td>`).join('')}
      <td></td></tr></tfoot>` : '';
  const vacioTabla = allFilas.length
    ? `<tr><td colspan="${nCols}" class="uro-vacio-tabla"><strong>Las facturas a la entidad elegidas no tienen filas en esta tabla.</strong> <button type="button" class="uro-link" onclick="uroLimpiarSeleccion('${t.id}')">Ver todas las filas</button></td></tr>`
    : `<tr><td colspan="${nCols}" class="uro-vacio-tabla"><strong>Esta tabla aún no tiene filas.</strong><br/>Usa «Elegir facturas a la entidad»: sus liquidaciones de especialistas llegan aquí solas. También puedes agregar una fila manual.</td></tr>`;

  // KPIs de la liquidación visible
  const valEnt = madresSel.length ? madresSel.reduce((s,e)=>s+(Number(e.valorEntidad)||0),0)
               : [...new Set(filas.map(f=>f.identId))].reduce((s,id)=>s+(Number(egresos.find(e=>e.id===id)?.valorEntidad)||0),0);
  const valFac = filas.reduce((s,f)=>s+(Number(f.valorFactura)||0),0);
  const valPag = filas.reduce((s,f)=>s+(Number(f.valorPagar)||0),0);
  const madreTxt = madresSel.length
    ? `<div class="uro-ms-l">Factura${madresSel.length!==1?'s':''} a la entidad seleccionada${madresSel.length!==1?'s':''}</div>
       <div class="uro-ms-n">${madresSel.slice(0,3).map(e=>escHtml(e.factura||'—')).join(', ')}${madresSel.length>3?` <span>+${madresSel.length-3}</span>`:''}</div>
       <div class="uro-ms-c">${escHtml(madresSel.length===1 ? (madresSel[0].concepto||'') : `${madresSel.length} facturas · ${[...new Set(madresSel.map(e=>e.honorarioMes?etiquetaMes(e.honorarioMes):''))].filter(Boolean).join(', ')}`)}</div>`
    : `<div class="uro-ms-l">Facturas a la entidad</div><div class="uro-ms-n uro-ms-todas">Todas las filas</div><div class="uro-ms-c">Elige facturas a la entidad para ver solo su liquidación.</div>`;

  box.innerHTML = `<div class="uro-ent-detail egr-custom-card" id="tcard-${t.id}">
    <div class="uro-ed-head">
      <button class="uro-ico bordered" type="button" onclick="uroVolverEntidades()" title="Volver a entidades" aria-label="Volver a entidades"><i class="fa-solid fa-arrow-left"></i></button>
      ${(t.logoDer||t.logoIzq)?`<img src="${t.logoDer||t.logoIzq}" class="uro-ed-logo" alt=""/>`:''}
      <h2 class="uro-ed-t">${escHtml(t.nombre)}</h2>
      <label class="uro-ed-sw"><span class="uro-sr">Cambiar de entidad</span>
        <select onchange="uroTablaActiva(this.value)">${[...tablasEgreso].sort((a,b)=>String(a.nombre||'').localeCompare(String(b.nombre||''),'es')).map(x=>`<option value="${x.id}" ${x.id===t.id?'selected':''}>${escHtml(x.nombre||'Sin nombre')}</option>`).join('')}</select></label>
      <div class="uro-ed-checks">
        <label class="ech-check"><input type="checkbox" ${t._chkContabilidad?'checked':''} onchange="toggleTablaCheck('${t.id}','contabilidad',event.target.checked)"/><span>Revisado por Contabilidad</span></label>
        <label class="ech-check"><input type="checkbox" ${t._chkFacturacion?'checked':''} onchange="toggleTablaCheck('${t.id}','facturacion',event.target.checked)"/><span>Revisado por Facturación</span></label>
      </div>
      <button class="uro-ico bordered" type="button" onclick="editTabla('${t.id}')" title="Editar nombre y logos" aria-label="Editar tabla"><i class="fa-solid fa-gear"></i></button>
      <button class="uro-ico bordered del" type="button" onclick="deleteTabla('${t.id}')" title="Eliminar tabla" aria-label="Eliminar tabla"><i class="fa-solid fa-trash"></i></button>
    </div>

    <div class="uro-ms">
      <div class="uro-ms-a">${madreTxt}</div>
      <div class="uro-ms-k"><span>Valor entidad</span><b>${fmtCOP(valEnt)}</b></div>
      <div class="uro-ms-k"><span>Valor liquidaciones de especialistas</span><b>${fmtCOP(valFac)}</b></div>
      <div class="uro-ms-k"><span>Valor a pagar</span><b class="acc">${fmtCOP(valPag)}</b></div>
      <div class="uro-ms-k"><span>Filas</span><b>${filas.length}${selIds.length?` <small>de ${allFilas.length}</small>`:''}</b></div>
    </div>
    ${madresSel.map(e => { const s = uroSueltasDe({ id: e.id, honorarioMes: e.honorarioMes, ent: entDe(e) }).filter(x => x.t.id === t.id);
      return s.length ? `<div class="uro-sueltas"><i class="fa-solid fa-link-slash"></i><div><b>${s.length} fila(s) de ${escHtml(e.honorarioMes ? mesFilaLabel(e.honorarioMes) : 'este mes')} no están vinculadas a ${escHtml(e.factura || 'la factura')}</b><small>No se ven aquí, no reciben giros y no tienen candado: ${escHtml(s.slice(0, 6).map(x => (x.f.factura || 's/n') + ' · ' + (x.f.nombre || '')).join(', '))}${s.length > 6 ? '…' : ''}</small></div><button type="button" class="uro-btn sm" onclick="uroVincularAbrir('${e.id}')"><i class="fa-solid fa-link"></i> Vincular</button></div>` : ''; }).join('')}

    <div class="uro-liq-tools">
      <button class="uro-btn pri sm" type="button" onclick="openTablaRowModal('${t.id}',null)"><i class="fa-solid fa-plus"></i> Fila manual</button>
      <button class="uro-btn outline-v sm" type="button" onclick="exportarTablaExcel('${t.id}')"><i class="fa-solid fa-file-excel"></i> Exportar Excel</button>
      <div class="uro-tools-r">
        <div class="ech-search">
          <i class="fa-solid fa-magnifying-glass ech-search-ico" aria-hidden="true"></i>
          <input type="text" class="ech-search-input" id="busq-${t.id}" placeholder="Buscar especialista o factura…"
            aria-label="Buscar en la liquidación" value="${escHtml(busquedaTablas[t.id]||'')}" oninput="filtrarTablaBusqueda('${t.id}', this.value)"/>
          <button class="ech-search-x" type="button" aria-label="Limpiar búsqueda" onclick="limpiarBusquedaTabla('${t.id}')">&times;</button>
          <span class="ech-search-count"></span>
        </div>
        <div class="uro-seg" role="group" aria-label="Vista">
          <button type="button" class="${_uroVista==='lista'?'on':''}" onclick="uroVistaLiq('lista')">Lista</button>
          <button type="button" class="${_uroVista==='madre'?'on':''}" onclick="uroVistaLiq('madre')">Por factura a la entidad</button>
        </div>
        <div class="uro-cols-wrap">
          <button type="button" class="uro-btn sec sm uro-cols-btn" aria-expanded="${_uroColsAbierto}" onclick="uroColsPopover(event)"><i class="fa-solid fa-table-columns"></i> Columnas</button>
          <div class="uro-cols-pop" ${_uroColsAbierto?'':'hidden'} role="dialog" aria-label="Elegir columnas">
            <div class="uro-cols-t">Columnas visibles</div>
            ${UROCOLS.map(c => `<label><input type="checkbox" ${cols.includes(c)?'checked':''} onchange="uroToggleCol('${c.k}',this.checked)"/> ${c.l}</label>`).join('')}
            <div class="uro-cols-f">Factura, especialista y acciones siempre se ven. <button type="button" class="uro-link" onclick="uroColsDefecto()">Restablecer</button></div>
          </div>
        </div>
      </div>
    </div>
    ${(() => {
      // Aviso si la tabla YA trae filas repetidas (misma factura y especialista) de antes
      const vistos = new Map(); let rep = 0;
      allFilas.forEach(f => { const k = _nrm(f.factura); if (!k) return; const kk = k+'|'+_nrm(f.nombre); vistos.set(kk,(vistos.get(kk)||0)+1); });
      vistos.forEach(n => { if (n > 1) rep += n-1; });
      return rep ? `<div class="uro-bloq-aviso uro-dup-aviso"><i class="fa-solid fa-triangle-exclamation" aria-hidden="true"></i>
        <span>Esta tabla tiene ${rep} fila${rep!==1?'s':''} repetida${rep!==1?'s':''} (misma factura y especialista), de antes de este cambio. Revísalas y elimina la que sobre: no se borran solas.</span></div>` : '';
    })()}
    <div class="uro-bloq-aviso">
      <i class="fa-solid ${filas.some(estaBloqueada) ? 'fa-lock' : 'fa-layer-group'}" aria-hidden="true"></i>
      <span>${filas.some(estaBloqueada)
        ? 'Las filas con candado son liquidaciones de facturas a la entidad que no has traído. Para editarlas, primero elige su factura a la entidad.'
        : selIds.length
          ? `Trabajando con ${selIds.length} factura${selIds.length!==1?'s':''} a la entidad: <strong>${madresSel.map(e=>escHtml(e.factura||'—')).join(', ')}</strong>.`
          : 'Elige las facturas a la entidad de esta liquidación: sus liquidaciones llegan solas y quedan listas para editar.'}</span>
      ${selIds.length ? `<button type="button" class="uro-link" onclick="uroLimpiarSeleccion('${t.id}')">Ver todas las filas</button>` : ''}
      <button type="button" class="uro-btn outline sm" onclick="uroAbrirMadres('${t.id}')"><i class="fa-solid fa-list-check"></i> ${selIds.length ? 'Cambiar facturas a la entidad' : 'Elegir facturas a la entidad'}</button>
    </div>
    <div class="egr-custom-table-wrap uro-liq-wrap">
      <table class="egr-custom-table uro-liq-table" style="min-width:${250 + cols.length*96}px">
        <thead><tr>
          <th>Factura</th><th>Especialista</th>
          ${cols.map(c => `<th class="${c.num?'th-money':''} ${c.k==='valorPagar'?'uro-pagar':''}">${c.l}</th>`).join('')}
          <th class="th-money">Acciones</th>
        </tr></thead>
        <tbody>${cuerpo || vacioTabla}
          <tr class="tbl-no-results" style="display:none"><td colspan="${nCols}" class="uro-vacio-tabla">Sin resultados para la búsqueda.</td></tr>
        </tbody>
        ${pie}
      </table>
    </div>
    <p class="uro-nota">Valor a pagar = (abono si es mayor que 0, si no valor factura) − descuentos − pagos registrados. «Pagado» solo aparece cuando los pagos registrados cubren el neto.</p>
  </div>`;

  const card = document.getElementById('tcard-'+t.id);
  if (card) {
    card.querySelectorAll('.tbl-group-row').forEach(gr => {
      const clave = gr.getAttribute('data-group');
      if (grupoColapsado[`${t.id}|${clave}`]) {
        gr.classList.add('colapsado');
        card.querySelectorAll(`tr[data-group-row="${cssEscapa(clave)}"]`).forEach(tr => tr.style.display = 'none');
      }
    });
    if (busquedaTablas[t.id]) filtrarTablaBusqueda(t.id, busquedaTablas[t.id]);
  }
}

window.openTablaRowModal = (tablaId, idx) => {
  {
    const tb = tablasEgreso.find(t=>t.id===tablaId);
    const fx = (idx !== null && idx !== undefined) ? tb?.filas?.[idx] : null;
    if (fx && fx.identId && egresos.some(e=>e.id===fx.identId) && !uroSelIds(tb).includes(fx.identId)) { uroAvisoBloqueo(tablaId, fx.identId); return; }
  }
  editTablaRowTablaId = tablaId;
  editTablaRowIdx     = idx;
  const tabla = tablasEgreso.find(t=>t.id===tablaId);
  // Validate: need identificador to add new row
  if(idx===null && !(tabla?._selectedIdents?.length || tabla?._selectedIdent)) {
    toast('Debes seleccionar un Identificador antes de agregar filas.','error');
    return;
  }
  const f = (idx !== null && idx !== undefined) ? tabla?.filas?.[idx] : null;
  _filaOriginal = f ? JSON.parse(JSON.stringify(f)) : null;   // copia para conservar campos y relación
  document.getElementById('tablaRowTitle').textContent = f ? `Editar liquidación · Factura ${f.factura||'sin número'}` : 'Nueva fila manual';
  document.getElementById('tablaRowTablaId').value = tablaId;
  document.getElementById('tablaRowId').value = idx??'';
  document.getElementById('trFactura').value     = f?.factura||'';
  document.getElementById('trMes').value         = f?.mes||'';

  // Poblar select de especialistas desde CLIENTES y restaurar selección
  const selNombre = document.getElementById('trNombre');
  const especialistas = [...new Set(doctors.filter(d=>d.especialista).map(d=>d.especialista))].sort((a,b)=>a.localeCompare(b,'es',{sensitivity:'base'}));
  const savedNombre = f?.nombre||'';
  // Build options with 'selected' attribute directly on the matching option
  selNombre.innerHTML = '<option value="">— Seleccionar especialista —</option>'
    + especialistas.map(e=>`<option value="${escHtml(e)}" ${e===savedNombre?'selected':''}>${escHtml(e)}</option>`).join('')
    + (savedNombre && !especialistas.includes(savedNombre)
        ? `<option value="${escHtml(savedNombre)}" selected>${escHtml(savedNombre)}</option>` : '');
  // Force value after DOM update
  selNombre.value = savedNombre;

  const selTipoP = document.getElementById('trTipoPersona');
  if (selTipoP) selTipoP.value = f?.tipoPersona||'';

  document.getElementById('trValorFactura').value= f?.valorFactura||'';
  _abonoLegado = (Number(f?.abono)||0) > 0;   // filas con abono digitado: regla anterior, se puede seguir editando
  { const ab = document.getElementById('trAbono'), pag = (f?.pagos||[]).reduce((t,p)=>t+(Number(p.monto)||0),0);
    ab.value = _abonoLegado ? f.abono : (pag || ''); ab.readOnly = !_abonoLegado; ab.classList.toggle('tr-rete-auto', !_abonoLegado);
    ab.title = _abonoLegado ? 'Abono digitado antes: reemplaza al valor factura como base (regla anterior)' : 'Suma de los giros y pagos recibidos (solo lectura)';
    const lb = document.querySelector('label[for="trAbono"]'); if (lb) lb.textContent = _abonoLegado ? 'Abono (base anterior)' : 'Abono (giros recibidos)'; }
  document.getElementById('trGlosa').value       = f?.glosa||'';
  document.getElementById('trReteFuente').value  = f?.reteFuente||'';
  document.getElementById('trReteModo').value    = f?.reteFuenteModo === 'pct' ? 'pct' : 'valor';
  document.getElementById('trRetePct').value     = f?.reteFuenteModo === 'pct' ? (f.reteFuentePct ?? '') : '';
  { const pct = f?.reteFuenteModo === 'pct', pIn = document.getElementById('trRetePct'), vIn = document.getElementById('trReteFuente');
    pIn.hidden = !pct; vIn.hidden = pct; vIn.readOnly = pct; vIn.classList.toggle('tr-rete-auto', pct); vIn.tabIndex = pct ? -1 : 0; }
  document.getElementById('trAfc').value         = f?.afc||'';
  document.getElementById('trResidentes').value  = f?.residentes||'';
  document.getElementById('trTiquetes').value    = f?.tiquetes||'';
  document.getElementById('trHotel').value       = f?.hotel||'';
  document.getElementById('trTransporte').value  = f?.transporte||'';
  // Cargar historial de pagos de la fila (o vacío para fila nueva)
  _pagosTmp = f?.pagos ? JSON.parse(JSON.stringify(f.pagos)) : [];
  renderPagos();
  calcValorPagar();
  document.getElementById('egresoAutoInfo').style.display='none';
  // Subtítulo: tabla y factura a la entidad vinculada
  const subEl = document.getElementById('trSub');
  if (subEl) {
    const madreId = f ? f.identId : (uroSelIds(tabla||{})[0]||'');
    const madre = egresos.find(e=>e.id===madreId);
    subEl.textContent = [tabla?.nombre||'', madre ? `Factura a la entidad ${madre.factura||''}` : (f ? 'Sin factura a la entidad vinculada' : '')].filter(Boolean).join(' · ');
  }
  // Pestañas del formulario: siempre abre en "Datos generales"
  uroEditTab('datos');
  const envios = f?.envios || [];
  const nC = document.getElementById('trCorreosN'); if (nC) nC.textContent = envios.length || (f?.correoEnviado ? 1 : '');
  const cBox = document.getElementById('trCorreos');
  if (cBox) cBox.innerHTML = envios.length
    ? [...envios].reverse().map(e => `<div class="uro-env-reg"><span>${new Date(e.fecha).toLocaleString('es-CO',{dateStyle:'short',timeStyle:'short'})}</span><strong>${escHtml(e.tipoTxt||e.tipo||'')}${e.reenvio?' (reenvío)':''}</strong><span>${escHtml(e.para||'')}</span><span>${escHtml(e.por||'')}</span></div>`).join('')
    : f?.correoEnviado ? `<p class="uro-env-vacio">Se envió un correo el ${f.correoFecha ? new Date(f.correoFecha).toLocaleDateString('es-CO') : '(fecha no registrada)'}, antes de que existiera el registro detallado.</p>`
    : `<p class="uro-env-vacio">Aún no se ha enviado ningún correo de esta fila. Se envía desde el botón del avión en la tabla.</p>`;
  document.getElementById('tablaRowModal').classList.add('open');
  trRegimenSugerir();   // régimen tributario del especialista y su % de retención
};
window.uroEditTab = (p) => {
  document.querySelectorAll('#tablaRowModal .uro-etab').forEach(b => { const on = b.dataset.p === p; b.classList.toggle('on', on); b.setAttribute('aria-selected', on?'true':'false'); });
  document.querySelectorAll('#tablaRowModal .uro-epanel').forEach(x => x.hidden = x.dataset.p !== p);
};

window.closeTablaRowModal = () => {
  document.getElementById('tablaRowModal').classList.remove('open');
  editTablaRowTablaId = null; editTablaRowIdx = null; _filaOriginal = null;
};
let _filaOriginal = null;   // fila tal como estaba al abrir el panel (null = fila nueva)

/* Autocompletar desde EGRESO cuando se escribe la factura */
window.autocompletarDesdeEgreso = () => {
  const factura = document.getElementById('trFactura').value.trim().toLowerCase();
  if (!factura) return;

  const infoEl = document.getElementById('egresoAutoInfo');
  const msgEl  = document.getElementById('egresoAutoMsg');

  // 1. Buscar PRIMERO en liquidaciones de especialistas — son los registros reales
  let foundHija = null;
  for (const e of egresos) {
    const hija = (e.hijas||[]).find(h => (h.factura||'').toLowerCase() === factura);
    if (hija) { foundHija = hija; break; }
  }

  // 2. Si no es hija, buscar en las facturas a la entidad
  const foundMadre = foundHija ? null : (egresos.find(e => (e.factura||'').toLowerCase() === factura) || null);

  if (foundHija) {
    document.getElementById('trMes').value          = foundHija.honorarioMes || '';
    // Set select value for nombre
    const sel = document.getElementById('trNombre');
    if (sel) sel.value = foundHija.nombre || '';
    document.getElementById('trValorFactura').value = foundHija.valorEspecialista || 0;
    calcValorPagar();
    infoEl.style.display = 'flex';
    msgEl.textContent = `✓ Liquidación del especialista encontrada: ${foundHija.factura} · ${foundHija.nombre}`;
    return;
  }

  if (foundMadre) {
    document.getElementById('trMes').value          = foundMadre.honorarioMes      || '';
    const sel = document.getElementById('trNombre');
    if (sel) sel.value = foundMadre.nombre || '';
    document.getElementById('trValorFactura').value = foundMadre.valorEspecialista || 0;
    calcValorPagar();
    infoEl.style.display = 'flex';
    msgEl.textContent = `✓ Factura a la entidad encontrada: ${foundMadre.factura} · ${foundMadre.nombre}`;
    return;
  }

  infoEl.style.display = 'none';
};

/* Calcular VALOR A PAGAR */
/* ── Régimen tributario del especialista → % de retención (tabla que define la contadora; régimen simple = 0 %) ──
   La retención se aplica UNA vez, en la fila de liquidación (el giro sale sobre el saldo, que ya es neto). */
const REGIMENES = [
  { k:'simple', t:'Simple', fijo:0 },
  { k:'ordinario', t:'Ordinario' },
];
const regNormal = k => !k ? '' : (k === 'simple' ? 'simple' : (/^ordinario|persona_juridica/.test(k) ? 'ordinario' : ''));
let regTarifas = {}, _regCargado = false;
function regSuscribir(){
  if (_regCargado) return; _regCargado = true;
  onSnapshot(doc(db,'uiPrefs','regimenRetencion'), sn => { regTarifas = sn.exists() ? (sn.data()?.tarifas || {}) : {}; if (document.getElementById('regModal')?.classList.contains('open')) regPintar(); trRegimenSugerir(); },
    e => console.warn('Tarifas de retención no disponibles:', e));
}
const regTarifa = k => { k = regNormal(k); const r = REGIMENES.find(x => x.k === k); if (!r) return null; return r.fijo != null ? r.fijo : (Number(regTarifas[k] ?? regTarifas.ordinario_declarante) || 0); };
const regNombre = k => REGIMENES.find(x => x.k === regNormal(k))?.t || '';
function regOpciones(sel){ return `<option value="">— Sin definir —</option>` + REGIMENES.map(r => `<option value="${r.k}" ${r.k === sel ? 'selected' : ''}>${escHtml(r.t)}</option>`).join(''); }
function regDeEspecialista(nombre, razonId){   // régimen de la razón social a la que se paga (o la predeterminada)
  const d = cliDoctorDeEspecialista(nombre); if (!d) return '';
  const rs = cliRazones(d), r = (razonId && rs.find(x => x.id === razonId)) || cliRazonPred(d);
  return regNormal(r?.regimen || d.regimenTrib || '');
}
window.regAbrir = () => { regSuscribir(); regPintar(); document.getElementById('regModal').classList.add('open'); };
window.regCerrar = () => document.getElementById('regModal').classList.remove('open');
function regPintar(){
  const b = document.getElementById('regBody'); if (!b) return;
  b.innerHTML = REGIMENES.map(r => `<div class="reg-fila"><label for="reg_${r.k}">${escHtml(r.t)}</label><div class="reg-in"><input type="number" id="reg_${r.k}" min="0" max="100" step="0.01" value="${r.fijo != null ? r.fijo : (regTarifas[r.k] ?? '')}" ${r.fijo != null ? 'readonly title="El régimen simple no tiene retención"' : 'placeholder="0"'}/><span>%</span></div></div>`).join('');
}
window.regGuardar = async () => {
  const tarifas = {};
  for (const r of REGIMENES) { if (r.fijo != null) continue; const v = Number(document.getElementById('reg_' + r.k)?.value)||0;
    if (v < 0 || v > 100) { toast(`La tarifa de ${r.t} debe estar entre 0 y 100.`, 'error'); return; } tarifas[r.k] = v; }
  try { await setDoc(doc(db,'uiPrefs','regimenRetencion'), { tarifas, updatedAt: serverTimestamp(), por: currentProfile?.nombreCompleto || currentUser?.email || '' });
    regTarifas = tarifas; regCerrar(); toast('Tarifas de retención guardadas.', 'success'); trRegimenSugerir(); }
  catch (e) { toast('No se pudieron guardar las tarifas: ' + e.message, 'error'); }
};
/* En «Editar liquidación»: muestra el régimen del especialista y propone su % (no cambia nada sin clic) */
function trRegimenSugerir(){
  const box = document.getElementById('trRegimen'); if (!box || !document.getElementById('tablaRowModal')?.classList.contains('open')) return;
  const nom = document.getElementById('trNombre')?.value || '', k = regDeEspecialista(nom);
  if (!k) { box.innerHTML = `Régimen del especialista sin definir (ficha del cliente). <a href="#" onclick="event.preventDefault();regAbrir()">Tarifas</a>`; return; }
  const t = regTarifa(k), modo = document.getElementById('trReteModo')?.value, pct = Number(document.getElementById('trRetePct')?.value)||0;
  const igual = (modo === 'pct' && pct === t) || (t === 0 && !(Number(document.getElementById('trReteFuente')?.value)||0));
  box.innerHTML = `${escHtml(regNombre(k))}: ${String(t).replace('.', ',')} %` + (igual ? '' : ` · <a href="#" onclick="event.preventDefault();trRegimenAplicar()">Usar ${String(t).replace('.', ',')} %</a>`) + ` · <a href="#" onclick="event.preventDefault();regAbrir()">Tarifas</a>`;
}
window.trRegimenAplicar = () => {
  const k = regDeEspecialista(document.getElementById('trNombre')?.value || ''); if (!k) return;
  const t = regTarifa(k);
  if (t === 0) { document.getElementById('trReteModo').value = 'valor'; trReteModo(); document.getElementById('trReteFuente').value = 0; }
  else { document.getElementById('trReteModo').value = 'pct'; document.getElementById('trRetePct').value = t; trReteModo(); }
  calcValorPagar(); trRegimenSugerir();
};

/* Retención en la fuente: valor en pesos o porcentaje del VALOR FACTURA (redondeado, sin centavos).
   Se guarda siempre el valor en pesos (reteFuente) más el modo y el porcentaje, así el resto de la app no cambia. */
window.trReteModo = () => {
  const pct = document.getElementById('trReteModo')?.value === 'pct';
  const pIn = document.getElementById('trRetePct'), vIn = document.getElementById('trReteFuente');
  pIn.hidden = !pct; vIn.hidden = pct; vIn.readOnly = pct; vIn.classList.toggle('tr-rete-auto', pct); vIn.tabIndex = pct ? -1 : 0;
  if (pct) { if (!pIn.value) { const vf = Number(document.getElementById('trValorFactura').value)||0, v = Number(vIn.value)||0; if (vf && v) pIn.value = Math.round(v / vf * 10000) / 100; } setTimeout(() => pIn.focus(), 0); }
  calcValorPagar();
};
function trReteAplicar(){
  const modo = document.getElementById('trReteModo')?.value, info = document.getElementById('trReteCalc'); if (!info) return;
  if (modo !== 'pct') { info.textContent = ''; return; }
  const pIn = document.getElementById('trRetePct');
  let pct = Number(pIn.value)||0; if (pct < 0) { pct = 0; pIn.value = 0; } if (pct > 100) { pct = 100; pIn.value = 100; }
  const vf = Number(document.getElementById('trValorFactura').value)||0;
  const v = Math.round(vf * pct / 100);
  document.getElementById('trReteFuente').value = v || (pIn.value === '' ? '' : 0);
  info.textContent = pct ? `${String(pct).replace('.', ',')} % de ${fmtCOP(vf)} = ${fmtCOP(v)}` : '';
}
let _abonoLegado = false;
window.calcValorPagar = () => {
  trReteAplicar();   // en modo % la retención sigue al valor factura
  trRegimenSugerir();
  const g     = id => Number(document.getElementById(id)?.value)||0;
  const abono = _abonoLegado ? g('trAbono') : 0;   // solo las filas con abono digitado lo usan como base
  const descuentos = g('trGlosa') + g('trReteFuente') + g('trAfc')
                   + g('trResidentes') + g('trTiquetes')
                   + g('trHotel') + g('trTransporte');
  // Si ABONO > 0: base = ABONO. Si ABONO = 0: base = VALOR FACTURA
  const base  = abono > 0 ? abono : g('trValorFactura');
  const neto  = base - descuentos;                         // valor neto tras descuentos
  const pagado = (_pagosTmp||[]).reduce((s,p)=>s+(Number(p.monto)||0),0);
  const saldo = Math.max(0, neto - pagado);                // Valor a Pagar = saldo pendiente (nunca negativo)
  const el = document.getElementById('trValorPagar');
  if (el) { el.value = saldo; el.style.color = (neto < 0) ? 'var(--red)' : 'var(--navy)'; }
  calcSaldo();
};

/* ── PAGOS REALIZADOS (historial) y SALDO PENDIENTE ── */
let _pagosTmp = [];   // [{monto, fecha}] del modal activo (original)
/* Tipo de abono: lista del 1 al 10. El valor se guarda en el campo ref de siempre, así los pagos
   anteriores conservan su texto (si no está en la lista, se muestra como opción adicional). */
const TIPOS_ABONO = ['1er Abono','2do Abono','3er Abono','4to Abono','5to Abono','6to Abono','7mo Abono','8vo Abono','9no Abono','10mo Abono'];
function tipoAbonoSiguiente(pagos){
  const usados = new Set((pagos||[]).map(p => p.ref));
  return TIPOS_ABONO.find(t => !usados.has(t)) || '';
}
function tipoAbonoOpciones(actual){
  const extra = actual && !TIPOS_ABONO.includes(actual) ? [actual] : [];
  return `<option value="" ${actual ? '' : 'selected'}>Seleccionar…</option>`
    + [...TIPOS_ABONO, ...extra].map(t => `<option value="${escHtml(t)}" ${t === actual ? 'selected' : ''}>${escHtml(t)}</option>`).join('');
}

window.addPagoRow = () => {
  // Se registra quién anotó el pago (trazabilidad); referencia opcional
  _pagosTmp.push({ monto:0, fecha:uroHoyLocal(), ref: tipoAbonoSiguiente(_pagosTmp),
    por: currentProfile?.nombreCompleto || currentUser?.email || '' });
  renderPagos();
  setTimeout(() => document.querySelector('#pagosList .pago-row:last-child .pago-monto')?.focus(), 0);
};
window.removePagoRow = (i) => {
  _pagosTmp.splice(i,1);
  renderPagos();
};
window.onPagoChange = (i, campo, val) => {
  if (!_pagosTmp[i]) return;
  _pagosTmp[i][campo] = campo==='monto' ? (Number(val)||0) : val;
  calcValorPagar();
};
function renderPagos() {
  const list  = document.getElementById('pagosList');
  const empty = document.getElementById('pagosEmpty');
  if (!list) return;
  if (!_pagosTmp.length) {
    const nP = document.getElementById('trPagosN'); if (nP) nP.textContent = '';
    list.innerHTML = '';
    if (empty) empty.style.display = 'block';
    calcValorPagar(); return;
  }
  if (empty) empty.style.display = 'none';
  const nP0 = document.getElementById('trPagosN'); if (nP0) nP0.textContent = _pagosTmp.length;
  list.innerHTML = `<div class="pago-row pago-cab" aria-hidden="true"><span>Fecha</span><span>Monto</span><span>Tipo de abono</span><span>Registró</span><span></span></div>`
  + _pagosTmp.map((p,i)=>`
    <div class="pago-row">
      <input type="date" class="pago-fecha" value="${p.fecha||''}" aria-label="Fecha del pago ${i+1}"
        onchange="onPagoChange(${i},'fecha',this.value)"/>
      <input type="number" class="pago-monto" value="${p.monto||''}" placeholder="Monto" min="0" aria-label="Monto del pago ${i+1}"
        oninput="onPagoChange(${i},'monto',this.value)"/>
      <select class="pago-ref" aria-label="Tipo de abono del pago ${i+1}" onchange="onPagoChange(${i},'ref',this.value)">${tipoAbonoOpciones(p.ref||'')}</select>
      <span class="pago-por" title="${escHtml(p.por||'')}">${escHtml(p.por||'—')}</span>
      <button type="button" class="pago-del" onclick="removePagoRow(${i})" title="Eliminar pago" aria-label="Eliminar pago ${i+1}"><i class="fa-solid fa-trash"></i></button>
      <input type="text" class="pago-obs" value="${escHtml(p.obs||'')}" maxlength="300" placeholder="Observación del abono (opcional · sale en el PDF del correo)" aria-label="Observación del pago ${i+1}"
        oninput="onPagoChange(${i},'obs',this.value)"/>
    </div>`).join('');
  calcValorPagar();
}
/* Calcula neto, total pagado, saldo y actualiza alerta/estado */
function calcSaldo() {
  // Calcular el NETO directamente (no leer trValorPagar, que ahora es el saldo)
  const g = id => Number(document.getElementById(id)?.value)||0;
  const abono = _abonoLegado ? g('trAbono') : 0;
  const descuentos = g('trGlosa') + g('trReteFuente') + g('trAfc')
                   + g('trResidentes') + g('trTiquetes')
                   + g('trHotel') + g('trTransporte');
  const base = abono > 0 ? abono : g('trValorFactura');
  const neto = base - descuentos;
  const pagado = _pagosTmp.reduce((s,p)=>s+(Number(p.monto)||0),0);
  const saldo = Math.max(0, neto - pagado);

  const setTxt = (id,val) => { const el=document.getElementById(id); if(el) el.textContent = fmtCOP(val); };
  setTxt('prBase', base);
  setTxt('prDesc', descuentos);
  const bl = document.getElementById('prBaseL'); if (bl) bl.textContent = abono > 0 ? 'Base (abono)' : 'Base (valor factura)';
  setTxt('prNeto', neto);
  // Los pagos se RESTAN del neto: se muestran con signo menos
  const pgEl = document.getElementById('prPagado'); if (pgEl) { pgEl.textContent = (pagado > 0 ? '− ' : '') + fmtCOP(pagado); pgEl.classList.toggle('pr-resta', pagado > 0); }
  const exceso = neto > 0 ? pagado - neto : 0;
  setTxt('prSaldo', exceso > 1 ? -Math.round(exceso) : saldo);   // pagado de más: saldo negativo a favor de Uroexpertos

  const estadoEl = document.getElementById('prEstado');
  const saldoEl  = document.getElementById('prSaldo');
  if (!estadoEl) return;

  if (exceso > 1) {
    // Pagado de más: se muestra el exceso (antes quedaba oculto como «Pagado»)
    const porMonto = new Map();
    _pagosTmp.forEach((p,i) => { const m = Math.round((Number(p.monto)||0)*100)/100; if (!(m > 0)) return;
      (porMonto.get(m) || porMonto.set(m, []).get(m)).push(p.ref || ('pago ' + (i+1))); });
    const rep = [...porMonto.entries()].filter(([,l]) => l.length > 1);
    estadoEl.className = 'pr-estado pr-exceso';
    estadoEl.innerHTML = `<i class="fa-solid fa-triangle-exclamation"></i> <span><b>Pagado de más: ${fmtCOP(exceso)}</b><br>Los pagos superan el neto liquidado.`
      + (rep.length ? ' Revisa posibles pagos repetidos: ' + rep.map(([m,l]) => `${l.map(escHtml).join(' y ')} (${fmtCOP(m)})`).join('; ') + '.' : ' Revisa si hay un pago registrado dos veces.') + '</span>';
    if (saldoEl) saldoEl.style.color = '#b42318';
  } else if (saldo <= 0 && neto > 0) {
    estadoEl.className = 'pr-estado pr-pagada';
    estadoEl.innerHTML = '<i class="fa-solid fa-circle-check"></i> Pagado: los pagos registrados cubren el neto';
    if (saldoEl) saldoEl.style.color = '#1a7a3d';
  } else if (neto > 0 && saldo <= neto * 0.10) {
    estadoEl.className = 'pr-estado pr-proximo';
    estadoEl.innerHTML = `<i class="fa-solid fa-triangle-exclamation"></i> Pago próximo a completarse — saldo ${fmtCOP(saldo)}`;
    if (saldoEl) saldoEl.style.color = '#b35900';
  } else {
    estadoEl.className = 'pr-estado';
    estadoEl.innerHTML = neto <= 0 ? '' : pagado > 0
      ? `<i class="fa-solid fa-circle-half-stroke"></i> Pago parcial: falta ${fmtCOP(saldo)}`
      : '<i class="fa-regular fa-clock"></i> Pendiente: sin pagos registrados';
    if (saldoEl) saldoEl.style.color = 'var(--navy)';
  }
}

let _guardandoFila = false;   // candado anti-reentrada (doble clic / doble evento)
window.saveTablaRow = async () => {
  // Si ya hay un guardado en curso, ignorar (evita doble ejecución)
  if (_guardandoFila) return;

  const tablaId = editTablaRowTablaId;
  const tabla   = tablasEgreso.find(t=>t.id===tablaId);
  if (!tabla) return;

  // Guardar identIds actuales de la tabla (soporte múltiple)
  const tablaForIdent  = tablasEgreso.find(t=>t.id===tablaId);
  const currentIdentIds = tablaForIdent?._selectedIdents?.length
    ? tablaForIdent._selectedIdents
    : (tablaForIdent?._selectedIdent ? [tablaForIdent._selectedIdent] : []);
  const currentIdentId  = currentIdentIds[0]||'';

  const esEdicion = (editTablaRowIdx !== null && editTablaRowIdx !== undefined);
  const orig = esEdicion ? (_filaOriginal || tabla.filas?.[editTablaRowIdx] || {}) : null;
  // Posición vigente de la fila editada (la tabla pudo cambiar mientras el panel estaba abierto)
  let posEdit = editTablaRowIdx;
  if (esEdicion) {
    const firmaOrig = JSON.stringify(orig);
    posEdit = orig.rowId ? (tabla.filas||[]).findIndex(f=>f.rowId===orig.rowId)
                         : (tabla.filas||[]).findIndex(f=>JSON.stringify(f)===firmaOrig);
    if (posEdit === -1) { toast('Esta fila cambió o se eliminó mientras la editabas. Ciérrala y vuelve a abrirla.','error'); return; }
  }

  const fila = {
    // Al editar se conservan TODOS los campos existentes (relación con la liquidación, envíos de correo, etc.)
    ...(esEdicion ? orig : {}),
    // ID único estable por fila (para editar/eliminar sin ambigüedad y detectar duplicados)
    rowId:        esEdicion ? (orig.rowId || genRowId()) : genRowId(),
    // La relación con la factura a la entidad NO cambia al editar; solo se asigna a filas nuevas
    identId:      esEdicion ? (orig.identId ?? currentIdentId)   : currentIdentId,
    identIds:     esEdicion ? (orig.identIds ?? currentIdentIds) : currentIdentIds,
    factura:      document.getElementById('trFactura').value.trim(),
    mes:          document.getElementById('trMes').value,
    nombre:       document.getElementById('trNombre').value.trim(),
    tipoPersona:  document.getElementById('trTipoPersona')?.value||'',
    valorFactura: Number(document.getElementById('trValorFactura').value)||0,
    abono:        _abonoLegado ? (Number(document.getElementById('trAbono').value)||0) : 0,   // filas nuevas: la casilla solo muestra los giros
    glosa:        Number(document.getElementById('trGlosa').value)||0,
    reteFuente:   Number(document.getElementById('trReteFuente').value)||0,
    reteFuenteModo: document.getElementById('trReteModo')?.value === 'pct' ? 'pct' : 'valor',
    reteFuentePct:  document.getElementById('trReteModo')?.value === 'pct' ? (Number(document.getElementById('trRetePct').value)||0) : 0,
    afc:          Number(document.getElementById('trAfc').value)||0,
    residentes:   Number(document.getElementById('trResidentes').value)||0,
    tiquetes:     Number(document.getElementById('trTiquetes').value)||0,
    hotel:        Number(document.getElementById('trHotel').value)||0,
    transporte:   Number(document.getElementById('trTransporte').value)||0,
    valorPagar:   Number(document.getElementById('trValorPagar').value)||0,
    pagos:        JSON.parse(JSON.stringify(_pagosTmp||[])),
  };

  // 9.9 · liquidación de una factura cerrada: los valores y descuentos no cambian sin abrir el candado; los pagos sí se registran
  { const mid = fila.identId, cand = mid ? segCandadoDe(mid) : null;
    const campos = ['factura','nombre','valorFactura','abono','glosa','reteFuente','afc','residentes','tiquetes','hotel','transporte'];
    const cambia = esEdicion ? campos.some(k => String(orig[k] ?? '') !== String(fila[k] ?? '') && !((orig[k] ?? '') === '' && Number(fila[k]) === 0)) : true;
    if (cambia && !segExigir('facturacion', 'modificar liquidaciones')) return;
    if (!cambia && JSON.stringify(orig?.pagos || []) !== JSON.stringify(fila.pagos || []) && !segExigir('contabilidad', 'registrar pagos')) return;
    if (cand && cand.cerrado && !cand.editable && cambia) { const e = egresos.find(x => x.id === mid); toast(`La factura ${e?.factura || ''} está cerrada (candado): ábrela con tu contraseña y un motivo para cambiar valores o descuentos de su liquidación.`, 'error'); return; }
    if (mid && esEdicion) { const dif = campos.filter(k => String(orig[k] ?? '') !== String(fila[k] ?? '')).map(k => ({ accion: 'Cambio en liquidación', campo: `${fila.factura || fila.nombre} · ${k}`, antes: segTxt(orig[k]), despues: segTxt(fila[k]) }));
      const pa = (orig.pagos || []).length, pn = (fila.pagos || []).length; if (pa !== pn) dif.push({ accion: pn > pa ? 'Registró pago' : 'Quitó pago', campo: `${fila.factura || fila.nombre} · pagos`, antes: String(pa), despues: String(pn) });
      if (dif.length) segHistorial(mid, dif, cand?.abiertoPorMi ? cand.abierto.motivo : ''); } }
  const filas = [...(tabla.filas||[])];

  // ── Validación anti-duplicados: la factura no puede existir ya en esta tabla ──
  const facturaNueva = (fila.factura||'').trim().toLowerCase();
  if (facturaNueva) {
    const duplicada = filas.some((f, i) => {
      // Al editar, ignorar la propia fila que se está editando
      if (esEdicion && i === posEdit) return false;
      return (f.factura||'').trim().toLowerCase() === facturaNueva;
    });
    if (duplicada) {
      toast(`La factura "${fila.factura}" ya existe en esta tabla. No se puede duplicar.`, 'error');
      return;
    }
  }

  // Activar candado y deshabilitar el botón ANTES del await
  _guardandoFila = true;
  const btnGuardar = document.querySelector('#tablaRowModal .btn-primary');
  const btnHtmlPrev = btnGuardar?.innerHTML;
  if (btnGuardar) { btnGuardar.disabled = true; btnGuardar.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Guardando...'; }

  if (esEdicion) {
    filas[posEdit] = fila;
  } else {
    filas.push(fila);
  }

  try {
    await updateDoc(doc(db,'tablasEgreso',tablaId),{filas, updatedAt:serverTimestamp()});
    toast('Fila guardada.','success');
    closeTablaRowModal();
  } catch(e) {
    toast('Error: '+e.message,'error');
  } finally {
    // Liberar candado y restaurar botón siempre
    _guardandoFila = false;
    if (btnGuardar) { btnGuardar.disabled = false; btnGuardar.innerHTML = btnHtmlPrev; }
  }
};

/* Genera un ID único para cada fila (timestamp + aleatorio) */
function genRowId(){
  return 'r' + Date.now().toString(36) + Math.random().toString(36).slice(2,8);
}

window.deleteTablaRow = async (tablaId, idx, rowId) => {
  // Identificar la fila ANTES de confirmar (por rowId estable si existe)
  const t0 = tablasEgreso.find(t=>t.id===tablaId);
  const objetivo = rowId ? (t0?.filas||[]).find(f=>f.rowId===rowId) : t0?.filas?.[idx];
  if (!objetivo) { toast('No se encontró la fila. Recarga la vista.','error'); return; }
  if (!segExigir('facturacion', 'eliminar filas de liquidación')) return;
  if (objetivo.identId && !segCandadoDe(objetivo.identId).editable) { toast('La factura de esta fila está cerrada (candado): no se puede eliminar la fila.', 'error'); return; }
  if (!confirm(`¿Eliminar la fila de la factura ${objetivo.factura||'(sin número)'} — ${objetivo.nombre||''}?`)) return;
  // Releer la tabla vigente DESPUÉS de confirmar: pudo cambiar mientras el diálogo estaba abierto
  const tabla = tablasEgreso.find(t=>t.id===tablaId);
  if (!tabla) return;
  const filas = [...(tabla.filas||[])];
  const firma = JSON.stringify(objetivo);
  const pos = objetivo.rowId ? filas.findIndex(f=>f.rowId===objetivo.rowId) : filas.findIndex(f=>JSON.stringify(f)===firma);
  if (pos === -1) { toast('La fila ya no existe (otro usuario la cambió).','error'); return; }
  filas.splice(pos,1);
  try {
    await updateDoc(doc(db,'tablasEgreso',tablaId),{filas});
    toast('Fila eliminada.');
  } catch(e) { toast('Error: '+e.message,'error'); }
};

/* ══ LIQUIDACIÓN / VISTA PDF ══ */
