/* ── Llamada al backend ── */
async function iaApi(body, opc = {}) {
  if (!currentUser) throw new Error('Inicia sesión.');
  const token = typeof currentUser.getIdToken === 'function' ? await currentUser.getIdToken() : '';
  let r;
  for (const url of IA_ENDPOINTS) {
    try { r = await fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + token }, body: JSON.stringify(body), signal: opc.signal }); }
    catch (e) { if (e?.name === 'AbortError') throw e; r = null; continue; }
    if (r.status !== 404) break;
  }
  if (!r) throw new Error('No hay conexión con el servicio de IA.');
  // Respuesta progresiva (Vercel): líneas JSON {t:'d', c:'texto'} … y al final {t:'fin', …respuesta}
  if (r.ok && /ndjson/.test(r.headers.get('content-type') || '') && r.body?.getReader) {
    const rd = r.body.getReader(), dec = new TextDecoder(); let buf = '', fin = null;
    while (true) {
      const { value, done } = await rd.read(); if (done) break;
      buf += dec.decode(value, { stream: true }); let i;
      while ((i = buf.indexOf('\n')) >= 0) { const l = buf.slice(0, i).trim(); buf = buf.slice(i + 1); if (!l) continue;
        let o; try { o = JSON.parse(l); } catch (e) { continue; }
        if (o.t === 'd' && opc.onDelta) opc.onDelta(o.c || ''); else if (o.t === 'fin') fin = o; else if (o.t === 'error') throw new Error(o.error || 'Error del servicio de IA.'); }
    }
    if (!fin) throw new Error('La respuesta de la IA se cortó. Intenta de nuevo.');
    delete fin.t; return fin;
  }
  let j = null; try { j = await r.json(); } catch (e) {}
  if (!r.ok) throw new Error((j && j.error) || (r.status === 404 ? 'El servicio de IA no está publicado (api/ai.js).' : 'Error del servicio de IA (' + r.status + ').'));
  return j;
}
function iaRegistrar(accion, detalle, extra = {}) {
  if (!currentUser) return;
  addDoc(collection(db, 'iaHistorial'), { uid: currentUser.uid, usuario: currentProfile?.nombreCompleto || currentUser.email || '', accion, detalle: String(detalle || '').slice(0, 400), ...extra, fechaISO: new Date().toISOString(), createdAt: serverTimestamp() }).catch(() => {});
}

/* ── JARVIS 2.0 · herramientas de datos (cálculo en BOE con las fórmulas existentes; la IA solo elige) ── */
function iaMesClave(anio, mes){ const i = iaMesIdx(mes); return anio && i >= 0 ? `${anio}-${String(i + 1).padStart(2, '0')}` : ''; }
function iaMesDeEgreso(e){ return String(e.honorarioMes || e.fechaFacturacion || '').slice(0, 7); }
function iaEstadoSeguro(e){ try { return egmEstadoEgreso(e); } catch (err) { return null; } }
function iaSumaEgresos(lista){
  const t = { facturas: 0, facturado: 0, glosa: 0, ica: 0, retencion: 0, neto_a_recibir: 0, abonado: 0, saldo_por_cobrar: 0, honorarios_por_pagar: 0, administracion: 0 };
  lista.forEach(e => { const r = iaEstadoSeguro(e); t.facturas++; t.facturado += iaNum(e.valorEntidad);
    if (!r) return; t.glosa += r.glosa; t.ica += r.ica; t.retencion += r.retencion; t.neto_a_recibir += r.netoEntidad; t.abonado += r.abonos;
    t.saldo_por_cobrar += Math.max(0, r.saldoCobrar); t.honorarios_por_pagar += Math.max(0, r.valorPagar); t.administracion += r.administracion; });
  const txt = {}; Object.keys(t).forEach(k => { if (k !== 'facturas') txt[k + '_txt'] = iaFmt(t[k]); });
  return { ...t, ...txt };
}
function iaResumenUro(egr, a = {}){
  const meses = [...new Set(egr.map(iaMesDeEgreso).filter(Boolean))].sort();
  let clave = iaMesClave(a.anio, a.mes), anio = a.anio;
  if (!clave && !anio) { clave = meses.at(-1) || ''; }
  const deEnt = e => !a.entidad || iaCoincide(e.nombre, a.entidad);
  const del = k => egr.filter(e => deEnt(e) && (k.length === 7 ? iaMesDeEgreso(e) === k : iaMesDeEgreso(e).startsWith(k)));
  const lista = clave ? del(clave) : del(String(anio));
  const out = { criterio: 'Facturas a la entidad de UROEXPERTOS por mes de honorario (o fecha de facturación si no tiene)', periodo: clave || String(anio), entidad: a.entidad || 'todas', registros: lista.length, totales: iaSumaEgresos(lista) };
  const porEnt = new Map(); lista.forEach(e => { const k = e.nombre || 'Sin entidad'; (porEnt.get(k) || porEnt.set(k, []).get(k)).push(e); });
  out.por_entidad = [...porEnt.entries()].map(([k, l]) => { const s = iaSumaEgresos(l); return { entidad: k, facturas: l.length, facturado_txt: s.facturado_txt, saldo_por_cobrar_txt: s.saldo_por_cobrar_txt, glosa_txt: s.glosa_txt, retencion_txt: s.retencion_txt, _f: s.facturado }; })
    .sort((x, y) => y._f - x._f).slice(0, 20).map(({ _f, ...x }) => x);
  if (clave) { const [y, m] = clave.split('-').map(Number), ant = m === 1 ? `${y - 1}-12` : `${y}-${String(m - 1).padStart(2, '0')}`, la = del(ant);
    const sa = iaSumaEgresos(la); out.mes_anterior = { periodo: ant, registros: la.length, facturado_txt: sa.facturado_txt, saldo_por_cobrar_txt: sa.saldo_por_cobrar_txt };
    out.variacion_facturado_pct = sa.facturado ? Math.round((out.totales.facturado - sa.facturado) / sa.facturado * 1000) / 10 : null; }
  out.meses_con_datos = meses.slice(-12);
  return out;
}
function iaCartera(egr, a = {}, hoy){
  const g = new Map();
  egr.filter(e => !a.entidad || iaCoincide(e.nombre, a.entidad)).forEach(e => { const r = iaEstadoSeguro(e); if (!r || r.saldoCobrar < 1) return;
    const k = e.nombre || 'Sin entidad', x = g.get(k) || { entidad: k, facturas: 0, saldo: 0, abonado: 0, dias_max: 0, detalle: [] };
    const d = iaDias(e.fechaFacturacion, hoy); x.facturas++; x.saldo += r.saldoCobrar; x.abonado += r.abonos; x.dias_max = Math.max(x.dias_max, d || 0);
    x.detalle.push({ factura: e.factura || '(sin número)', honorario_mes: e.honorarioMes || '', saldo_txt: iaFmt(r.saldoCobrar), dias: d, estado: r.estado }); g.set(k, x); });
  const l = [...g.values()].sort((p, q) => q.saldo - p.saldo);
  return { criterio: 'Saldo por cobrar = neto a recibir (facturado − glosa − ICA − retención) − abonos registrados', fecha: hoy, entidades: l.length,
    total_por_cobrar_txt: iaFmt(l.reduce((s, x) => s + x.saldo, 0)), facturas: l.reduce((s, x) => s + x.facturas, 0),
    ranking: l.slice(0, 15).map(x => ({ entidad: x.entidad, facturas: x.facturas, saldo_txt: iaFmt(x.saldo), abonado_txt: iaFmt(x.abonado), dias_factura_mas_antigua: x.dias_max, facturas_detalle: x.detalle.slice(0, 8) })),
    fuente: 'UROEXPERTOS (facturas a la entidad y abonos)' };
}
function iaLiquidaciones(egr, a = {}){
  const fil = egr.filter(e => (!a.entidad || iaCoincide(e.nombre, a.entidad)) && (!a.honorario_mes || iaMesDeEgreso(e).startsWith(a.honorario_mes))
    && (!a.factura || iaNorm(e.factura).includes(iaNorm(a.factura)) || (e.hijas || []).some(h => iaNorm(h.factura).includes(iaNorm(a.factura))))
    && (!a.especialista || (e.hijas || []).some(h => iaCoincide([h.nombre, h.proveedor].join(' '), a.especialista))));
  const filas = fil.map(e => { const r = iaEstadoSeguro(e); let u = null; try { u = egmUnirHijasLiquidacion(e.id, (e.hijas || []).map(h => ({ ...h }))); } catch (err) {}
    const ctrl = (r?.controles || []).filter(c => c.estado && c.estado !== 'cuadra').map(c => ({ control: c.nombre, regla: c.regla, estado: c.estado, detalle: c.detalle || c.dif || null }));
    const al = (r?.alertas || []).filter(x => !x.info).map(x => x.texto + (x.valor ? ' (' + iaFmt(x.valor) + ')' : '') + (x.detalle ? ' — ' + x.detalle : ''));
    return { factura: e.factura || '(sin número)', entidad: e.nombre || '', honorario_mes: e.honorarioMes || '', estado: r?.estado || 'sin calcular',
      valor_entidad_txt: iaFmt(e.valorEntidad), saldo_por_cobrar_txt: r ? iaFmt(r.saldoCobrar) : null, por_pagar_especialistas_txt: r ? iaFmt(r.valorPagar) : null,
      controles_en_diferencia: ctrl, alertas: al, con_diferencias: !!(ctrl.length || al.length),
      liquidaciones: (u?.hijas || []).filter(h => !a.especialista || iaCoincide([h.nombre, h.proveedor].join(' '), a.especialista)).slice(0, 15).map(h => ({ factura: h.factura || '', especialista: h.nombre || '', valor_especialista_txt: iaFmt(h.valorEspecialista), descuentos_txt: iaFmt(h.descuentos), pagado_txt: iaFmt(h.pagado), saldo_txt: iaFmt(h.conLiquidacion ? h.saldoLiq : h.neto), con_liquidacion: h.conLiquidacion })) };
  });
  const out = a.solo_diferencias ? filas.filter(x => x.con_diferencias) : filas;
  return { registros: out.length, revisadas: filas.length, con_diferencias: filas.filter(x => x.con_diferencias).length, facturas: out.slice(0, 15),
    nota: 'Controles y alertas calculados por BOE con las mismas reglas de la factura a la entidad.', fuente: 'UROEXPERTOS (facturas a la entidad y tablas de liquidación)' };
}
function iaTurnos(a = {}){
  const todos = [...(puedeVer('turnos') ? (turnos || []) : []), ...(puedeVer('turnos2') ? (typeof ct_turnos !== 'undefined' ? ct_turnos || [] : []) : [])];
  const hoy = iaHoy(), desde = a.desde || hoy, hasta = a.hasta || '9999-12-31';
  const l = todos.filter(t => (t.fechaHasta || t.fecha || '') >= desde && (t.fecha || '') <= hasta && (!a.especialista || iaCoincide(t.especialista, a.especialista)) && (!a.sede || iaCoincide(t.sede, a.sede)))
    .sort((x, y) => String(x.fecha).localeCompare(String(y.fecha)));
  return { desde, hasta, registros: l.length, turnos: l.slice(0, 30).map(t => ({ fecha: t.fecha, hasta: t.fechaHasta || t.fecha, especialista: t.especialista || '', sede: t.sede || '', tipo: t.tipo || '', servicio: t.servicio || '', trayecto: t.trayecto || '' })), fuente: 'Cuadro de turnos' };
}
function iaDigitacion(a = {}){
  const R = JV.registros, c = f => R.filter(f).length, porMes = {}, porEnt = {};
  R.filter(r => !r.error).forEach(r => { const m = jvFechaISO(r.fecha).slice(0, 7) || 'sin fecha'; porMes[m] = (porMes[m] || 0) + 1; const e = r.entidad || 'sin entidad'; porEnt[e] = (porEnt[e] || 0) + 1; });
  const docs = [...JV.archivos.values()].concat((JV.pendientes || []).map(f => ({ nombre: f.name, estado: 'pendiente' })));
  const est = k => docs.filter(d => d.estado === k).map(d => ({ archivo: d.nombre, motivo: d.motivo || null }));
  const qx = R.filter(r => r.tipo === JV_CIR);
  return { atenciones: R.length, registros_digitados: jvFilas(R.filter(r => !r.error)).length, consultas: c(r => r.tipo === 'CONSULTA'), interconsultas: c(r => r.tipo === 'INTERCONSULTA'),
    cirugias: qx.length, procedimientos_quirurgicos: qx.reduce((s, r) => s + (r.procedimientos || []).length, 0), procedimientos_por_revisar: qx.flatMap(r => r.procedimientos || []).filter(x => !x.codigo || !x.descripcion || (x.dudas || []).length).length,
    informes_quirurgicos_pendientes: qx.filter(r => jvEstado(r) !== 'ok').map(r => ({ archivo: r.archivo, motivo: jvMotivoRevision([r]) })), sin_tipo: c(r => !r.error && !r.tipo),
    validados: c(r => jvEstado(r) === 'ok'), por_revisar: c(r => jvEstado(r) === 'rev'), con_error: c(r => jvEstado(r) === 'err'), por_mes_del_folio: porMes, por_entidad: porEnt,
    procesando: JV.proc ? { total: JV.proc.total, procesados: JV.proc.hechos, actual: JV.proc.actual } : null,
    documentos_sesion: { total: docs.length, ilegibles: est('ilegible'), con_error: est('error'), requieren_revision: est('rev'), duplicados: est('duplicado').length, pendientes: est('pendiente').length },
    nota: 'Por confidencialidad no se envían cédulas ni nombres de pacientes; están en la tabla de JARVIS.' };
}

/* ── Herramientas: consultas determinísticas que pide el modelo ── */
const IA_SIN_ACCESO = s => ({ sin_acceso: true, mensaje: `El usuario no tiene acceso a ${s}.` });
function iaEjecutarHerramienta(nombre, args) {
  const f = iaFuentes(), hoy = iaHoy();
  switch (nombre) {
    case 'consultar_facturacion': return f.facturas ? iaFacturacion(f.facturas, doctors, args) : IA_SIN_ACCESO('Reportes');
    case 'comparar_periodos':     return f.facturas ? iaComparar(f.facturas, doctors, args) : IA_SIN_ACCESO('Reportes');
    case 'consultar_pagos_pendientes': return f.egresos ? iaPendientes(f.egresos, args, hoy) : IA_SIN_ACCESO('UROEXPERTOS');
    case 'consultar_egresos':     return f.egresos ? iaEgresos(f.egresos, args) : IA_SIN_ACCESO('UROEXPERTOS');
    case 'consultar_clientes':    return f.doctors ? iaClientes(f.doctors, args) : IA_SIN_ACCESO('Clientes');
    case 'consultar_alertas': {
      const l = iaAlertasLista.filter(a => (!args.tipo || args.tipo === 'todas' || a.tipo === args.tipo) && (!args.prioridad || args.prioridad === 'todas' || a.prioridad === args.prioridad));
      return { fecha: hoy, registros: l.length, resumen: iaResumen(l), nota: 'Posibles anomalías detectadas por reglas fijas; no son errores confirmados.',
        alertas: l.slice(0, 20).map(a => ({ prioridad: a.prioridad, tipo: a.tipo, titulo: a.titulo, que: a.que, valor_afectado: a.valor != null ? iaFmt(a.valor) : null, porque: a.porque, accion: a.accion, registros: a.registros.length })) };
    }
    case 'consultar_documentos': {
      const l = iaDocs.filter(d => (!args.anio || Number(d.anio) === Number(args.anio)) && (!args.mes || iaNorm(d.mes) === iaNorm(args.mes)) && (!args.doctor || iaCoincide(d.doctorNombre, args.doctor)));
      return { registros: l.length, documentos: l.slice(0, 25).map(d => ({ archivo: d.archivo, especialista: d.doctorNombre, periodo: iaPeriodoTxt(d.anio, d.mes), numero: d.numero || null, valor_txt: d.valor ? iaFmt(d.valor) : null, entidad: d.entidad || null, cargado: (d.creadoISO || '').slice(0, 10), procesado_con_ia: !!d.procesadoIA, destino: d.destino })) };
    }
    case 'listar_especialistas': return { registros: doctors.length, especialistas: doctors.map(d => d.nombre || d.especialista).filter(Boolean).slice(0, 150) };
    case 'resumen_uroexpertos':   return f.egresos ? iaResumenUro(f.egresos, args) : IA_SIN_ACCESO('UROEXPERTOS');
    case 'consultar_cartera':     return f.egresos ? iaCartera(f.egresos, args, hoy) : IA_SIN_ACCESO('UROEXPERTOS');
    case 'consultar_liquidaciones': return f.egresos ? iaLiquidaciones(f.egresos, args) : IA_SIN_ACCESO('UROEXPERTOS');
    case 'consultar_turnos':      return puedeVer('turnos') || puedeVer('turnos2') ? iaTurnos(args) : IA_SIN_ACCESO('Cuadro de turnos');
    case 'consultar_digitacion':  return iaDigitacion(args);
  }
  return { error: 'Herramienta desconocida.' };
}

/* ── Chat ── */
const IA_SUGERENCIAS = ['¿Cuánto hemos facturado este mes?', '¿Qué especialistas tienen honorarios pendientes de pago?', '¿Cuáles son las facturas pendientes de Panamericana?',
  '¿Qué facturas presentan diferencias?', '¿Qué especialistas tuvieron una disminución de facturación frente al mes anterior?', '¿Qué clientes no tienen correo registrado?',
  '¿Qué facturas presentan posibles duplicados?', '¿Cuáles son las principales alertas de facturación del mes?'];
function iaRenderBienvenida() {
  const box = iaEl('iaMsgs'); if (!box || box.childElementCount) return;
  const nom = (currentProfile?.nombreCompleto || '').split(' ')[0];
  box.innerHTML = `<div class="ia-hello"><span class="ia-hello-ico"><i class="fa-solid fa-wand-magic-sparkles"></i></span><h4>Hola${nom ? ', ' + iaEsc(nom) : ''}</h4>
    <p>Pregúntame por la facturación, pagos, clientes o alertas. Respondo con los datos reales de BOE y te digo qué periodo y cuántos registros usé.</p>
    <div class="ia-sug">${IA_SUGERENCIAS.map(s => `<button onclick="iaPreguntar(this.textContent)">${iaEsc(s)}</button>`).join('')}</div></div>`;
}
function iaMd(t) {
  const lines = iaEsc(t).replace(/\*\*(.+?)\*\*/g, '<b>$1</b>').split('\n');
  let html = '', ul = false;
  lines.forEach(l => { const m = /^\s*(?:[-•*]|\d+[.)])\s+(.*)/.exec(l);
    if (m) { if (!ul) { html += '<ul>'; ul = true; } html += `<li>${m[1]}</li>`; }
    else { if (ul) { html += '</ul>'; ul = false; } html += l.trim() ? `<p>${l}</p>` : ''; } });
  return html + (ul ? '</ul>' : '');
}
function iaBurbuja(rol, html, cls = '') {
  const box = iaEl('iaMsgs'); box.querySelector('.ia-hello')?.remove();
  const d = document.createElement('div'); d.className = `ia-msg ${rol} ${cls}`; d.innerHTML = html; box.appendChild(d); box.scrollTop = box.scrollHeight; return d;
}
window.iaPreguntar = (t) => { const i = iaEl('iaInput'); i.value = t; iaEnviar(); };
window.iaTeclado = (ev) => { if (ev.key === 'Enter' && !ev.shiftKey) { ev.preventDefault(); iaEnviar(); } };
window.iaNuevaConversacion = () => { iaConv = []; const b = iaEl('iaMsgs'); if (b) b.innerHTML = ''; iaRenderBienvenida(); };
function iaRecortarConv() {
  const idx = []; iaConv.forEach((m, i) => { if (m.role === 'user') idx.push(i); });
  if (idx.length > 6) iaConv = iaConv.slice(idx[idx.length - 6]);
}
window.iaEnviar = async () => {
  const inp = iaEl('iaInput'); const texto = (inp.value || '').trim();
  const adj = iaEl('iaChatPdf')?.files?.[0];
  if (adj) { iaDesdeChat(texto, adj); inp.value = ''; return; }
  if (!texto || iaOcupado) return;
  if (jvIntencion(texto)) { inp.value = ''; return; }   // JARVIS resuelve sin IA: abrir, cargar, continuar, contar, exportar
  inp.value = ''; iaOcupado = true; iaEl('iaSend').disabled = true;
  iaBurbuja('user', iaEsc(texto));
  const pens = iaBurbuja('bot', '<span class="ia-dots"><i></i><i></i><i></i></span> <span class="ia-pens">Pensando…</span>', 'pensando');
  iaConv.push({ role: 'user', content: texto }); iaRecortarConv();
  const usadas = [];
  try {
    for (let paso = 0; paso < 6; paso++) {
      const j = await iaApi({ modo: 'chat', messages: iaConv, contexto: { usuario: currentProfile?.nombreCompleto || '', hoy: iaHoy(), secciones: iaSecciones() } });
      const m = j.message || {};
      if (m.tool_calls && m.tool_calls.length) {
        iaConv.push(m);
        m.tool_calls.forEach(tc => {
          let args = {}; try { args = JSON.parse(tc.function.arguments || '{}'); } catch (e) {}
          usadas.push(tc.function.name);
          pens.querySelector('.ia-pens').textContent = 'Consultando ' + (IA_HERR_TXT[tc.function.name] || 'BOE') + '…';
          let res; try { res = iaEjecutarHerramienta(tc.function.name, args); } catch (e) { res = { error: e.message }; }
          iaConv.push({ role: 'tool', tool_call_id: tc.id, content: JSON.stringify(res).slice(0, 14000) });
        });
        continue;
      }
      const txt = m.content || 'No obtuve respuesta.';
      iaConv.push({ role: 'assistant', content: txt });
      pens.remove();
      const fuentes = [...new Set(usadas)].map(u => IA_HERR_TXT[u] || u);
      iaBurbuja('bot', iaMd(txt) + (fuentes.length ? `<div class="ia-fuentes"><i class="fa-solid fa-database"></i> Datos de BOE: ${iaEsc(fuentes.join(' · '))}</div>` : ''));
      iaRegistrar('pregunta', texto, { herramientas: [...new Set(usadas)] });
      break;
    }
  } catch (e) {
    pens.remove(); iaBurbuja('bot', `<p><i class="fa-solid fa-circle-exclamation"></i> ${iaEsc(e.message)}</p>`, 'error');
    if (iaConv.length && iaConv[iaConv.length - 1].role === 'user') iaConv.pop();
  } finally { iaOcupado = false; iaEl('iaSend').disabled = false; }
};
/* PDF adjuntado en el chat: se toma doctor y periodo del texto y se abre la carga con esa selección */
window.iaAdjuntoChat = (inp) => {
  const f = inp.files?.[0]; const ch = iaEl('iaAdjChip');
  if (ch) { ch.style.display = f ? '' : 'none'; ch.querySelector('span').textContent = f ? f.name : ''; }
};
window.iaQuitarAdjunto = () => { const i = iaEl('iaChatPdf'); if (i) i.value = ''; iaAdjuntoChat(i || { files: [] }); };
function iaInterpretarDestino(texto) {
  const t = iaNorm(texto); let anio = null, mes = null, doc = null, mejor = 0;
  const ma = /\b(20\d{2})\b/.exec(t); if (ma) anio = Number(ma[1]);
  IA_MESES.forEach(m => { if (new RegExp('\\b' + m + '\\b').test(t)) mes = m; });
  doctors.forEach(d => { [d.nombre, d.especialista].filter(Boolean).forEach(n => {
    const pal = iaNorm(n).split(' ').filter(w => w.length > 2); const hit = pal.filter(w => t.includes(w)).length;
    if (hit >= Math.min(2, pal.length) && hit > mejor) { mejor = hit; doc = d; } }); });
  return { doctorId: doc ? doc.id : '', anio, mes };
}
function iaDesdeChat(texto, archivo) {
  const dst = iaInterpretarDestino(texto);
  if (texto) iaBurbuja('user', iaEsc(texto) + `<div class="ia-adj"><i class="fa-solid fa-file-pdf"></i> ${iaEsc(archivo.name)}</div>`);
  const falta = [!dst.doctorId && 'el doctor', !dst.mes && 'el mes', !dst.anio && 'el año'].filter(Boolean);
  iaBurbuja('bot', `<p>Abrí la carga de la factura con ${falta.length ? 'lo que entendí; selecciona ' + falta.join(', ') + ' antes de leerla' : 'el destino que indicaste. Revísalo y presiona <b>Leer factura con IA</b>'}.</p>`);
  iaCambiarTab('pdf');
  if (dst.doctorId) iaEl('iaPdfDoctor').value = dst.doctorId;
  if (dst.anio) iaEl('iaPdfAnio').value = String(dst.anio);
  if (dst.mes) iaEl('iaPdfMes').value = dst.mes;
  iaPdfAsignarArchivo(archivo);
  iaQuitarAdjunto();
}

/* ── Alertas ── */
function iaRenderAlertas() {
  const box = iaEl('iaAlertasBox'); if (!box) return;
  const r = iaResumen(iaAlertasLista);
  const tipos = Object.keys(IA_TIPOS).filter(t => r.tipos[t]);
  if (iaFiltroTipo !== 'todas' && !r.tipos[iaFiltroTipo]) iaFiltroTipo = 'todas';
  const l = iaAlertasLista.filter(a => iaFiltroTipo === 'todas' || a.tipo === iaFiltroTipo);
  const sinAcc = ['reportes', 'egresos', 'doctores'].filter(v => !puedeVer(v));
  const regHtml = (x) => {
    const abrir = x.col === 'egresos' ? `iaAbrirRegistro('egresos','${iaEsc(x.id)}')` : x.col === 'doctors' ? `iaAbrirRegistro('doctors','${iaEsc(x.id)}')` : x.col === 'facturas' ? `iaAbrirRegistro('facturas','')` : '';
    return `<li>${abrir ? `<a onclick="${abrir}">` : '<span>'}${iaEsc(x.etiqueta)}${abrir ? ' <i class="fa-solid fa-arrow-up-right-from-square"></i></a>' : '</span>'}</li>`;
  };
  box.innerHTML = `<div class="ia-al-kpis">
      <div class="ia-kpi alta"><b>${r.alta}</b><span>Alta</span></div><div class="ia-kpi media"><b>${r.media}</b><span>Media</span></div><div class="ia-kpi baja"><b>${r.baja}</b><span>Baja</span></div>
    </div>
    <div class="ia-al-fil"><button class="${iaFiltroTipo === 'todas' ? 'on' : ''}" onclick="iaFiltrarAlertas('todas')">Todas <em>${r.total}</em></button>${tipos.map(t => `<button class="${iaFiltroTipo === t ? 'on' : ''}" onclick="iaFiltrarAlertas('${t}')">${IA_TIPOS[t]} <em>${r.tipos[t]}</em></button>`).join('')}</div>
    <div class="ia-al-explica">${iaExplicacion ? `<div class="ia-exp">${iaExplicacion}</div>` : `<button class="btn btn-ghost btn-sm" onclick="iaExplicarAlertas()" ${r.total ? '' : 'disabled'}><i class="fa-solid fa-wand-magic-sparkles"></i> Explicar y priorizar con IA</button>`}</div>
    ${sinAcc.length ? `<div class="ia-nota"><i class="fa-solid fa-lock"></i> No se revisaron las secciones sin acceso: ${sinAcc.map(v => ({ reportes: 'Reportes', egresos: 'UROEXPERTOS', doctores: 'Clientes' }[v])).join(', ')}.</div>` : ''}
    ${l.length ? l.slice(0, 150).map((a, i) => `<div class="ia-al ${a.prioridad}">
      <div class="ia-al-top"><span class="ia-pri ${a.prioridad}">${iaCap(a.prioridad)}</span><span class="ia-al-tipo">${IA_TIPOS[a.tipo] || a.tipo}</span>${a.valor != null && a.valor !== 0 ? `<span class="ia-al-val">${iaFmt(Math.abs(a.valor))}</span>` : ''}</div>
      <h5>${iaEsc(a.titulo)}</h5><p>${iaEsc(a.que)}</p>
      <details><summary>Por qué y qué hacer · ${a.registros.length} registro(s)</summary>
        <div class="ia-al-det"><div><b>Por qué:</b> ${iaEsc(a.porque)}</div><div><b>Acción recomendada:</b> ${iaEsc(a.accion)}</div>
        <ul class="ia-al-regs">${a.registros.slice(0, 12).map(regHtml).join('')}${a.registros.length > 12 ? `<li class="mas">y ${a.registros.length - 12} más…</li>` : ''}</ul></div></details>
    </div>`).join('') + (l.length > 150 ? `<div class="ia-nota">Se muestran 150 de ${l.length} alertas.</div>` : '')
    : `<div class="ia-vacio"><i class="fa-solid fa-circle-check"></i><b>Sin alertas</b><span>Las reglas no encontraron anomalías con los datos actuales.</span></div>`}`;
}
window.iaFiltrarAlertas = (t) => { iaFiltroTipo = t; iaRenderAlertas(); };
window.iaAbrirRegistro = (col, id) => {
  iaCerrarPanel();
  if (col === 'egresos') { navigate('egresos'); setTimeout(() => { try { openEgresoModal(id); } catch (e) {} }, 350); }
  else if (col === 'doctors') { navigate('doctores'); setTimeout(() => { try { openDoctorModal(id); } catch (e) {} }, 300); }
  else if (col === 'facturas') navigate('reportes');
};
window.iaExplicarAlertas = async () => {
  const box = document.querySelector('#iaAlertasBox .ia-al-explica'); if (!box) return;
  box.innerHTML = '<div class="ia-exp"><span class="ia-dots"><i></i><i></i><i></i></span> Analizando las alertas…</div>';
  const firma = iaAlertasFirma;
  try {
    const top = iaAlertasLista.slice(0, 25).map(a => ({ prioridad: a.prioridad, tipo: a.tipo, titulo: a.titulo, que: a.que, valor: a.valor != null ? iaFmt(a.valor) : null }));
    const j = await iaApi({ modo: 'chat', contexto: { usuario: currentProfile?.nombreCompleto || '', hoy: iaHoy(), secciones: iaSecciones() },
      messages: [{ role: 'user', content: 'Estas son las alertas calculadas por las reglas de BOE (posibles anomalías, no errores confirmados). En máximo 6 viñetas: qué revisar primero y por qué. No inventes datos que no estén aquí.\n' + JSON.stringify({ resumen: iaResumen(iaAlertasLista), alertas: top }) }] });
    if (firma === iaAlertasFirma) iaExplicacion = iaMd(j.message?.content || 'Sin respuesta.');
    iaRegistrar('explicar_alertas', `${iaAlertasLista.length} alertas`);
    iaRenderAlertas();
  } catch (e) { box.innerHTML = `<div class="ia-exp error"><i class="fa-solid fa-circle-exclamation"></i> ${iaEsc(e.message)}</div>`; }
};

