  let dupFichas = []; try { const noms = new Set((e.hijas || []).map(h => cliDoctorDeEspecialista(h.nombre)?.id).filter(Boolean)); dupFichas = cliPosiblesDuplicados().filter(p => noms.has(p.prin.id) || noms.has(p.sec.id)).map(p => `fichas duplicadas: «${p.prin.especialista || p.prin.nombre}» y «${p.sec.especialista || p.sec.nombre}»`); } catch (x) {}
