  if (!egresoId) { toast('Guarda la factura a la entidad antes de generar la orden.', 'error'); return; }
  const e = egresos.find(x => x.id === egresoId);
  const abs = (e?.abonos || []).filter(a => (Number(a.monto)||0) > 0);
  if (!abonoId) abonoId = abs[abs.length - 1]?.id;
  if (!abonoId || !abs.some(a => a.id === abonoId)) { toast('No hay abonos guardados. Registra el abono y guarda la factura.', 'error'); return; }
  if (localAbonos.some(a => egmEsNuevo(a) && Number(a.monto) > 0)) { toast('Hay abonos sin guardar: guarda la factura a la entidad primero.', 'error'); return; }
  _opCtx = { egresoId, abonoId };
  document.getElementById('opFechaPago').value = uroHoyLocal();
