    lineas.forEach(l => { const k = l.d ? l.d.id : 'x:' + (l.cedula || l.especialista + l.fila); const g = grupos.get(k) || { d: l.d, cedula: l.cedula, especialista: l.d?.especialista || l.especialista, lineas: [] }; g.lineas.push(l); grupos.set(k, g); });
    const liqs = [...grupos.values()].map(g => ({ ...g, valorEntidad: g.lineas.reduce((t, l) => t + l.valorEntidad, 0), admin: g.lineas.reduce((t, l) => t + l.valorEntidad - l.valorEspecialista, 0),
      valorEspecialista: g.lineas.reduce((t, l) => t + l.valorEspecialista, 0), glosa: g.lineas.reduce((t, l) => t + l.glosa, 0), otros: g.lineas.reduce((t, l) => t + l.otros, 0),
      facturas: [...new Set(g.lineas.map(l => l.factEsp).filter(Boolean))] }));
    const sumE = liqs.reduce((t, l) => t + l.valorEntidad, 0), sumA = liqs.reduce((t, l) => t + l.admin, 0), sumS = liqs.reduce((t, l) => t + l.valorEspecialista, 0);
    const errores = [], avisos = [];
