    if (!lineas.length) errores.push('No tiene filas en LIQUIDACIONES');
    if (Math.abs(sumE - f.valor) > 2) errores.push(`Liquidaciones ${fmtCOP(sumE)} ≠ valor facturado ${fmtCOP(f.valor)} (diferencia ${fmtCOP(sumE - f.valor)})`);
    const malLinea = lineas.filter(l => Math.abs(l.admin + l.valorEspecialista - l.valorEntidad) > 2);
    if (malLinea.length) errores.push(`Administración + especialista ≠ valor entidad en ${malLinea.length} línea(s) (filas ${malLinea.map(l => l.fila).join(', ')})`);
    const sinCed = lineas.filter(l => !l.d);
    if (sinCed.length) errores.push(`${sinCed.length} línea(s) sin especialista en Clientes por cédula: ${sinCed.map(l => `${l.especialista || 'sin nombre'} (${l.cedula || 'sin cédula'})`).join(', ')}`);
    if (lineas.some(l => l.otros)) avisos.push('Trae «otros descuentos»: regístralos en la liquidación (se guardan en el detalle)');
    const existe = piExistente(f, ent);
