      const base = { fechaFacturacion: p.f.fecha, honorarioMes: p.f.mes, concepto: p.f.concepto || p.f.tipo, nombre: p.ent.razonSocial, entidadId: p.ent.id, entidadNit: p.ent.nit || '', entidadDv: p.ent.dv || '',
        factura: p.f.numero, valorEntidad: p.f.valor, ica: p.f.ica, reteHonorarios: ret, notaCredito: p.f.glosa, valorEntidadNeto: neto, tipoFactura: p.f.tipo,
        importId: p.f.id, importArchivo: _piArchivo?.nombre || p.f.archivo || '', importadoPor: por, importadoISO: ahora };
      let egresoId;
      if (!p.existe) {
        const hijas = p.liqs.map(l => piHija(p, l, null));
        const ref = await addDoc(collection(db,'egresos'), { ...base, administracion: p.sumA, valorEspecialista: p.sumS, hijas, abonos: [], fechaPago: '', notas: '', createdAt: serverTimestamp(), updatedAt: serverTimestamp() });
        egresoId = ref.id;
        await segHistorial(egresoId, [{ accion: 'Importó desde plantilla', campo: 'Factura a la entidad', despues: `${p.f.numero || p.f.id} · ${fmtCOP(p.f.valor)} · ${hijas.length} liquidaciones`, motivo: _piArchivo?.nombre || '' }]);
      } else {
        egresoId = p.existe.id;
        const previas = [...(p.existe.hijas || [])], usadas = new Set();
        const hijas = previas.map(h => { const l = p.liqs.find(x => _nrm(x.especialista) === _nrm(h.nombre)); if (!l) return h; usadas.add(l); return piHija(p, l, h); });
        p.liqs.filter(l => !usadas.has(l)).forEach(l => hijas.push(piHija(p, l, null)));
        const data = { ...base, administracion: hijas.reduce((t, h) => t + (Number(h.administracion) || 0), 0), valorEspecialista: hijas.reduce((t, h) => t + (Number(h.valorEspecialista) || 0), 0), hijas, updatedAt: serverTimestamp() };
        const cambios = segDiferencias(p.existe, { ...p.existe, ...data });
        // la liquidación sigue a las liquidaciones (9.7) con la misma transacción que la factura
        const guardaAb = localAbonos, guardaQ = _abonosQuitados; localAbonos = []; _abonosQuitados = [];
        try { const ops = egmOperacionesLiquidacion(egresoId, new Map(), hijas);
          if (ops.length) await egmGuardarConLiquidacion(egresoId, data, ops); else await updateDoc(doc(db,'egresos', egresoId), data); }
        finally { localAbonos = guardaAb; _abonosQuitados = guardaQ; }
        await segHistorial(egresoId, [{ accion: 'Actualizó desde plantilla', campo: 'Factura a la entidad', despues: p.f.id }, ...cambios], `Importación ${_piArchivo?.nombre || ''}`);
      }
      // el archivo importado queda como soporte de la factura
      if (_piArchivo) { try { await opGuardarArchivo(_piArchivo.blob, _piArchivo.nombre, { id: egresoId, factura: p.f.numero }, 'importacion'); } catch (eA) { errores.push(`${p.f.id}: la factura quedó, pero no se guardó el archivo como soporte (${eA.message})`); } }
